INSERT INTO `driving_category` VALUES (1, 'AM', 'mopedi, laki tricikli i laki četvorocikli');
INSERT INTO `driving_category` VALUES (2, 'A1', 'Motocikli zapremine do 125 cm3 i snage motora do 11kW, čiji odnos snage motora i mase vozila nije veći od 0,1 kW/kg i teški tricikli snage motora do 15kW');
INSERT INTO `driving_category` VALUES (3, 'A2', 'Motocikli čija snaga motora nije veća od 35kW i čiji odnos snage motora i mase vozila nije veći od 0,2 kW/kg');
INSERT INTO `driving_category` VALUES (4, 'A', 'Motocikli i teški tricikli čija snaga motora prelazi 35kW');
INSERT INTO `driving_category` VALUES (5, 'B1', 'Teški četvorocikli');
INSERT INTO `driving_category` VALUES (6, 'B', 'Motorna vozila, osim vozila kategorije A, A1, A2, AM, F i M, čija dozvoljena masa nije veća od 3500kg i koja nemaju više od osam sedišta ne računajući sedište za vozača');
INSERT INTO `driving_category` VALUES (7, 'BE', 'Skup vozila čije vučno vozilo pripada kategoriji B, najveća dozvoljena masa priključnog vozila je veća od 750 kg, a nije veća od 3500 kg');
INSERT INTO `driving_category` VALUES (8, 'C1', 'Motorna vozila, osim vozila kategorije A, A1, A2, AM, F, M, B, D i D1, čija je najveća dozvoljena masa veća od 3500 kg, a nije veća od 7500 kg');
INSERT INTO `driving_category` VALUES (9, 'C1E', 'Skup vozila čije vučno vozilo spada u kategoriju C1, a najveća dozvoljena masa priključnog vozila prelazi 750 kg i naveća dozvoljena masa skupa ne prelazi 12.000 kg, kao i skup vozila čije vučno vozilo spada u kategoriju B, a najveća dozvoljena masa priključnog vozila prelazi 3.500 kg i najveća dozvoljena masa skupa vozila ne prelazi 12.000 kg');
INSERT INTO `driving_category` VALUES (10, 'C', 'Motorna vozila, osim kategorije A, A1, A2, AM, F, M, B, D i D1, čija je najveća dozvoljena masa veća od 3.500 kg');
INSERT INTO `driving_category` VALUES (11, 'CE', 'Skup vozila čije vučno vozilo pripada kategoriji C, a najveća dozvoljena masa priključnog vozila je veća od 750 kg');
INSERT INTO `driving_category` VALUES (12, 'D1', 'Motorna vozila za prevoz lica, koja osim sedišta za vozača imaju više od osam, a najviše 16 sedišta i čija maksimalna dužina ne prelazi osam metara');
INSERT INTO `driving_category` VALUES (13, 'D1E', 'Skup vozila čije vučno vozilo pripada kategoriji D1, a najveća dozvoljena masa priključnog vozila je veća od 750 kg');
INSERT INTO `driving_category` VALUES (14, 'D', 'Motorna vozila za prevoz lica, koja osim sedišta za vozača imaju više od osam sedišta');
INSERT INTO `driving_category` VALUES (15, 'DE', 'Skup vozila čije vučno vozilo pripada kategoriji D, a najveća dozvoljena masa priključnog vozila je veća od 750 kg');
INSERT INTO `driving_category` VALUES (16, 'F', 'Traktori sa ili bez priključnih vozila i radne mašine');
INSERT INTO `driving_category` VALUES (17, 'M', 'Motokultivator');
