INSERT INTO `kad_absence_subtype` VALUES (1, 1, NULL, 20, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, 'Zaposleni ostvaruje pravo na pun odmor ukoliko mu radni odnos traje cele kalendarske godine, u trajanju od najmanje 20 radnih dana koji se uvećavaju za kriterijume propisane opštim aktom i ugovorom o radu. Za svaki navršeni mesec rada, u kalendarskoj godini u kojoj mu radni odnos počinje ili prestaje, ostvaruje pravo na dvanaestinu punog odmora (srazmerni godišnji odmor). #Član 69 i 72. Zakona o radu', 1, '2021-04-16 11:00:55', '2021-04-16 11:00:55', 0, 1, 1, 1);
INSERT INTO `kad_absence_subtype` VALUES (2, 2, 'Sklapanje braka', 1, NULL, 5, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, 'Zaposleni ima pravo na plaćeno odsustvo u ukupnom trajanju do pet radnih dana u toku kalendarske godine, u slučaju sklapanja braka, porođaja supruge, teže bolesti člana uže porodice i u drugim slučajevima utvrđenim opštim aktom i ugovorom o radu, a samo vreme trajanje odsustva u ovim grupnim slučajevima utvrđuje se opštim aktom i ugovorom o radu. # član 77 Zakona o radu', 1, '2021-04-16 11:00:55', '2021-04-16 11:00:55', 0, 1, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (3, 2, 'Porođaj supruge/vanbračnog partnera', 1, NULL, 5, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, 'Zaposleni ima pravo na plaćeno odsustvo u ukupnom trajanju do pet radnih dana u toku kalendarske godine, u slučaju sklapanja braka, porođaja supruge, teže bolesti člana uže porodice i u drugim slučajevima utvrđenim opštim aktom i ugovorom o radu, a samo vreme trajanje odsustva u ovim grupnim slučajevima utvrđuje se opštim aktom i ugovorom o radu. # član 77 Zakona o radu', 1, '2021-04-16 11:00:55', '2021-04-16 11:00:55', 0, 1, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (4, 2, 'Teža bolest člana uže prodice', 1, NULL, 5, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, 'Zaposleni ima pravo na plaćeno odsustvo u ukupnom trajanju do pet radnih dana u toku kalendarske godine, u slučaju sklapanja braka, porođaja supruge, teže bolesti člana uže porodice i u drugim slučajevima utvrđenim opštim aktom i ugovorom o radu, a samo vreme trajanje odsustva u ovim grupnim slučajevima utvrđuje se opštim aktom i ugovorom o radu. # član 77 Zakona o radu', 1, '2021-04-16 11:00:56', '2021-04-16 11:00:56', 0, 1, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (5, 2, 'Teža bolest srodnika ili lica sa kojima živi u zajedničkom domaćinstvu', 1, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, 'Poslodavac može da odobri zaposlenom odsustvo u slučaju teže bolesti ili smrti i za srodnike koji nisu navedeni kao članovi uže porodice (bračni drug, deca, braća, sestre, roditelji, usvojilac, usvojenik i staratelj) i za druga lica koja žive u zajedničkom porodičnom domaćinstvu sa zaposlenim, u trajanju utvrđenom rešenjem poslodavca. #član 77 Zakona o radu', 1, '2021-04-16 11:00:56', '2021-04-16 11:00:56', 0, 1, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (6, 2, 'Smrt člana uže porodice', 1, NULL, 5, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, 'Zaposleni ima pravo na plaćeno odsustvo pet radnih dana zbog smrti člana uže porodice. #član 77 Zakona o radu', 1, '2021-04-16 11:00:56', '2021-04-16 11:00:56', 0, 1, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (7, 2, 'Smrt srodnika ili lica sa kojima živi u zajedničkom domaćinstvu', 1, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, 'Poslodavac može da odobri zaposlenom odsustvo u slučaju teže bolesti ili smrti i za srodnike koji nisu navedeni kao članovi uže porodice (bračni drug, deca, braća, sestre, roditelji, usvojilac, usvojenik i staratelj) i za druga lica koja žive u zajedničkom porodičnom domaćinstvu sa zaposlenim, u trajanju utvrđenom rešenjem poslodavca. #član 77 Zakona o radu', 1, '2021-04-16 11:00:56', '2021-04-16 11:00:56', 0, 1, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (8, 2, 'Dobrovoljno davanje krvi', 1, NULL, 2, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, 'Zaposleni ima pravo na plaćeno odsustvo dva uzastopna dana za svaki slučaj dobrovoljnog davanja krvi računajući i dan davanja krvi. #član 77 Zakona o radu', 1, '2021-04-16 11:00:56', '2021-04-16 11:00:56', 0, 1, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (9, 3, 'Odsustvo na dan praznika u skladu sa Zakonom o državnim i drugim praznicima', 1, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, 'U dane državnih i verskih praznika koji se praznuju u Republici Srbiji ne rade državni i drugi organi, privredna društva i drugi oblici organizovanja za obavljanje delatnosti ili usluga, osim na Dan pobede koji se praznuje radno. Dani državnih i verskih praznika utvrđuju se Zakonom o državnim i drugim praznicima u Republici Srbiji #član 1, 1a i 2 Zakona o državnim i drugim praznicima u Republici Srbiji', 1, '2021-04-16 11:00:56', '2021-04-16 11:00:56', 0, 0, 1, 0);
INSERT INTO `kad_absence_subtype` VALUES (10, 3, 'Odsustvo po osnovu veroispovesti (pravoslavne, katoličke, islamske i jevrejske)', 1, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, 'Zaposleni pravoslavci, katolici i pripradnici drugih hriščanskih zajednica, pripadnici islamske i jevrejske verske zajednice imaju pravo na odsustvo u dane tačno određenih verskih praznika. #član 4. Zakona o državnim i drugim praznicima u Republici Srbiji.', 1, '2021-04-16 11:00:56', '2021-04-16 11:00:56', 0, 0, 1, 0);
INSERT INTO `kad_absence_subtype` VALUES (11, 4, 'Vojna vežba', 1, NULL, 90, NULL, 0, 2, NULL, NULL, NULL, NULL, NULL, 'Pored mogućnosti da građani dobrovoljno služe vojni rok sa oružjem u Vojsci Srbije, predviđeno je da lica u rezervnom sastavu mogu biti pozivana na vojne vežbe i vežbe civilne zaštite i to najviše do 90 dana u toku jedne godine. Za vreme vojne vežbe, zaposleni ima pravo na naknadu zarade u visini svoje prosečne zarade u prethodnih 12 meseci, u skladu sa opštim aktom i ugovorom o radu. #Zakon o vojnoj, radnoj i materijalnoj obavezi #član 114 Zakona o radu', 0, '2021-04-16 11:00:56', '2021-04-16 11:00:56', 1, 0, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (12, 4, 'Odazivanje na poziv državnog organa', 1, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, 'Zaposleni ima pravo na naknadu zarade u visini prosečne zarade u prethodnih 12 meseci, u skladu sa opštim aktom i ugovorom o radu, za vreme odsustvovanja sa zbog odazivanja na poziv državnog organa, a poslodavac ima pravo na refundiranje isplaćene naknade u slučaju odazivanja na poziv državnog organa, od organa na čiji se poziv zaposleni odazvao, ako zakonom nije drukčije određeno. #član 114. Zakona o radu', 0, '2021-04-16 11:00:57', '2021-04-16 11:00:57', 1, 0, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (13, 5, 'Usled prekida rada ili smanjenog obima posla bez krivice zaposlenog (član 116. Zakona o radu)', 1, NULL, 45, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, 'Odsustvo usled prekida rada ili smanjenog obima posla, do kog je došlo bez krivice zaposlenog, može trajati duže od 45 radnih dana samo uz saglasnost Ministarstva rada, zapošljavanja, boračkih i socijalnih pitanja. #član 116. Zakona o radu', 1, '2021-04-16 11:00:57', '2021-04-16 11:00:57', 0, 0, 1, 1);
INSERT INTO `kad_absence_subtype` VALUES (14, 5, 'Usled neobezbeđivanja bezbednih i zdravih uslova za rad (član 117. stav 1. Zakona o radu)', 1, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, 'Zaposleni ima pravo na naknadu zarade u visini utvrđenoj opštim aktom i ugovorom o radu za vreme prekida rada do koga je došlo naredbom nadležnog državnog organa ili nadležnog organa poslodavca zbog neobezbeđivanja bezbednosti i zaštite života i zdravlja na radu, koja je uslov daljeg obavljanja rada bez ugrožavanja života i zdravlja zaposlenih i drugih lica, i u drugim slučajevima, u skladu sa zakonom. #član 117. Zakona o radu', 1, '2021-04-16 11:00:57', '2021-04-16 11:00:57', 0, 0, 1, 1);
INSERT INTO `kad_absence_subtype` VALUES (15, 6, 'Odobreno od strane poslodavca (član 78. Zakona o radu)', 1, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, 'Poslodavac može da odobri zaposlenom zahtev za neplaćenim odsustvom ako nađe da je takav zahtev opravdan i da ne remeti proces rada. Za vreme odsustva bez naknade zarade, zaposlenom miruju sva prava i obaveze po osnovu rada, ako za pojedina nije drugačije određeno zakonom, opštim aktom i ugovorom o radu. #član 78. Zakona o radu', 1, '2021-04-16 11:00:57', '2021-04-16 11:00:57', 0, 1, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (16, 6, 'Zbog nege deteta do tri godine starosti (član 100. Zakona o radu)', 1, NULL, NULL, 36, 0, 2, NULL, NULL, NULL, NULL, NULL, 'Jedan od roditelja, usvojilac, hranitelj, odnosno staratelj ima pravo da odsustvuje sa rada dok dete ne navrši tri godine života, a za vreme kog prava i obaveze po osnovu rada miruju, ako za pojedina prava zakonom, opštim aktom i ugovorom o radu nije drukčije određeno. #član 100. Zakona o radu', 1, '2021-04-16 11:00:57', '2021-04-16 11:00:57', 1, 0, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (17, 6, 'Neopravdani izostanak', NULL, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, 'Radno vreme je vremenski period u kome je zaposleni dužan, odnosno raspoloživ da obavlja poslove prema nalozima poslodavca, na mestu gde se poslovi obavljaju, u skladu sa zakonom. Ukoliko zaposleni odsustvuje sa rada u radno vreme, a za njegovo odsustvo nema osnova (nije odobreno od strane poslodavca, nema doznaka ukoliko je reč o bolovanju), već je reč o samovolji zaposlenog, radi se o neopravdanom odsustvu za vreme kog zaposlenom ne pripada naknada zarade. #član 50. Zakona o radu', 1, '2021-04-16 11:00:57', '2021-04-16 11:00:57', 0, 0, 1, 1);
INSERT INTO `kad_absence_subtype` VALUES (18, 7, 'Porodiljsko odsustvo', 1, NULL, 45, 3, NULL, 2, NULL, NULL, NULL, NULL, NULL, 'Zaposlena žena ima pravo da otpočne porodiljsko odsustvo na osnovu nalaza nadležnog zdravstvenog organa najranije 45 dana, a obavezno 28 dana pre vremena određenog za porođaj, a koje traje do navršena tri meseca od dana porođaja. #član 94 Zakona o radu.', 0, '2021-04-16 11:00:57', '2021-04-16 11:00:57', 1, 0, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (19, 7, 'Odsustvo sa rada radi nege deteta', 1, NULL, NULL, NULL, NULL, 2, NULL, NULL, NULL, NULL, NULL, 'Zaposlena žena ima pravo na porodiljsko odsustvo , kao i odsustvo sa rada radi nege deteta, u ukupnom trajanju od 365 dana, a za treće i svako naredno rođeno dete ukupno trajanje odsustva je 2 godine. Pravo na naknadu zarade utvrđeno je odredbama Zakona o finansijskoj podršci porodici sa decom. #član 94 i 94a Zakona o radu', 0, '2021-04-16 11:00:57', '2021-04-16 11:00:57', 1, 0, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (20, 7, 'Porodiljsko odsustvo i odsustvo sa rada radi nege deteta', NULL, 3, NULL, 12, NULL, 2, NULL, NULL, NULL, NULL, NULL, 'Zaposlena žena ima pravo na porodiljsko odsustvo , kao i odsustvo sa rada radi nege deteta, u ukupnom trajanju od 365 dana, a za treće i svako naredno rođeno dete ukupno trajanje odsustva je 2 godine. Pravo na naknadu zarade utvrđeno je odredbama Zakona o finansijskoj podršci porodici sa decom. #član 94 i 94a Zakona o radu', 0, '2021-04-16 11:00:57', '2021-04-16 11:00:57', 1, 0, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (21, 7, 'Odsustvo sa rada radi posebne nege deteta', 1, NULL, NULL, 60, NULL, 2, NULL, NULL, NULL, NULL, NULL, 'Jedan od roditelja deteta kome je neophodna posebna nega zbog teškog stepena psihofizičke ometenosti, osim za slučajeve predviđene propisima o zdravstvenom osiguranju, ima pravo da, po isteku porodiljskog odsustva i odsustva sa rada radi nege deteta, odsustvuje sa rada ili da radi sa polovinom punog radnog vremena, najduže do navršenih pet godina života deteta. Pravo na naknadu zarade utvrđeno je odredbama Zakona o finansijskoj podršci porodici sa decom. #član 96.  Zakona o radu', 0, '2021-04-16 11:00:57', '2021-04-16 11:00:57', 1, 0, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (22, 7, 'Odsustvo hranitelja, odnosno staratelja radi nege deteta mlađeg od pet godina života', 1, NULL, NULL, 8, NULL, 2, NULL, NULL, NULL, NULL, NULL, 'Lice kome je, u skladu sa propisima o usvojenju, upućeno dete na prilagođavanje pre zasnivanja usvojenja, a po zasnivanju usvojenja - i jedan od usvojilaca, kao i hranitelj, odnosno staratelj deteta mlađeg od pet godina života ima pravo da, radi nege deteta, odsustvuje sa rada osam meseci neprekidno od dana smeštaja deteta u hraniteljsku, odnosno starateljsku porodicu, a najduže do navršenih pet godina života deteta. Naknadu zarade ostvaruje u skladu sa odredbama Zakona o finansijskoj podršci porodici sa decom. #član 97. Zakona o radu', 0, '2021-04-16 11:00:58', '2021-04-16 11:00:58', 1, 0, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (23, 7, 'Odsustvo hranitelja odnosno staratelja u slučaju smeštaja u hraniteljsku odnosno starateljsku porodicu pre navršena tri meseca života deteta', 1, NULL, NULL, 11, NULL, 2, NULL, NULL, NULL, NULL, NULL, 'Ako je smeštaj u hraniteljsku, odnosno starateljsku porodicu nastupio pre navršena tri meseca života deteta, lice kome je, u skladu sa propisima o usvojenju, upućeno dete na prilagođavanje pre zasnivanja usvojenja, a po zasnivanju usvojenja - i jedan od usvojilaca, kao i hranitelj, odnosno staratelj deteta ima pravo da, radi nege deteta, odsustvuje sa rada do navršenih 11 meseci života deteta. Naknadu zarade ostvaruje u skladu sa odredbama Zakona o finansijskoj podršci porodici sa decom. #član 97. Zakona o radu', 0, '2021-04-16 11:00:58', '2021-04-16 11:00:58', 1, 0, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (24, 8, 'Usled povrede ili bolesti van rada', 1, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2021-04-16 11:00:58', '2021-04-16 11:00:58', 1, 0, 0, 0);
INSERT INTO `kad_absence_subtype` VALUES (25, 8, 'Usled povrede ili bolesti na radu', 1, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, NULL, 0, '2021-04-16 11:00:58', '2021-04-16 11:00:58', 1, 0, 0, 0);
INSERT INTO `kad_absence_subtype` VALUES (26, 8, 'Zbog bolesti ili komplikacija u vezi sa održavanjem trudnoće', 1, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2021-04-16 11:00:58', '2021-04-16 11:00:58', 1, 0, 0, 0);
INSERT INTO `kad_absence_subtype` VALUES (27, 8, 'Zbog propisane mere obavezne izolacije kao kliconoše ili zbog pojave zaraznih bolesti u njegovoj okolini', 1, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2021-04-16 11:00:58', '2021-04-16 11:00:58', 1, 0, 0, 0);
INSERT INTO `kad_absence_subtype` VALUES (28, 8, 'Zbog nege bolesnog, odnosno povređenog člana uže porodice, pod uslovima utvrđenim Zakonom o zdravstvenom osiguranju', 1, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2021-04-16 11:00:58', '2021-04-16 11:00:58', 1, 0, 0, 0);
INSERT INTO `kad_absence_subtype` VALUES (29, 8, 'Zbog dobrovoljnog davanja organa, ćelija i tkiva, izuzev dobrovoljnog davanja krvi', 1, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2021-04-16 11:00:58', '2021-04-16 11:00:58', 1, 0, 0, 0);
INSERT INTO `kad_absence_subtype` VALUES (30, 8, 'U slučaju kada je određen za pratioca bolesnog osiguranog lica upućenog na lečenje ili lekarski pregled u drugo mesto, odnosno dok boravi kao pratilac u stacionarnoj zdravstvenoj ustanovi', 1, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2021-04-16 11:00:58', '2021-04-16 11:00:58', 1, 0, 0, 0);
INSERT INTO `kad_absence_subtype` VALUES (31, 9, 'Usled odlaska na odsluženje vojnog roka', 1, NULL, NULL, 6, 0, 2, NULL, NULL, NULL, NULL, NULL, 'Građani dobrovoljno služe vojni rok sa oružjem u Vojsci Srbijeu trajanju od 6 šest meseci. Zaposlenom miruju prava i obaveze po osnovu rada za vreme odsluženja vojnog roka, osim ako za pojedina prava zakonom, opštim aktom ili ugovorom o radu nije drukčije određeno. #Zakon o vojnoj, radnoj i materijalnoj obavezi #član 79 Zakona o radu', 0, '2021-04-16 11:00:58', '2021-04-16 11:00:58', 1, 0, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (32, 9, 'Usled upućivanja na rad u inostranstvo od strane poslodavca ili u okviru međunarodno-tehničke ili prosvetno-kulturne saradnje, u diplomatska, konzularna i druga predstavništva', 1, NULL, NULL, 12, 0, 2, NULL, NULL, NULL, NULL, NULL, 'Poslodavac može zaposlenog da uputi na privremeni rad u inostranstvo do 12 meseci sa mogućnošću produženja, ako zakonom ili međunarodnim ugovorom nije drukčije određeno. #Zakon o uslovima za upućivanje zaposlenih na privremeni rad u inostranstvo i njihovoj zaštiti', 0, '2021-04-16 11:00:58', '2021-04-16 11:00:58', 1, 0, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (33, 9, 'Usled privremenog upućivanja na rad kod drugog poslodavca u smislu člana 174. ovog zakona', 1, NULL, NULL, 12, 0, 2, NULL, NULL, NULL, NULL, NULL, 'Zaposleni može da bude privremeno upućen na rad kod drugog poslodavca na odgovarajući posao najduže godinu dana ako je - 1) privremeno prestala potreba za njegovim radom, 2) dat u zakup poslovni prostor ili 3) zaključen ugovor o poslovnoj saradnji. Upućivanje može trajati i duže samo uz saglasnost zaposlenog i u drugim slučajevima utvrđenim opštim aktom ili ugovorom o radu. #član 174. Zakona o radu', 0, '2021-04-16 11:00:58', '2021-04-16 11:00:58', 0, 0, 1, 1);
INSERT INTO `kad_absence_subtype` VALUES (34, 9, 'Usled izbora, odnosno imenovanja na funkciju u državnom organu, sindikatu, političkoj organizaciji ili drugu javnu funkciju čije vršenje zahteva da privremeno prestane da radi kod poslodavca', 1, NULL, NULL, 48, 0, 2, NULL, NULL, NULL, NULL, NULL, 'Najčešće mandat traje četiri godine, ali trajanje mandata zavisi od konkretne funkcije koju će lice (zaposleni) obavljati.', 0, '2021-04-16 11:00:59', '2021-04-16 11:00:59', 1, 0, 1, 1);
INSERT INTO `kad_absence_subtype` VALUES (35, 9, 'Usled izdržavanja kazne zatvora, odnosno izrečene mere bezbednosti, vaspitne ili zaštitne mere, u trajanju do šest meseci', 1, NULL, NULL, 6, 0, 2, NULL, NULL, NULL, NULL, NULL, 'Zaposlenom miruju prava i obaveze koje se stiču na radu i po osnovu rada, ako odsustvuje sa rada zbog izdržavanja kazne zatvora, odnosno izrečene mere bezbednosti, vaspitne ili zaštitne mere, u trajanju do šest meseci. Za pojedina prava i obaveze zakonom, opštim aktom, odnosno ugovorom o radu može biti drukčije određeno. #Član 79. Zakona o radu', 0, '2021-04-16 11:00:59', '2021-04-16 11:00:59', 1, 0, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (36, 9, 'Za vreme trajanja postupka pred arbitrom zbog otkaza ugovora o radu', 1, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, 'Opštim aktom i ugovorom o radu može se predvideti postupak sporazumnog rešavanja spornih pitanja između poslodavca i zaposlenog pred arbitrom. Rok za pokretanje postupka pred arbitrom jeste tri dana od dana dostavljanja rešenja zaposlenom, a arbitar je dužan da donese odluku u roku od 10 dana od dana podnošenja zahteva za sporazumno rešavanje spornih pitanja. #član 194. Zakona o radu', 0, '2021-04-16 11:00:59', '2021-04-16 11:00:59', 0, 1, 1, 1);
INSERT INTO `kad_absence_subtype` VALUES (37, 10, 'Zaposlenog protiv kog je započeto krivično gonjenje zbog krivičnog dela učinjenog na radu ili u vezi sa radom', 1, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, 'Zaposleni može biti privremeno udaljen sa rada ako je protiv zaposlenog započeto krivično gonjenje zbog krivičnog dela učinjenog na radu ili u vezi sa radom, a samo udaljenje može da traje do pravnosnažnog okončanja tog krivičnog postupka. Zaposlenom pripada naknada zarade u visini jedne četvrtine, a ako izdržava porodicu u visini jedne trećine osnovne zarade. #član 165, 167 i 168 Zakona o radu', 1, '2021-04-16 11:00:59', '2021-04-16 11:00:59', 1, 0, 0, 1);
INSERT INTO `kad_absence_subtype` VALUES (38, 10, 'Zaposlenog koji nepoštovanjem radne discipline ili povredom radne obaveze ugrožava imovinu veće vrednosti utvrđene opštim aktom ili ugovorom o radu', 1, NULL, NULL, 3, 0, 2, NULL, NULL, NULL, NULL, NULL, 'Udaljenje zaposlenog koji nepoštovanjem radne discipline ili povredom radne obaveze ugrožava imovinu veće vrednosti utvrđene opštim aktom ili ugovorom o radumože da traje najduže tri meseca, a po isteku tog perioda poslodavac je dužan da zaposlenog vrati na rad ili da mu otkaže ugovor o radu ili izrekne drugu meru u skladu sa ovim zakonom ako za to postoje opravdani razlozi. Zaposlenom pripada naknada zarade u visini jedne četvrtine, a ako izdržava porodicu u visini jedne trećine osnovne zarade. #član 165, 167 i 168 Zakona o radu', 1, '2021-04-16 11:00:59', '2021-04-16 11:00:59', 0, 0, 1, 1);
INSERT INTO `kad_absence_subtype` VALUES (39, 10, 'Zaposlenog ako je priroda povrede radne obaveze/nepoštovanja radne discipline takva da ne može da nastavi rad kod poslodavca', 1, NULL, NULL, 3, 0, 2, NULL, NULL, NULL, NULL, NULL, 'Zaposleni može da bude privremeno udaljen sa rada ako je priroda povrede radne obaveze, odnosno nepoštovanja radne discipline ili je ponašanje zaposlenog takvo da ne može da nastavi rad kod poslodavca pre isteka roka na izjašnjenje na navode iz upozorenja, i to može trajati najduže tri meseca, a po isteku tog perioda poslodavac je dužan da zaposlenog vrati na rad ili da mu otkaže ugovor o radu ili izrekne drugu meru u skladu sa ovim zakonom ako za to postoje opravdani razlozi iz člana 179. st. 2. i 3. ovog zakona. Zaposlenom pripada naknada zarade u visini jedne četvrtine, a ako izdržava porodicu u visini jedne trećine osnovne zarade. #član 165, 167 i 168 Zakona o radu', 1, '2021-04-16 11:00:59', '2021-04-16 11:00:59', 0, 0, 1, 1);
INSERT INTO `kad_absence_subtype` VALUES (40, 10, 'Zaposlenog koji je u pritvoru', 1, NULL, NULL, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, 'Zaposleni kome je određen pritvor udaljuje se sa rada od prvog dana pritvora, dok pritvor traje. Zaposlenom pripada naknada zarade u visini jedne četvrtine, a ako izdržava porodicu u visini jedne trećine osnovne zarade, koja se isplaćuje na teret organa koji je odredio pritvor. #član 166 i 168 Zakona o radu', 1, '2021-04-16 11:00:59', '2021-04-16 11:00:59', 0, 0, 1, 1);
INSERT INTO `kad_absence_subtype` VALUES (41, 10, 'Disciplinsko privremeno udaljenje sa rada', 1, NULL, 15, NULL, 0, 1, NULL, NULL, NULL, NULL, NULL, 'Poslodavac može zaposlenom za povredu radne obaveze ili nepoštovanje radne discipline da, ako smatra da postoje olakšavajuće okolnosti ili da povreda radne obaveze, odnosno nepoštovanje radne discipline, nije takve prirode da zaposlenom treba da prestane radni odnos, umesto otkaza ugovora o radu, izrekne meru privremeno udaljenje sa rada bez naknade zarade, u trajanju od jednog do 15 radnih dana. Mera se izriče rešenjem nakon sprovedene predotkazne procedure. #član 179, 179a i 180 Zakona o radu.', 1, '2021-04-16 11:00:59', '2021-04-16 11:00:59', 0, 0, 1, 1);
INSERT INTO `kad_absence_type` VALUES (1, 'Godišnji odmor', '2021-04-16 10:28:27', '2021-04-16 10:28:27', NULL);
