INSERT INTO `kad_absence_type` VALUES (6, 'Neplaćeno odsustvo', '2021-04-16 10:28:28', '2021-04-16 10:28:28', 1);
INSERT INTO `kad_absence_type` VALUES (7, 'Odsustva po osnovu materinstva', '2021-04-16 10:28:28', '2021-04-16 10:28:28', 1);
INSERT INTO `kad_absence_type` VALUES (8, 'Privremena sprečenost za rad (bolovanje)', '2021-04-16 10:28:28', '2021-04-16 10:28:28', 1);
