INSERT INTO `passport_type` VALUES (1, 'Standardni');
INSERT INTO `pdv_reasons` VALUES (12, '1', '', 'zakonu o porezu na dodatu vrednost', '24', '1', 'PDV se ne plaća na prevozne i ostale usluge, koje su povezane sa uvozom dobara, ako je vrednost tih usluga sadržana u osnovici iz člana 19 stav 2 ovog zakona', 'ПДВ се не плаћа на превозне и остале услуге, које су повезане са увозом добара, ако је вредност тих услуга садржана у основици из члана 19 став 2 овог закона', '0', 'reasonKey_1', 1, NULL, NULL, NULL, NULL);
INSERT INTO `pdv_reasons` VALUES (13, '2', '', 'zakonu o porezu na dodatu vrednost', '24', '1', 'PDV se ne plaća na promet dobara koja obveznik ili treće lice, po njegovom nalogu, šalje ili otprema u inostranstvo', 'ПДВ се не плаћа на промет добара која обвезник или треће лице, по његовом налогу, шаље или отпрема у иностранство', '0', 'reasonKey_2', 1, NULL, NULL, NULL, NULL);
INSERT INTO `pdv_reasons` VALUES (14, '3', '', 'zakonu o porezu na dodatu vrednost', '24', '1', 'PDV se ne plaća na promet dobara koja inostrani primalac ili treće lice, po njegovom nalogu, šalje ili otprema u inostranstvo', 'ПДВ се не плаћа на промет добара која инострани прималац или треће лице, по његовом налогу, шаље или отпрема у иностранство', '0', 'reasonKey_3', 1, NULL, NULL, NULL, NULL);
INSERT INTO `pdv_reasons` VALUES (15, '4', '', 'zakonu o porezu na dodatu vrednost', '24', '1', 'promet dobara koja putnik otprema u inostranstvo u ličnom prtljagu, za nekomercijalne svrhe, ako:(1) putnik u Republici nema prebivalište ni boravište,(2) se dobra otpremaju pre isteka tri kalendarska meseca po isteku kalendarskog meseca u kojem je izvršen promet dobara,(3) je ukupna vrednost isporučenih dobara jednaka ili veća od 6.000 dinara, uključujući PDV,(4) obveznik PDV poseduje dokaze da je putnik otpremio dobra u inostranstvo', 'промет добара која путник отпрема у иностранство у личном пртљагу, за некомерцијалне сврхе, ако:(1) путник у Републици нема пребивалиште ни боравиште,(2) се добра отпремају пре истека три календарска месеца по истеку календарског месеца у којем је извршен промет добара,(3) је укупна вредност испоручених добара једнака или већа од 6.000 динара, укључујући ПДВ,(4) обвезник ПДВ поседује доказе да је путник отпремио добра у иностранство', '0', 'reasonKey_4', 1, NULL, NULL, NULL, NULL);
INSERT INTO `pdv_reasons` VALUES (16, '6', '', 'zakonu o porezu na dodatu vrednost', '24', '2', 'Inostranim primaocem dobara ili usluga, u smislu ovog člana, smatra se lice koje je obveznik, a čije je mesto stvarne uprave van Republike', 'Иностраним примаоцем добара или услуга, у смислу овог члана, сматра се лице које је обвезник, а чије је место стварне управе ван Републике', '0', 'reasonKey_6', 1, NULL, NULL, NULL, NULL);
INSERT INTO `pdv_reasons` VALUES (17, '7', '', 'zakonu o porezu na dodatu vrednost', '24', '2', 'Inostranim primaocem dobara ili usluga, u smislu ovog člana, smatra se lice koje nije obveznik, a ima prebivalište ili sedište van Republike', 'Иностраним примаоцем добара или услуга, у смислу овог члана, сматра се лице које није обвезник, а има пребивалиште или седиште ван Републике', '0', 'reasonKey_7', 1, NULL, NULL, NULL, NULL);
INSERT INTO `pdv_reasons` VALUES (18, '8', '', 'zakonu o porezu na dodatu vrednost', '25', '1', 'PDV se ne plaća u prometu novca i kapitala, i to kod poslovanja i posredovanja u poslovanju zakonskim sredstvima plaćanja, osim papirnog i kovanog novca koji se ne koristi kao zakonsko sredstvo plaćanja ili ima numizmatičku vrednost', 'ПДВ се не плаћа у промету новца и капитала, и то код пословања и посредовања у пословању законским средствима плаћања, осим папирног и кованог новца који се не користи као законско средство плаћања или има нумизматичку вредност', '0', 'reasonKey_8', 1, NULL, NULL, NULL, NULL);
INSERT INTO `pdv_reasons` VALUES (19, '9', '', 'zakonu o porezu na dodatu vrednost', '25', '2', 'PDV se ne plaća i na promet usluga osiguranja i reosiguranja, uključujući prateće usluge posrednika i agenta (zastupnika) u osiguranju', 'ПДВ се не плаћа и на промет услуга осигурања и реосигурања, укључујући пратеће услуге посредника и агента (заступника) у осигурању', '0', 'reasonKey_9', 1, NULL, NULL, NULL, NULL);
INSERT INTO `pdv_reasons` VALUES (20, '10', '', 'zakonu o porezu na dodatu vrednost', '26', '1', 'PDV se ne plaća na uvoz dobara čiji promet je u skladu sa\nčlanom 24. stav 1. tač. 5), 10), 11) i 13)-16g) i članom 25. stav 1. tač. 1) i 2) i stav 2. tač. 5) i 10) ovog zakona oslobođen PDV', 'ПДВ се не плаћа на увоз добара чији промет је у складу са\nчланом 24. став 1. тач. 5), 10), 11) и 13)-16г) и чланом 25. став 1. тач. 1) и 2) и став 2. тач. 5) и 10) овог закона ослобођен ПДВ', '0', 'reasonKey_10', 1, NULL, NULL, NULL, NULL);
INSERT INTO `pdv_reasons` VALUES (21, '11', '', 'zakonu o porezu na dodatu vrednost', '26', '1', 'PDV se ne plaća na uvoz dobara koja se uvoze na osnovu ugovora o donaciji, odnosno kao humanitarna pomoć u skladu sa zakonom kojim se uređuju donacije, odnosno humanitarna pomoć', 'ПДВ се не плаћа на увоз добара која се увозе на основу уговора о донацији, односно као хуманитарна помоћ у складу са законом којим се уређују донације, односно хуманитарна помоћ', '0', 'reasonKey_11', 1, NULL, NULL, NULL, NULL);
INSERT INTO `pdv_reasons` VALUES (22, '12', '', 'zakonu o porezu na dodatu vrednost', '26', '1', 'PDV se ne plaća na uvoz dobara koja su izvezena, a koja se u Republiku vraćaju neprodata ili zato što ne odgovaraju obavezama koje proističu iz ugovora, odnosno poslovnog odnosa na osnovu kojeg su bila izvezena', 'PDV se ne plaća na uvoz dobara koja su izvezena, a koja se u Republiku vraćaju neprodata ili zato što ne odgovaraju obavezama koje proističu iz ugovora, odnosno poslovnog odnosa na osnovu kojeg su bila izvezena', '0', 'reasonKey_12', 1, NULL, NULL, NULL, NULL);
INSERT INTO `pdv_reasons` VALUES (23, '1', 'AE', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Poreski dužnik je primalac dobara ili usluga, obveznik PDV, za promet sekundarnih sirovina i usluga koje su neposredno povezane sa tim dobrima, izvršen od strane drugog obveznika PDV', NULL, NULL, 'PDV-RS-10-2-1', 1, '1', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (24, '2', 'AE', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Poreski dužnik je primalac dobara, obveznik PDV, za promet građevinskih objekata i ekonomski deljivih celina u okviru tih objekata, uključujući i vlasničke udele na tim dobrima, izvršen od strane drugog obveznika PDV, u slučaju kada je ugovorom na osnovu kojeg se vrši promet tih dobara predviđeno da će se na taj promet obračunati PDV u skladu sa ovim zakonom', NULL, NULL, 'PDV-RS-10-2-2', 1, '2', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (25, '3', 'AE', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Poreski dužnik je primalac dobara i usluga iz oblasti građevinarstva, obveznik PDV, odnosno lice iz člana 9. stav 1. ovog zakona, za promet izvršen od strane obveznika PDV, ako je vrednost tog prometa veća od 500.000 dinara, bez PDV', NULL, NULL, 'PDV-RS-10-2-3', 1, '3', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (26, '4', 'AE', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Poreski dužnik je primalac električne energije i prirodnog gasa koji se isporučuju preko prenosne, transportne i distributivne mreže, obveznik PDV koji je ova dobra nabavio radi dalje prodaje, za promet električne energije i prirodnog gasa izvršen od strane drugog obveznika PDV', NULL, NULL, 'PDV-RS-10-2-4', 1, '4', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (27, '5', 'AE', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Poreski dužnik je primalac dobara ili usluga, obveznik PDV, za promet izvršen od strane drugog obveznika PDV, i to kod prometa hipotekovane nepokretnosti kod realizacije hipoteke u skladu sa zakonom kojim se uređuje hipoteka', NULL, NULL, 'PDV-RS-10-2-5-1', 1, '5', '1', '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (28, '6', 'AE', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Poreski dužnik je primalac dobara ili usluga, obveznik PDV, za promet izvršen od strane drugog obveznika PDV, i to kod prometa predmeta založnog prava kod realizacije ugovora o zalozi u skladu sa zakonom kojim se uređuje založno pravo na pokretnim stvarima', NULL, NULL, 'PDV-RS-10-2-5-2', 1, '5', '2', '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (29, '7', 'AE', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Poreski dužnik je primalac dobara ili usluga, obveznik PDV, za promet izvršen od strane drugog obveznika PDV, i to kod prometa dobara ili usluga nad kojima se sprovodi izvršenje u izvršnom postupku u skladu sa zakonom', NULL, NULL, 'PDV-RS-10-2-5-3', 1, '5', '3', '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (30, '8', 'O', 'Zakon o Porezu na dodatu vrednost', '11', '1', 'Mesto prometa dobara je inostranstvo - mesto u kojem se dobro nalazi u trenutku slanja ili prevoza do primaoca ili, po njegovom nalogu, do trećeg lica, ako dobro šalje ili prevozi isporučilac, primalac ili treće lice, po njegovom nalogu', NULL, NULL, 'PDV-RS-11-1-1', 0, '1', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (31, '9', 'O', 'Zakon o Porezu na dodatu vrednost', '11', '1', 'Mesto prometa dobara je inostranstvo - mesto ugradnje ili montaže dobra, ako se ono ugrađuje ili montira od strane isporučioca ili, po njegovom nalogu, od strane trećeg lica', NULL, NULL, 'PDV-RS-11-1-2', 0, '2', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (32, '10', 'O', 'Zakon o Porezu na dodatu vrednost', '11', '1', 'Mesto prometa dobara je inostranstvo - mesto u kojem se dobro nalazi u trenutku isporuke, ako se dobro isporučuje bez otpreme, odnosno prevoza', NULL, NULL, 'PDV-RS-11-1-3', 0, '3', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (33, '11', 'O', 'Zakon o Porezu na dodatu vrednost', '11', '1', 'Mesto prometa dobara je inostranstvo - mesto u kojem primalac električne energije, prirodnog gasa i energije za grejanje, odnosno hlađenje, čija se isporuka vrši preko prenosne, transportne i distributivne mreže, a koji je ova dobra nabavio radi dalje prodaje, ima sedište ili stalnu poslovnu jedinicu kojima se dobra isporučuju', NULL, NULL, 'PDV-RS-11-1-4', 0, '4', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (34, '12', 'O', 'Zakon o Porezu na dodatu vrednost', '11', '1', 'Mesto prometa dobara je inostranstvo - mesto prijema vode, električne energije, prirodnog gasa i energije za grejanje, odnosno hlađenje, za krajnju potrošnju', NULL, NULL, 'PDV-RS-11-1-5', 0, '5', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (35, '13', 'O', 'Zakon o Porezu na dodatu vrednost', '11', '3', 'Izuzetno od stava 1. tačka 3) ovog člana, ako se promet dobara vrši na brodu, odnosno u letilici ili vozu u toku prevoza putnika, mestom prometa smatra se mesto polaska broda, letilice ili voza, koje se nalazi u inostranstvu', NULL, NULL, 'PDV-RS-11-3', 0, NULL, NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (36, '14', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '4', 'Ako se promet usluga vrši poreskom obvezniku, mestom prometa usluga smatra se mesto u inostranstvu u kojem primalac usluga ima sedište ili stalnu poslovnu jedinicu ako se promet usluga vrši stalnoj poslovnoj jedinici koja se ne nalazi u mestu u kojem primalac usluga ima sedište, odnosno mesto u inostranstvu u kojem primalac usluga ima prebivalište ili boravište', NULL, NULL, 'PDV-RS-12-4', 0, NULL, NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (37, '15', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga u vezi sa nepokretnostima, uključujući i usluge posredovanja kod prometa nepokretnosti, smatra se mesto u inostranstvu u kojem se nalazi nepokretnost', NULL, NULL, 'PDV-RS-12-6-1', 0, '1', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (38, '16', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga prevoza lica, smatra se mesto gde se obavlja prevoz, a ako se prevoz obavlja i u Republici i u inostranstvu, odredbe ovog zakona primenjuju se samo na deo prevoza izvršen u Republici - deo usluge prevoza koji se vrši u inostranstvu', NULL, NULL, 'PDV-RS-12-6-2', 0, '2', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (39, '17', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga prevoza dobara koja se pruža licu koje nije poreski obveznik, smatra se mesto gde se obavlja prevoz, a ako se prevoz obavlja i u Republici i u inostranstvu, odredbe ovog zakona primenjuju se samo na deo prevoza izvršen u Republici - deo usluge prevoza koji se vrši u inostranstvu', NULL, NULL, 'PDV-RS-12-6-3', 0, '3', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (40, '18', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga smatra se mesto gde su usluge stvarno pružene, ako se radi o uslugama koje se odnose na prisustvovanje kulturnim, umetničkim, sportskim, naučnim, obrazovnim, zabavnim ili sličnim događajima (sajmovi, izložbe i dr.), uključujući i pomoćne usluge u vezi sa prisustvovanjem tim događajima, čije je mesto prometa u inostranstvu', NULL, NULL, 'PDV-RS-12-6-4-1', 0, '4', '1', '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (41, '19', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga smatra se mesto gde su usluge stvarno pružene, ako se radi o uslugama organizatora događaja iz podtačke (1) ove tačke, pruženih licu koje nije poreski obveznik, čije je mesto prometa u inostranstvu', NULL, NULL, 'PDV-RS-12-6-4-2', 0, '4', '2', '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (42, '20', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga smatra se mesto gde su usluge stvarno pružene, ako se radi o pomoćnim uslugama u vezi sa prevozom, kao što su utovar, istovar, pretovar i slično, pruženih licu koje nije poreski obveznik, čije je mesto prometa u inostranstvu', NULL, NULL, 'PDV-RS-12-6-4-3', 0, '4', '3', '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (43, '21', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga smatra se mesto gde su usluge stvarno pružene, ako se radi o uslugama procene pokretnih stvari, odnosno radova na pokretnim stvarima pruženih licu koje nije poreski obveznik, čije je mesto prometa u inostranstvu', NULL, NULL, 'PDV-RS-12-6-4-4', 0, '4', '4', '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (44, '22', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga smatra se mesto gde su usluge stvarno pružene, ako se radi o uslugama predaje jela i pića za konzumaciju na licu mesta, čije je mesto prometa u inostranstvu', NULL, NULL, 'PDV-RS-12-6-4-5', 0, '4', '5', '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (45, '23', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga iznajmljivanja prevoznih sredstava na kraći vremenski period, smatra se mesto u inostranstvu u kojem se prevozno sredstvo stvarno stavlja na korišćenje primaocu usluge', NULL, NULL, 'PDV-RS-12-6-5', 0, '5', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (46, '24', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga iznajmljivanja prevoznih sredstava, osim iz tačke 5) ovog stava, pruženih licu koje nije poreski obveznik, smatra se mesto u inostranstvu u kojem to lice ima sedište, prebivalište ili boravište', NULL, NULL, 'PDV-RS-12-6-6', 0, '6', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (47, '25', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga koje se pružaju licu koje nije poreski obveznik, smatra se mesto sedišta, prebivališta ili boravišta primaoca usluga, koje se nalazi u inostranstvu, ako se radi o uslugama prenosa, ustupanja i davanja na korišćenje autorskih i srodnih prava, prava na patente, licence, zaštitne znakove i druga prava intelektualne svojine', NULL, NULL, 'PDV-RS-12-6-7-1', 0, '7', '1', '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (48, '26', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga koje se pružaju licu koje nije poreski obveznik, smatra se mesto sedišta, prebivališta ili boravišta primaoca usluga, koje se nalazi u inostranstvu, ako se radi o uslugama oglašavanja', NULL, NULL, 'PDV-RS-12-6-7-2', 0, '7', '2', '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (49, '27', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga koje se pružaju licu koje nije poreski obveznik, smatra se mesto sedišta, prebivališta ili boravišta primaoca usluga, koje se nalazi u inostranstvu, ako se radi o uslugama savetnika, inženjera, advokata, revizora i sličnih usluga, kao i prevodilaca za usluge prevođenja, uključujući i prevođenje u pisanom obliku', NULL, NULL, 'PDV-RS-12-6-7-3', 0, '7', '3', '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (50, '28', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga koje se pružaju licu koje nije poreski obveznik, smatra se mesto sedišta, prebivališta ili boravišta primaoca usluga, koje se nalazi u inostranstvu, ako se radi o uslugama obrade podataka i ustupanja, odnosno davanja informacija, uključujući i informacije o poslovnim postupcima i iskustvu', NULL, NULL, 'PDV-RS-12-6-7-4', 0, '7', '4', '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (51, '29', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga koje se pružaju licu koje nije poreski obveznik, smatra se mesto sedišta, prebivališta ili boravišta primaoca usluga, koje se nalazi u inostranstvu, ako se radi o uslugama preuzimanja obaveze da se u potpunosti ili delimično odustane od obavljanja neke delatnosti ili od korišćenja nekog prava iz ove tačke', NULL, NULL, 'PDV-RS-12-6-7-5', 0, '7', '5', '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (52, '30', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga koje se pružaju licu koje nije poreski obveznik, smatra se mesto sedišta, prebivališta ili boravišta primaoca usluga, koje se nalazi u inostranstvu, ako se radi o uslugama bankarskog i finansijskog poslovanja i poslovanja u oblasti osiguranja, uključujući reosiguranje, osim iznajmljivanja sefova', NULL, NULL, 'PDV-RS-12-6-7-6', 0, '7', '6', '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (53, '31', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga koje se pružaju licu koje nije poreski obveznik, smatra se mesto sedišta, prebivališta ili boravišta primaoca usluga, koje se nalazi u inostranstvu, ako se radi o uslugama stavljanja na raspolaganje osoblja', NULL, NULL, 'PDV-RS-12-6-7-7', 0, '7', '7', '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (54, '32', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga koje se pružaju licu koje nije poreski obveznik, smatra se mesto sedišta, prebivališta ili boravišta primaoca usluga, koje se nalazi u inostranstvu, ako se radi o uslugama iznajmljivanja pokretnih stvari, osim prevoznih sredstava', NULL, NULL, 'PDV-RS-12-6-7-8', 0, '7', '8', '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (55, '33', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga koje se pružaju licu koje nije poreski obveznik, smatra se mesto sedišta, prebivališta ili boravišta primaoca usluga, koje se nalazi u inostranstvu, ako se radi o uslugama omogućavanja pristupa mreži prirodnog gasa, mreži za prenos električne energije i mreži za grejanje, odnosno hlađenje, transporta i distribucije putem tih mreža, kao i drugih usluga koje su neposredno povezane sa tim uslugama', NULL, NULL, 'PDV-RS-12-6-7-9', 0, '7', '9', '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (56, '34', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga koje se pružaju licu koje nije poreski obveznik, smatra se mesto sedišta, prebivališta ili boravišta primaoca usluga, koje se nalazi u inostranstvu, ako se radi o uslugama telekomunikacija', NULL, NULL, 'PDV-RS-12-6-7-10', 0, '7', '10', '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (57, '35', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga koje se pružaju licu koje nije poreski obveznik, smatra se mesto sedišta, prebivališta ili boravišta primaoca usluga, koje se nalazi u inostranstvu, ako se radi o uslugama radijskog i televizijskog emitovanja', NULL, NULL, 'PDV-RS-12-6-7-11', 0, '7', '11', '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (58, '36', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga koje se pružaju licu koje nije poreski obveznik, smatra se mesto sedišta, prebivališta ili boravišta primaoca usluga, koje se nalazi u inostranstvu, ako se radi o uslugama pruženim elektronskim putem', NULL, NULL, 'PDV-RS-12-6-7-12', 0, '7', '12', '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (59, '37', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '6', 'Mestom prometa usluga posredovanja kod prometa dobara ili usluga koja se pruža licu koje nije poreski obveznik, smatra se mesto u kojem je izvršen promet dobara ili usluga koji je predmet posredovanja, koje je u inostranstvu', NULL, NULL, 'PDV-RS-12-6-8', 0, '8', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (60, '38', 'O', 'Zakon o Porezu na dodatu vrednost', '12', '9', 'Izuzetno od stava 6. tačka 4) podtačka (5) ovog člana, ako se usluge predaje jela i pića za konzumaciju na licu mesta faktički pružaju na brodu, odnosno u letilici ili vozu u toku prevoza putnika, mestom prometa smatra se mesto polaska broda, letilice ili voza, koje je u inostranstvu.', NULL, NULL, 'PDV-RS-12-9', 0, NULL, NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (61, '39', 'O', 'Zakon o Porezu na dodatu vrednost', '17', '4', 'Osnovica ne sadrži iznose koje obveznik naplaćuje u ime i za račun drugog, ako te iznose prenosi licu u čije ime i za čiji račun je izvršio naplatu i ako su ti iznosi posebno evidentirani', NULL, NULL, 'PDV-RS-17-4-2', 1, '2', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (62, '40', 'O', 'Zakon o Porezu na dodatu vrednost', '17', '4', 'Osnovica ne sadrži iznose koje obveznik potražuje za izdatke koje je platio u ime i za račun primaoca dobara ili usluga, ako su ti iznosi posebno evidentirani', NULL, NULL, 'PDV-RS-17-4-3', 1, '3', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (63, '41', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '1', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza u prometu novca i kapitala, i to kod poslovanja i posredovanja u poslovanju zakonskim sredstvima plaćanja, osim papirnog i kovanog novca koji se ne koristi kao zakonsko sredstvo plaćanja ili ima numizmatičku vrednost;', NULL, NULL, 'PDV-RS-25-1-1', 0, '1', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (64, '42', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '1', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza u prometu novca i kapitala, i to kod prenosa virtuelnih valuta i zamene virtuelnih valuta za novčana sredstva u skladu sa zakonom kojim se uređuje digitalna imovina', NULL, NULL, 'PDV-RS-25-1-1a', 0, '1a', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (65, '43', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '1', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza u prometu novca i kapitala, i to kod poslovanja i posredovanja u poslovanju akcijama, udelima u društvima i udruženjima, obveznicama i drugim hartijama od vrednosti, osim poslovanja koje se odnosi na čuvanje i upravljanje hartijama od vrednosti', NULL, NULL, 'PDV-RS-25-1-2', 0, '2', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (66, '44', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '1', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza u prometu novca i kapitala, i to kod kreditnih poslova, uključujući posredovanje, kao i novčanih pozajmica', NULL, NULL, 'PDV-RS-25-1-3', 0, '3', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (67, '45', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '1', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza u prometu novca i kapitala, i to kod preuzimanja obaveza, garancija i drugih sredstava obezbeđenja, uključujući posredovanje', NULL, NULL, 'PDV-RS-25-1-4', 0, '4', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (68, '46', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '1', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza u prometu novca i kapitala, i to kod poslovanja i posredovanja u poslovanju depozitima, tekućim i žiro računima, nalozima za plaćanje, kao i platnim prometom i doznakama', NULL, NULL, 'PDV-RS-25-1-5', 0, '5', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (69, '47', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '1', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza u prometu novca i kapitala, i to kod poslovanja i posredovanja u poslovanju novčanim potraživanjima, čekovima, menicama i drugim sličnim hartijama od vrednosti, osim naplate potraživanja za druga lica', NULL, NULL, 'PDV-RS-25-1-6', 0, '6', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (70, '48', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '1', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza u prometu novca i kapitala, i to kod poslovanja društava za upravljanje investicionim fondovima u skladu sa propisima kojima se uređuju investicioni fondovi', NULL, NULL, 'PDV-RS-25-1-7', 0, '7', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (71, '49', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '1', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza u prometu novca i kapitala, i to kod poslovanja društava za upravljanje dobrovoljnim penzijskim fondovima u skladu sa propisima kojima se uređuju dobrovoljni penzijski fondovi i penzijski planovi', NULL, NULL, 'PDV-RS-25-1-8', 0, '8', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (72, '50', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '2', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza za promet usluga osiguranja i reosiguranja, uključujući prateće usluge posrednika i agenta (zastupnika) u osiguranju', NULL, NULL, 'PDV-RS-25-2-1', 0, '1', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (73, '51', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '2', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza za promet zemljišta, kao i na davanje u zakup tog zemljišta', NULL, NULL, 'PDV-RS-25-2-2', 0, '2', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (74, '52', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '2', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza za promet objekata, osim prvog prenosa prava raspolaganja na novoizgrađenim građevinskim objektima ili ekonomski deljivim celinama u okviru tih objekata i prvog prenosa vlasničkog udela na novoizgrađenim građevinskim objektima ili ekonomski deljivim celinama u okviru tih objekata, kao i prometa objekata i ekonomski deljivih celina u okviru tih objekata, uključujući i vlasničke udele na tim dobrima, u slučaju kada je ugovorom na osnovu kojeg se vrši promet tih dobara, zaključenim između obveznika PDV, predviđeno da će se na taj promet obračunati PDV, pod uslovom da sticalac obračunati PDV može u potpunosti odbiti kao prethodni porez', NULL, NULL, 'PDV-RS-25-2-3', 0, '3', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (75, '53', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '2', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza za promet dobara i usluga za koje pri nabavci obveznik nije imao pravo na odbitak prethodnog poreza', NULL, NULL, 'PDV-RS-25-2-3a', 0, '3a', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (76, '54', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '2', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza za promet dobara za koja je u prethodnoj fazi prometa postojala obaveza plaćanja poreza u skladu sa zakonom kojim se uređuju porezi na imovinu', NULL, NULL, 'PDV-RS-25-2-3b', 0, '3b', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (77, '55', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '2', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza za promet udela, hartija od vrednosti, poštanskih vrednosnica, taksenih i drugih važećih vrednosnica po njihovoj utisnutoj vrednosti u Republici, osim vlasničkih udela iz člana 4. ovog zakona', NULL, NULL, 'PDV-RS-25-2-5', 0, '5', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (78, '56', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '2', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza za promet poštanskih usluga od strane javnog preduzeća, kao i sa njima povezanih isporuka dobara', NULL, NULL, 'PDV-RS-25-2-6', 0, '6', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (79, '57', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '2', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza za promet usluga koje pružaju zdravstvene ustanove u skladu sa propisima koji regulišu zdravstvenu zaštitu, uključujući i smeštaj, negu i ishranu bolesnika u tim ustanovama, osim apoteka i apotekarskih ustanova', NULL, NULL, 'PDV-RS-25-2-7', 0, '7', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (80, '58', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '2', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza za promet usluga koje pružaju lekari, stomatolozi ili druga lica u skladu sa propisima koji regulišu zdravstvenu zaštitu', NULL, NULL, 'PDV-RS-25-2-8', 0, '8', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (81, '59', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '2', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza za promet usluga i isporuke zubne protetike u okviru delatnosti zubnog tehničara, kao i isporuka zubne protetike od strane stomatologa', NULL, NULL, 'PDV-RS-25-2-9', 0, '9', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (82, '60', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '2', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza za promet ljudskih organa, tkiva, telesnih tečnosti i ćelija, krvi i majčinog mleka', NULL, NULL, 'PDV-RS-25-2-10', 0, '10', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (83, '61', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '2', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza za promet usluga socijalnog staranja i zaštite, dečje zaštite i zaštite mladih, usluga ustanova socijalne zaštite, kao i sa njima neposredno povezanog prometa dobara i usluga od strane lica registrovanih za obavljanje tih delatnosti', NULL, NULL, 'PDV-RS-25-2-11', 0, '11', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (84, '62', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '2', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza za promet usluga smeštaja i ishrane učenika i studenata u školskim i studentskim domovima ili sličnim ustanovama, kao i sa njima neposredno povezan promet dobara i usluga', NULL, NULL, 'PDV-RS-25-2-12', 0, '12', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (85, '63', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '2', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza za promet usluga obrazovanja (predškolsko, osnovno, srednje, više i visoko) i profesionalne prekvalifikacije, kao i sa njima neposredno povezanog prometa dobara i usluga od strane lica registrovanih za obavljanje tih delatnosti, ako se ove delatnosti obavljaju u skladu sa propisima koji uređuju tu oblast', NULL, NULL, 'PDV-RS-25-2-13', 0, '13', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (86, '64', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '2', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza za promet usluga iz oblasti kulture i sa njima neposredno povezanog prometa dobara i usluga, od strane lica čija delatnost nije usmerena ka ostvarivanju dobiti, a koja su registrovana za tu delatnost', NULL, NULL, 'PDV-RS-25-2-14', 0, '14', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (87, '65', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '2', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza za promet usluga iz oblasti nauke i sa njima neposredno povezanog prometa dobara i usluga, od strane lica čija delatnost nije usmerena ka ostvarivanju dobiti, a koja su registrovana za tu delatnost', NULL, NULL, 'PDV-RS-25-2-15', 0, '15', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (88, '66', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '2', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza za promet usluga verskog karaktera od strane registrovanih crkava i verskih zajednica i sa njima neposredno povezanog prometa dobara i usluga', NULL, NULL, 'PDV-RS-25-2-16', 0, '16', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (89, '67', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '2', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza za promet usluga javnog radiodifuznog servisa, osim usluga komercijalnog karaktera', NULL, NULL, 'PDV-RS-25-2-17', 0, '17', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (90, '68', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '2', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza za promet usluga priređivanja igara na sreću', NULL, NULL, 'PDV-RS-25-2-18', 0, '18', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (91, '69', 'E', 'Zakon o Porezu na dodatu vrednost', '25', '2', 'Poresko oslobođenje bez prava na odbitak prethodnog poreza za promet usluga iz oblasti sporta i fizičkog vaspitanja licima koja se bave sportom i fizičkim vaspitanjem, od strane lica čija delatnost nije usmerena ka ostvarivanju dobiti, a koja su registrovana za tu delatnost', NULL, NULL, 'PDV-RS-25-2-19', 0, '19', NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (92, '70', 'AE', 'Zakon o Porezu na dodatu vrednost', '36b', '6', 'Poreski dužnik za promet investicionog zlata iz stava 5. ovog člana je obveznik PDV kojem je taj promet izvršen', NULL, NULL, 'PDV-RS-36b-6', 1, NULL, NULL, '2022-02-28 01:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (93, '71', 'R', 'Zakon o porezu na dodatu vrednost', '6', '1', 'Smatra se da promet dobara i usluga nije izvršen kod prenosa celokupne ili dela imovine, sa ili bez naknade, ili kao ulog, ako je sticalac poreski obveznik ili tim prenosom postane poreski obveznik i ako produži da obavlja istu delatnost', NULL, NULL, 'PDV-RS-6-1-1', 0, '1', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (94, '72', 'R', 'Zakon o porezu na dodatu vrednost', '6a', NULL, 'Smatra se da, u smislu ovog zakona, promet dobara i usluga koji vrši davalac koncesije koncesionaru, odnosno koncesionar davaocu koncesije u okviru realizacije ugovora o javno-privatnom partnerstvu sa elementima koncesije, zaključenog u skladu sa zakonom kojim se uređuju javno-privatno partnerstvo i koncesije, nije izvršen, ako su davalac koncesije i koncesionar obveznici PDV koji bi, u slučaju kada bi se taj promet smatrao izvršenim, imali u potpunosti pravo na odbitak prethodnog poreza u skladu sa ovim zakonom', NULL, NULL, 'PDV-RS-6a', 0, NULL, NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (95, '73', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnok poreza za prevozne i ostale usluge, koje su povezane sa uvozom dobara, ako je vrednost tih usluga sadržana u osnovici iz člana 19. stav 2. ovog zakona', NULL, NULL, 'PDV-RS-24-1-1', 0, '1', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (96, '74', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za promet dobara koja obveznik ili treće lice, po njegovom nalogu, šalje ili otprema u inostranstvo', NULL, NULL, 'PDV-RS-24-1-2', 0, '2', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (97, '75', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za promet dobara koja inostrani primalac ili treće lice, po njegovom nalogu, šalje ili otprema u inostranstvo', NULL, NULL, 'PDV-RS-24-1-3', 0, '3', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (98, '76', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za unos dobara u slobodnu zonu, prevozne i druge usluge korisnicima slobodnih zona koje su neposredno povezane sa tim unosom i promet dobara i usluga u slobodnoj zoni, za koje bi obveznik - korisnik slobodne zone imao pravo na odbitak prethodnog poreza kada bi ta dobra ili usluge nabavljao za potrebe obavljanja delatnosti van slobodne zone', NULL, NULL, 'PDV-RS-24-1-5', 0, '5', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (99, '77', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za promet dobara koja se unose u slobodnu zonu, prevozne i druge usluge koje su neposredno povezane sa tim unosom i promet dobara u slobodnoj zoni, koji se vrši stranom licu koje ima zaključen ugovor sa obveznikom PDV - korisnikom slobodne zone da ta dobra ugradi u dobra namenjena otpremanju u inostranstvo', NULL, NULL, 'PDV-RS-24-1-5a', 0, '5a', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (100, '78', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za promet dobara koja su u postupku carinskog skladištenja', NULL, NULL, 'PDV-RS-24-1-6', 0, '6', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (101, '79', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za otpremanje dobara u slobodne carinske prodavnice otvorene na vazduhoplovnim pristaništima otvorenim za međunarodni saobraćaj na kojima je organizovana pasoška i carinska kontrola radi prodaje putnicima u skladu sa carinskim propisima, kao i na isporuku dobara iz slobodnih carinskih prodavnica', NULL, NULL, 'PDV-RS-24-1-6a', 0, '6a', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (102, '80', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za usluge radova na pokretnim dobrima nabavljenim od strane inostranog primaoca usluge u Republici, ili koja su uvezena radi oplemenjivanja, opravke ili ugradnje, a koja posle oplemenjivanja, opravke ili ugradnje, isporučilac usluge, inostrani primalac ili treće lice, po njihovom nalogu, prevozi ili otprema u inostranstvo', NULL, NULL, 'PDV-RS-24-1-7', 0, '7', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (103, '81', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za promet dobara koja su u postupku aktivnog oplemenjivanja za koja bi obveznik - sticalac imao pravo na odbitak prethodnog poreza kada bi ta dobra nabavljao sa obračunatim PDV', NULL, NULL, 'PDV-RS-24-1-7a', 0, '7a', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (104, '82', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za prevozne i ostale usluge koje su u vezi sa izvozom, tranzitom ili privremenim uvozom dobara, osim usluga koje su oslobođene od PDV bez prava na poreski odbitak u skladu sa ovim zakonom', NULL, NULL, 'PDV-RS-24-1-8', 0, '8', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (105, '83', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za usluge međunarodnog prevoza lica u vazdušnom saobraćaju, s tim što za nerezidentno vazduhoplovno preduzeće poresko oslobođenje važi samo u slučaju uzajamnosti', NULL, NULL, 'PDV-RS-24-1-9', 0, '9', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (106, '84', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za isporuke letilica, servisiranje, popravke, održavanje, čarterisanje i iznajmljivanje letilica, koje se pretežno koriste uz naknadu u međunarodnom vazdušnom saobraćaju, kao i isporuke, iznajmljivanje, popravke i održavanje dobara namenjenih opremanju tih letilica', NULL, NULL, 'PDV-RS-24-1-10', 0, '10', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (107, '85', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za promet dobara i usluga namenjenih neposrednim potrebama letilica iz tačke 10) ovog stava', NULL, NULL, 'PDV-RS-24-1-11', 0, '11', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (108, '86', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za usluge međunarodnog prevoza lica brodovima u rečnom saobraćaju, s tim što za nerezidentno preduzeće koje vrši međunarodni prevoz lica brodovima u rečnom saobraćaju, poresko oslobođenje važi samo u slučaju uzajamnosti', NULL, NULL, 'PDV-RS-24-1-12', 0, '12', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (109, '87', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za isporuke brodova, servisiranje, popravke, održavanje i iznajmljivanje brodova, koji se pretežno koriste uz naknadu u međunarodnom rečnom saobraćaju, kao i isporuke, iznajmljivanje, popravke i održavanje dobara namenjenih opremanju tih brodova', NULL, NULL, 'PDV-RS-24-1-13', 0, '13', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (110, '88', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za promet dobara i usluga namenjenih neposrednim potrebama brodova iz tačke 13) ovog stava', NULL, NULL, 'PDV-RS-24-1-14', 0, '14', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (111, '89', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za isporuke zlata Narodnoj banci Srbije', NULL, NULL, 'PDV-RS-24-1-15', 0, '15', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (112, '90', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za dobra i usluge namenjene za službene potrebe diplomatskih i konzularnih predstavništava', NULL, NULL, 'PDV-RS-24-1-16-1', 0, '16', '1', '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (113, '91', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za dobra i usluge namenjene za službene potrebe međunarodnih organizacija, ako je to predviđeno međunarodnim ugovorom', NULL, NULL, 'PDV-RS-24-1-16-2', 0, '16', '2', '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (114, '92', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za dobra i usluge namenjene za lične potrebe stranog osoblja diplomatskih i konzularnih predstavništava, uključujući i članove njihovih porodica', NULL, NULL, 'PDV-RS-24-1-16-3', 0, '16', '3', '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (115, '93', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za dobra i usluge namenjene za lične potrebe stranog osoblja međunarodnih organizacija, uključujući članove njihovih porodica, ako je to predviđeno međunarodnim ugovorom', NULL, NULL, 'PDV-RS-24-1-16-4', 0, '16', '4', '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (116, '94', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za promet dobara i usluga koji se vrši u skladu sa ugovorima o donaciji zaključenim sa državnom zajednicom Srbija i Crna Gora, odnosno Republikom, ako je tim ugovorom predviđeno da se iz dobijenih novčanih sredstava neće plaćati troškovi poreza, u delu koji se finansira dobijenim novčanim sredstvima osim ako ratifikovanim međunarodnim ugovorom nije drukčije predviđeno', NULL, NULL, 'PDV-RS-24-1-16a', 0, '16a', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (117, '95', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za promet dobara i usluga koji se vrši u skladu sa ugovorima o kreditu, odnosno zajmu, zaključenim između državne zajednice Srbija i Crna Gora, odnosno Republike i međunarodne finansijske organizacije, odnosno druge države, kao i između treće strane i međunarodne finansijske organizacije, odnosno druge države u kojem se Republika Srbija pojavljuje kao garant, odnosno kontragarant, u delu koji se finansira dobijenim novčanim sredstvima, ako je tim ugovorima predviđeno da se iz dobijenih novčanih sredstava neće plaćati troškovi poreza', NULL, NULL, 'PDV-RS-24-1-16b', 0, '16b', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (118, '96', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za promet dobara i usluga koji se vrši na osnovu međunarodnih ugovora, ako je tim ugovorima predviđeno poresko oslobođenje, osim međunarodnih ugovora iz tač. 16a) i 16b) ovog stava', NULL, NULL, 'PDV-RS-24-1-16v', 0, '16v', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (119, '97', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za promet dobara i usluga koji se vrši u okviru realizacije infrastrukturnih projekata izgradnje autoputeva za koje je posebnim zakonom utvrđen javni interes', NULL, NULL, 'PDV-RS-24-1-16g', 0, '16g', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (120, '98', 'Z', 'Zakon o porezu na dodatu vrednost', '24', '1', 'Poresko oslobođenje sa pravom na odbitak prethodnog poreza za usluge posredovanja koje se odnose na promet dobara i usluga iz tač. 1) - 16) ovog stava', NULL, NULL, 'PDV-RS-24-1-17', 0, '17', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (121, '99', 'Z', 'Zakon o porezu na dodatu vrednost', '61', NULL, 'Promet dobara sa teritorije Republike van APKM na teritoriju APKM', NULL, NULL, 'PDV-RS-61', 0, NULL, NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (122, '100', 'SS', 'Zakon o porezu na dodatu vrednost', '33', NULL, 'Promet dobara i usluga koji vrši mali obveznik', NULL, NULL, 'PDV-RS-33', 0, NULL, NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (123, '101', 'SS', 'Zakon o porezu na dodatu vrednost', '35', '7', 'Turistička agencija za turističke usluge iz stava 1. ovog člana ne može da iskazuje PDV u računima ili drugim dokumentima i nema pravo na odbitak prethodnog poreza na osnovu prethodnih turističkih usluga koje su joj iskazane u računu', NULL, NULL, 'PDV-RS-35-7', 0, NULL, NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (124, '102', 'SS', 'Zakon o porezu na dodatu vrednost', '36', '5', 'Kod prometa dobara iz stava 1. ovog člana na koji se primenjuje oporezivanje razlike, obveznik ne može iskazivati PDV u računima ili drugim dokumentima', NULL, NULL, 'PDV-RS-36-5', 0, NULL, NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (125, '103', 'SS', 'Zakon o porezu na dodatu vrednost', '36b', '4', 'PDV se ne plaća na:\r\n1) promet i uvoz investicionog zlata, uključujući i investiciono zlato čija je vrednost navedena u potvrdama o alociranom ili nealociranom zlatu, zlato kojim se trguje preko računa za trgovanje zlatom, uključujući i zajmove i zamene zlata(svop poslovi) koji podrazumevaju pravo vlasništva ili potraživanja u vezi sa zlatom, kao i aktivnosti u vezi sa investicionim zlatom na osnovu fjučers i forvard ugovora čiji je rezultat prenos prava raspolaganja ili prava potraživanja u vezi sa investicionim zlatom;\r\n2) promet usluga posrednika koji u ime i za račun nalogodavca vrši promet investicionog zlata.', NULL, NULL, 'PDV-RS-36b-4', 0, NULL, NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (126, '104', 'OE', 'Zakon o porezu na dodatu vrednost', '17', '4', 'Osnovica ne sadrži iznose koje obveznik naplaćuje u ime i za račun drugog, ako te iznose prenosi licu u čije ime i za čiji račun je izvršio naplatu i ako su ti iznosi posebno evidentirani', NULL, NULL, 'PDV-RS-17-4-2', 0, '2', NULL, '2022-04-27 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (127, '105', 'OE', 'Zakon o porezu na dodatu vrednost', '17', '4', 'Osnovica ne sadrži iznose koje obveznik potražuje za izdatke koje je platio u ime i za račun primaoca dobara ili usluga, ako su ti iznosi posebno evidentirani', NULL, NULL, 'PDV-RS-17-4-3', 0, '3', NULL, '2022-04-27 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (128, '106', 'N', 'Zakon o porezu na dodatu vrednost', '4', '4', 'Promet dobara bez naknade, nezavisno od toga da li je predmet oporezivanja PDV ', NULL, NULL, 'PDV-RS-4', 0, '2', NULL, '2022-04-27 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (129, '107', 'N', 'Zakon o porezu na dodatu vrednost', '5', '4', 'Promet usluga bez naknade, nezavisno od toga da li je predmet oporezivanja PDV', NULL, NULL, 'PDV-RS-5', 0, '2', NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (130, '108', 'OE', 'Zakon o porezu na dodatu vrednost', '9', '1', 'U cilju obavljanja poslova za koje lice nije poreski obveznik iz člana 9. stav 1. ZPDV', NULL, NULL, 'PDV-RS-9', 0, NULL, NULL, '2022-04-07 02:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (131, '109', 'OE', 'Zakon o porezu na dodatu vrednost', '7a', '4', 'Višenamenski vrednosni vaučer', NULL, NULL, 'PDV-RS-7a-4', 0, NULL, NULL, '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (132, '112', 'OE', 'Zakon o porezu na dodatu vrednost', '4', '4', 'Promet dobara bez naknade koji nije predmet oporezivanja', NULL, NULL, 'PDV-RS-4-4-2NP', 0, '2 (NP)', NULL, '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (133, '113', 'OE', 'Zakon o porezu na dodatu vrednost', '5', '4', 'Promet usluga bez naknade koji nije predmet oporezivanja', NULL, NULL, 'PDV-RS-5-4-2NP', 0, '2 (NP)', NULL, '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (134, '114', 'N', 'Zakon o porezu na dodatu vrednost', '6', '1', 'Prenos imovine ili dela imovine u skladu sa članom 6. stav 1. tačka 1) ZPDV, bez naknade', NULL, NULL, 'PDV-RS-6-1-1 (BN)', 0, '1 (BN)', NULL, '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (135, '115', 'OE', 'Zakon o porezu na dodatu vrednost', '3 (NP)', 'ostalo', 'Ostala potraživanja koja nisu predmet oporezivanja PDV', NULL, NULL, 'PDV-RS-3NP-ostalo', 0, NULL, NULL, '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (136, '116', 'N', 'Zakon o porezu na dodatu vrednost', '3 - DZ', NULL, 'Umanjenje iznosa za plaćanje zbog primene drugog zakona', NULL, NULL, 'PDV-RS-3-DZ', 0, NULL, NULL, '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (137, '117', 'AE20', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Poreski dužnik je primalac dobara ili usluga, obveznik PDV, za promet sekundarnih sirovina i usluga koje su neposredno povezane sa tim dobrima, izvršen od strane drugog obveznika PDV', NULL, NULL, 'PDV-RS-10-2-1', 0, '1', NULL, '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (138, '118', 'AE20', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Poreski dužnik je primalac dobara, obveznik PDV, za promet građevinskih objekata i ekonomski deljivih celina u okviru tih objekata, uključujući i vlasničke udele na tim dobrima, izvršen od strane drugog obveznika PDV, u slučaju kada je ugovorom na osnovu kojeg se vrši promet tih dobara predviđeno da će se na taj promet obračunati PDV u skladu sa ovim zakonom', NULL, NULL, 'PDV-RS-10-2-2', 0, '2', NULL, '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (139, '119', 'AE20', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Poreski dužnik je primalac dobara i usluga iz oblasti građevinarstva, obveznik PDV, odnosno lice iz člana 9. stav 1. ovog zakona, za promet izvršen od strane obveznika PDV, ako je vrednost tog prometa veća od 500.000 dinara, bez PDV', NULL, NULL, 'PDV-RS-10-2-3', 0, '3', NULL, '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (140, '120', 'AE20', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Poreski dužnik je primalac električne energije i prirodnog gasa koji se isporučuju preko prenosne, transportne i distributivne mreže, obveznik PDV koji je ova dobra nabavio radi dalje prodaje, za promet električne energije i prirodnog gasa izvršen od strane drugog obveznika PDV', NULL, NULL, 'PDV-RS-10-2-4', 0, '4', NULL, '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (141, '121', 'AE20', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Poreski dužnik je primalac dobara ili usluga, obveznik PDV, za promet izvršen od strane drugog obveznika PDV, i to kod prometa hipotekovane nepokretnosti kod realizacije hipoteke u skladu sa zakonom kojim se uređuje hipoteka', NULL, NULL, 'PDV-RS-10-2-5-1', 0, '5', '1', '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (142, '122', 'AE20', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Poreski dužnik je primalac dobara ili usluga, obveznik PDV, za promet izvršen od strane drugog obveznika PDV, i to kod prometa predmeta založnog prava kod realizacije ugovora o zalozi u skladu sa zakonom kojim se uređuje založno pravo na pokretnim stvarima', NULL, NULL, 'PDV-RS-10-2-5-2', 0, '5', '2', '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (143, '123', 'AE20', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Poreski dužnik je primalac dobara ili usluga, obveznik PDV, za promet izvršen od strane drugog obveznika PDV, i to kod prometa dobara ili usluga nad kojima se sprovodi izvršenje u izvršnom postupku u skladu sa zakonom', NULL, NULL, 'PDV-RS-10-2-5-3', 0, '5', '3', '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (144, '124', 'AE20', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Prvi prenos prava raspolaganja na novoizgrađenim građevinskim objektima, ekonomski deljivih celina u okviru tih objekata i vlasničkih udela na tim dobrima, koji su predmet izvršenja u izvršnom postupku u skladu sa zakonom, izvršen od strane obveznika PDV, za koji je poreski dužnik primalac, obveznik PDV', NULL, NULL, 'PDV-RS-10-2-5-3-OBJ', 0, '5', '3-OBJ', '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (145, '125', 'AE20', 'Zakon o Porezu na dodatu vrednost', '36b', '6', 'Promet investicionog zlata po poreskoj stopi od 20% za koji je poreski dužnik primalac, obveznik PDV', NULL, NULL, 'PDV-RS-36b-6', 0, NULL, NULL, '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (146, '126', 'AE10', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Prvi prenos prava raspolaganja na novoizgrađenim građevinskim objektima, ekonomski deljivih celina u okviru tih objekata i vlasničkih udela na tim dobrima, koji su predmet izvršenja u izvršnom postupku u skladu sa zakonom, izvršen od strane obveznika PDV, za koji je poreski dužnik primalac, obveznik PDV', NULL, NULL, 'PDV-RS-10-2-5-3-OBJ', 0, '5', '3-OBJ', '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (147, '127', 'R', 'Zakon o Porezu na dodatu vrednost', '6', 'ostalo', 'Promet za koji se smatra da nije izvršen iz člana 6. stav 1. tač. 2), 3) i 4) ZPDV).', NULL, NULL, 'PDV-RS-6-ostalo', 0, NULL, NULL, '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (148, '128', 'AE20', 'Zakon o Porezu na dodatu vrednost', '10', '1', 'Prvi prenos prava raspolaganja na novoizgrađenim građevinskim objektima, ekonomski deljivim celinama u okviru tih objekata, kao i vlasničkim udelima na novoizgrađenim građevinskim objektima ili ekonomski deljivim celinama u okviru tih objekata koji vrši strano lice koje u Republici nije obveznik PDV, za koji je poreski dužnik primalac', NULL, NULL, 'PDV-RS-10-1-3-OBJ', 0, '3', 'OBJ', '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (149, '129', 'AE10', 'Zakon o Porezu na dodatu vrednost', '10', '1', 'Prvi prenos prava raspolaganja na novoizgrađenim građevinskim objektima, ekonomski deljivim celinama u okviru tih objekata, kao i vlasničkim udelima na novoizgrađenim građevinskim objektima ili ekonomski deljivim celinama u okviru tih objekata, koji vrši strano lice koje u Republici nije obveznik PDV, za koji je poreski dužnik primalac', NULL, NULL, 'PDV-RS-10-1-3-OBJ', 0, '3', 'OBJ', '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (150, '130', 'AE10', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Promet sekundarnih sirovina i usluga koje su neposredno povezane sa tim dobrima, izvršen od strane obveznika PDV, za koji je poreski dužnik primalac, obveznik PDV', NULL, NULL, 'PDV-RS-10-2-1', 0, '1', NULL, '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (151, '131', 'AE10', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Promet građevinskih objekata i ekonomski deljivih celina u okviru tih objekata, uključujući i vlasničke udele na tim dobrima, izvršen od strane obveznika PDV drugom obvezniku PDV, u slučaju kada je ugovorom na osnovu kojeg se vrši promet tih dobara predviđeno da će se na taj promet obračunati PDV u skladu sa ZPDV, za koji je poreski dužnik primalac', NULL, NULL, 'PDV-RS-10-2-2', 0, '2', NULL, '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (152, '132', 'AE10', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Promet dobara i usluga iz oblasti građevinarstva, izvršen od strane obveznika PDV, za koji je poreski dužnik primalac, obveznik  PDV, odnosno lice iz člana 9. stav 1. ZPDV', NULL, NULL, 'PDV-RS-10-2-3', 0, '3', NULL, '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (153, '133', 'AE10', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Promet električne energije i prirodnog gasa koji se isporučuju preko prenosne, transportne i distributivne mreže, izvršen od strane obveznika PDV, za koji je poreski dužnik primalac, obveznik PDV, koji je ova dobra nabavio radi dalje prodaje', NULL, NULL, 'PDV-RS-10-2-4', 0, '4', NULL, '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (154, '134', 'AE10', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Promet hipotekovane nepokretnosti kod realizacije hipoteke u skladu sa zakonom kojim se uređuje hipoteka, izvršen od strane obveznika  PDV, za koji je poreski dužnik primalac, obveznik PDV', NULL, NULL, 'PDV-RS-10-2-5-1', 0, '5', '1', '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (155, '135', 'AE10', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Promet predmeta založnog prava kod realizacije ugovora o zalozi u skladu sa zakonom kojim se uređuje založno pravo na pokretnim stvarima, izvršen od strane obveznika PDV, za koji je poreski dužnik primalac, obveznik PDV', NULL, NULL, 'PDV-RS-10-2-5-2', 0, '5', '2', '1900-01-01 00:00:00', NULL);
INSERT INTO `pdv_reasons` VALUES (156, '136', 'AE10', 'Zakon o Porezu na dodatu vrednost', '10', '2', 'Promet dobara ili usluga nad kojima se sprovodi izvršenje u izvršnom postupku u skladu sa zakonom, sa izuzetkom prvog prenosa prava raspolaganja na novoizgrađenim građevinskim objektima, ekonomski deljivih celina u okviru tih objekata i vlasničkih udela na tim dobrima, izvršen od strane obveznika PDV, za koji je poreski dužnik primalac dobara ili usluga, obveznik PDV', NULL, NULL, 'PDV-RS-10-2-5-3', 0, '5', '3', '1900-01-01 00:00:00', NULL);
