-- ----------------------------
-- Table structure for absence
-- ----------------------------
DROP TABLE IF EXISTS `absence`;
CREATE TABLE `absence`  (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `FK_employee` int(11) NULL DEFAULT NULL,
  `added_absence` int(11) NULL DEFAULT NULL,
  `date` date NULL DEFAULT NULL,
  `dateFrom` date NULL DEFAULT NULL,
  `dateTo` date NULL DEFAULT NULL,
  `days` int(11) NULL DEFAULT NULL,
  `remaining_days` int(11) NULL DEFAULT NULL,
  `note` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `FK_absence_types` int(11) NULL DEFAULT NULL,
  `FK_absence_subtypes` int(11) NULL DEFAULT NULL,
  `FK_document` int(11) NULL DEFAULT NULL,
  `has_documentation` tinyint(1) NOT NULL DEFAULT 0,
  `whoApproves` int(11) NULL DEFAULT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `FK_absence_employee`(`FK_employee`) USING BTREE,
  INDEX `FK_absence_employee_2`(`added_absence`) USING BTREE,
  INDEX `FK_absence_document`(`FK_document`) USING BTREE,
  INDEX `FK_absence_absence_types`(`FK_absence_types`) USING BTREE,
  INDEX `FK_absence_absence_subtypes`(`FK_absence_subtypes`) USING BTREE,
  INDEX `FK_absence_employee_3`(`whoApproves`) USING BTREE,
  CONSTRAINT `FK_absence_absence_subtypes` FOREIGN KEY (`FK_absence_subtypes`) REFERENCES `absence_subtypes` (`ID`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `FK_absence_absence_types` FOREIGN KEY (`FK_absence_types`) REFERENCES `absence_types` (`ID`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `FK_absence_document` FOREIGN KEY (`FK_document`) REFERENCES `document` (`ID`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `FK_absence_employee` FOREIGN KEY (`FK_employee`) REFERENCES `employee` (`ID`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `FK_absence_employee_2` FOREIGN KEY (`added_absence`) REFERENCES `employee` (`ID`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `FK_absence_employee_3` FOREIGN KEY (`whoApproves`) REFERENCES `employee` (`ID`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

