-- ----------------------------
-- Table structure for absence_request_dates
-- ----------------------------
DROP TABLE IF EXISTS `absence_request_dates`;
CREATE TABLE `absence_request_dates`  (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `request_id` int(11) NOT NULL,
  `date_from` date NOT NULL,
  `date_until` date NULL DEFAULT NULL,
  `has_orv_intervals` tinyint(4) NULL DEFAULT NULL COMMENT 'Kada se unose datumi u ovu tabelu ukoliko korisnik ima orv, intervali u absence request ce se pocepati u pod intervale odredjene neradnim danima u organizaciji radnog vremena. Kada je to slucaj na ovo polje ce se upisati 1 sto ce znaciti da se do tih intervala doslo proverom organizacije radnog vremena. Originalni poredak intervala bice sacuvan preko polja interval_no.',
  `interval_no` int(11) NULL DEFAULT NULL COMMENT 'Sluzi da sacuva stari poredak vremenskih intervala kod uzimanja u obzir organizacije radnog vremena. Intervali koji su grupisani pod istim brojem, pripadaju istom intervalu iz originalnog zahteva',
  `created_at` timestamp(0) NULL DEFAULT CURRENT_TIMESTAMP(0),
  `updated_at` timestamp(0) NULL DEFAULT CURRENT_TIMESTAMP(0),
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 1 CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = FIXED;

