-- Records of absence_request_dates
-- ----------------------------

-- ----------------------------
-- Table structure for absence_request_has_documents
-- ----------------------------
DROP TABLE IF EXISTS `absence_request_has_documents`;
CREATE TABLE `absence_request_has_documents`  (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `request_id` int(11) NOT NULL,
  `employeeID` int(11) NOT NULL COMMENT 'ID zaposlenog na koga se odnosi odsustvo',
  `tip` varchar(45) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'tip odsustva',
  `podtip` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT 'podtip odsustva',
  `document_id` int(11) NOT NULL,
  `isGenerated` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0 - nije generisan od strane programa, 1 - jeste generisan od strane programa',
  `created_at` timestamp(0) NULL DEFAULT CURRENT_TIMESTAMP(0),
  `updated_at` timestamp(0) NULL DEFAULT CURRENT_TIMESTAMP(0),
  `del_doc` smallint(6) NOT NULL DEFAULT 0 COMMENT '0 - dokument nije u delovodniku (fizicki fajl); 1 - dokument je u delovodniku; 2 - generisani dokument',
  `decision_year` smallint(4) NOT NULL DEFAULT 0 COMMENT 'Upisuje se godina na koju se odnosi rešenje o GO',
  `isKolektivniGo` tinyint(1) NOT NULL DEFAULT 0,
  `is_signed` tinyint(4) NULL DEFAULT 0,
  `signed_by` int(11) NULL DEFAULT NULL,
  `deleted` tinyint(4) NOT NULL DEFAULT 0 COMMENT 'ako se obriše zahtev ovo polje prelazi u 1, po defaultu je 0',
  `empty_doc` tinyint(4) NULL DEFAULT NULL,
  `main_doc` tinyint(4) NULL DEFAULT NULL,
  `is_readed` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `action` int(11) NULL DEFAULT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 1 CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = DYNAMIC;

