-- ----------------------------
-- Table structure for absence_requests
-- ----------------------------
DROP TABLE IF EXISTS `absence_requests`;
CREATE TABLE `absence_requests`  (
  `id` int(11) UNSIGNED NOT NULL AUTO_INCREMENT,
  `type` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'zahtev - 1, obavestenje - 0',
  `requestDate` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0),
  `requestDate_auto` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0),
  `whoSent` int(11) NULL DEFAULT NULL,
  `emplID` int(11) NULL DEFAULT NULL,
  `groupID` int(11) NULL DEFAULT NULL,
  `absenceTypeID` int(11) NULL DEFAULT NULL,
  `absenceSubTypeID` int(11) NULL DEFAULT NULL,
  `absence_days` int(11) NULL DEFAULT NULL,
  `lastYear` varchar(4) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT 'unosi se prošla godina',
  `lastYearDays` varchar(4) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT 'unosi se traženi broj dana za prošlu godinu',
  `currYear` varchar(4) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT 'unosi se tekuća godina',
  `currYearDays` varchar(4) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT 'unosi se traženi broj dana za tekuću godinu',
  `nextYear` varchar(4) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT 'unosi se sledeća godina',
  `nextYearDays` varchar(4) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0' COMMENT 'unosi se traženi broj dana za sledeću godinu',
  `structure_or_employee_absence` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `sendEmailFlag` tinyint(4) NULL DEFAULT 0 COMMENT '0 -  ne salji email obavestenja, 1 - salji eamil obavestenja ( na zahtev/odobravanje/izmenu )',
  `comment` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `statusID` int(11) NULL DEFAULT NULL,
  `isKolektivniGo` tinyint(4) NOT NULL DEFAULT 0,
  `proceduraID` int(11) NULL DEFAULT NULL,
  `flag_id_as_replacement_for_absence_subtype` int(11) NULL DEFAULT NULL COMMENT 'U situaciji kada imamo tip odsustva \'Odsustvo sa mesta rada (tip 11)\', tada ne postoji podtip odsustva vec umesto njega imamo vrednost ID-a zastavice iz tabele \'zastavice_odsustvo_sa_mesta_rada\'',
  `datumPorodjaja` date NULL DEFAULT NULL,
  `detePoReduRodjenja` int(11) NULL DEFAULT NULL COMMENT 'Oznacava redosledni broj rodjenja deteta. Ova tabela ima informacije jedino podtip 18,19,20',
  `created_at` timestamp(0) NULL DEFAULT CURRENT_TIMESTAMP(0),
  `updated_at` timestamp(0) NULL DEFAULT CURRENT_TIMESTAMP(0),
  `isSlava_flag` tinyint(1) NULL DEFAULT NULL COMMENT 'Ako je zahtev napravljen sa bekpart dela ili editovanja privatnih informacija zaposlenog, koji ima Kancelarko flag \'createdFromKancelarko\' = 1. Onda se popunjava ova kolona sa: \r\n1 - vezan za kancelarko i ima flag za slavu - radi lakseg manipulisanja (ubaceno zbog delete/edit slave sa privatnih informacija zaposlenog),',
  `createdFromKancelarko` tinyint(1) NULL DEFAULT NULL COMMENT '1 - kreirano od strane aplikacije Kancelarko, trenutno se koristi kod publikovanja godine/praznika, privatnih informacija zaposlenih o veroispovesti i/ili slave',
  `odobreno` tinyint(4) NOT NULL DEFAULT 0,
  `tipPraznika` tinyint(1) NULL DEFAULT NULL COMMENT '1 - odluka, 2 - resenje',
  `solveDate` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP(0),
  `action` int(11) NULL DEFAULT NULL COMMENT 'status odobreno ali neuruceno - 1\r\nstatus odobreno ali uruceno i nije procitano - 2\r\nstatus odobreno ali uruceno i procitano - 3\r\n\r\nstatus ponisteno ali neuruceno - 4\r\nstatus ponisteno ali uruceno i nije procitano - 5\r\nstatus ponisteno ali uruceno i procitano - 6\r\n\r\nstatus izmenjeno ali neuruceno - 7\r\nstatus izmenjeno ali uruceno i nije procitano - 8\r\nstatus izmenjeno ali uruceno i procitano - 9',
  `deliveredTime` datetime(0) NULL DEFAULT NULL,
  `showFlag` tinyint(4) NULL DEFAULT NULL COMMENT 'Ako je vrednost flaga 1 to znaci da ga nigde necemo prikazivati i voditi evidenciju o njemu',
  `approvedBy` int(11) NULL DEFAULT NULL COMMENT 'ID zaposlenog koji je odobrio zahtev za odsustvo',
  `deleted_at` int(11) NULL DEFAULT NULL,
  `deletedBy` int(11) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

