  `created_at` timestamp(0) NULL DEFAULT CURRENT_TIMESTAMP(0),
  `updated_at` timestamp(0) NULL DEFAULT CURRENT_TIMESTAMP(0),
  `isSlava_flag` tinyint(1) NULL DEFAULT NULL COMMENT 'Ako je zahtev napravljen sa bekpart dela ili editovanja privatnih informacija zaposlenog, koji ima Kancelarko flag \'createdFromKancelarko\' = 1. Onda se popunjava ova kolona sa: \r\n1 - vezan za kancelarko i ima flag za slavu - radi lakseg manipulisanja (ubaceno zbog delete/edit slave sa privatnih informacija zaposlenog),',
  `createdFromKancelarko` tinyint(1) NULL DEFAULT NULL COMMENT '1 - kreirano od strane aplikacije Kancelarko, trenutno se koristi kod publikovanja godine/praznika, privatnih informacija zaposlenih o veroispovesti i/ili slave',
  `odobreno` tinyint(4) NOT NULL DEFAULT 0,
  `tipPraznika` tinyint(1) NULL DEFAULT NULL COMMENT '1 - odluka, 2 - resenje',
  `solveDate` datetime(0) NULL DEFAULT CURRENT_TIMESTAMP(0),
  `action` int(11) NULL DEFAULT NULL COMMENT 'status odobreno ali neuruceno - 1\r\nstatus odobreno ali uruceno i nije procitano - 2\r\nstatus odobreno ali uruceno i procitano - 3\r\n\r\nstatus ponisteno ali neuruceno - 4\r\nstatus ponisteno ali uruceno i nije procitano - 5\r\nstatus ponisteno ali uruceno i procitano - 6\r\n\r\nstatus izmenjeno ali neuruceno - 7\r\nstatus izmenjeno ali uruceno i nije procitano - 8\r\nstatus izmenjeno ali uruceno i procitano - 9',
  `deliveredTime` datetime(0) NULL DEFAULT NULL,
  `showFlag` tinyint(4) NULL DEFAULT NULL COMMENT 'Ako je vrednost flaga 1 to znaci da ga nigde necemo prikazivati i voditi evidenciju o njemu',
  `approvedBy` int(11) NULL DEFAULT NULL COMMENT 'ID zaposlenog koji je odobrio zahtev za odsustvo',
  `deleted_at` int(11) NULL DEFAULT NULL,
  `deletedBy` int(11) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = 'kopija tabele \'absence_requests\' sa par dodatnih kolona. Ukoliko se desi neka promena u originalnoj tabeli, to se mora reflektovati i u ovoj tabeli' ROW_FORMAT = DYNAMIC;

