  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `criteriaGroup` int(11) NOT NULL,
  `criteriaID` int(11) NOT NULL,
  `termination_reason` enum('0','1','2') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '0' COMMENT '0 - Automatski, 1 - Izmena opšteg akta, 2 - Izmena ugovora o radu',
  `termination_doc_date` date NULL DEFAULT NULL COMMENT 'datum kada je donesen dokument koji gasi kriterijum (izmena opšteg akta ili izmena ugovora o radu)',
  `criteria_start_date` date NULL DEFAULT NULL COMMENT 'datum od kada važi kriterijum',
  `criteria_end_date` date NULL DEFAULT NULL COMMENT 'datum kada je prestao da važi kriterijum',
  `archive_date` date NOT NULL COMMENT 'datum kada samo arhivirali kriterijum',
  `unarchive_date` date NULL DEFAULT NULL COMMENT 'ovde se upisuje datum ako se kriterijum vraća u upotrebu',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 1 CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = FIXED;

