DROP TABLE IF EXISTS `case_blueprints_stavka`;
CREATE TABLE `case_blueprints_stavka`  (
  `ID` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `caseID` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `fakturaID` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `naziv` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0',
  `opis` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `datum` datetime(0) NULL DEFAULT '0000-00-00 00:00:00',
  `tip` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `podtip` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `radnovremeID` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `suma` decimal(13, 2) NULL DEFAULT 0.00,
  `valuta` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `kurs` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `pdv` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `zaposleniID` int(10) NULL DEFAULT NULL,
  `employeeID` int(10) NULL DEFAULT NULL,
  `clientID` int(10) NULL DEFAULT NULL,
  `clientType` enum('fizicko','pravno') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'fizicko',
  `sumaPdv` decimal(13, 2) NULL DEFAULT 0.00,
  `status_sv` tinyint(3) NULL DEFAULT 0,
  `status_go` tinyint(3) NULL DEFAULT 0,
  `originalnoTarif` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `clientFakturaID` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `satnica` decimal(13, 2) NULL DEFAULT NULL,
  `brojSati` decimal(13, 2) NULL DEFAULT NULL,
  `brojMinuta` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `popustID` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `tipPoslaID` int(10) NULL DEFAULT NULL,
  `kolicina` decimal(13, 4) NULL DEFAULT NULL,
  `discount_type` int(10) NULL DEFAULT NULL,
  `discount_stavka` decimal(13, 2) NULL DEFAULT 0.00,
  `discount_original_price` decimal(13, 2) NULL DEFAULT 0.00,
  `whoWorked` int(10) NULL DEFAULT NULL,
  `mamaStavka` int(10) NULL DEFAULT NULL,
  `mamaStavkaDescription` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `jedinicaMere` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `vrsta` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `oznakaID` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `rabatProc` decimal(13, 2) NULL DEFAULT NULL,
  `iznos` decimal(13, 2) NULL DEFAULT NULL,
  `krajnjaCena` decimal(13, 2) NULL DEFAULT NULL,
  `altID` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `barKod` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `altBarKod` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `lot` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `proizvedeno` datetime(0) NULL DEFAULT NULL,
  `trajeDo` datetime(0) NULL DEFAULT '0000-00-00 00:00:00',
  `ArticleID` int(10) NULL DEFAULT NULL,
  `UnitID` int(10) NULL DEFAULT NULL,
  `naslov` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `podNaslov` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

