DROP TABLE IF EXISTS `case_faktura`;
CREATE TABLE `case_faktura`  (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `ppID` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `izdavalacID` int(11) NULL DEFAULT 0,
  `primaocID` int(11) NULL DEFAULT 0,
  `primaocTip` tinyint(1) NULL DEFAULT NULL,
  `validData` tinyint(1) NULL DEFAULT 0 COMMENT '0 - nije obezbedjen minimalni set podataka, nemoze da se koristi u programu, 1 - obezbedjen je minimalni set podataka',
  `addressID` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `ppNaziv` varchar(250) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `ppAdresa` varchar(155) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `ppPib` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `ppMB` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `ppjbkjs` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `ppNosilacJn` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `napomena` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `beleska` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `brojFakture` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `datumFakture` date NOT NULL DEFAULT '0000-00-00',
  `valutaPlacanja` date NULL DEFAULT NULL,
  `mesto` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `ukupno` decimal(13, 2) NOT NULL DEFAULT 0.00,
  `sumapdv` decimal(13, 2) NOT NULL DEFAULT 0.00,
  `rounding` decimal(13, 2) NULL DEFAULT NULL,
  `sumatotal` decimal(13, 2) NOT NULL DEFAULT 0.00,
  `ukupnoSlovima` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `avanstotal` decimal(13, 2) NULL DEFAULT 0.00,
  `status` int(11) NOT NULL DEFAULT 0,
  `datumKreiranja` datetime(0) NOT NULL DEFAULT '0000-00-00 00:00:00',
  `employeeID` int(10) NULL DEFAULT 0,
  `caseID` int(11) NOT NULL DEFAULT 0,
  `markGeneralNote` tinyint(4) NULL DEFAULT 0,
  `valutaFakture` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `valutaPlacanjaTekst` text CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `beleskaZaFinansije` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `valutaPlacanjaBeleska` date NULL DEFAULT NULL,
  `archived` tinyint(4) NULL DEFAULT 0,
  `invoice_from` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `invoice_from_address` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `invoice_chosen_header` int(11) NULL DEFAULT NULL,
  `invoice_chosen_footer` int(11) NULL DEFAULT NULL,
  `invoice_chosen_seal` int(11) NULL DEFAULT NULL,
  `invoice_chosen_signature` int(11) NULL DEFAULT NULL,
  `invoice_chosen_broj_racuna` int(11) NULL DEFAULT NULL,
  `invoice_chosen_nbs_ips_qr` int(11) NULL DEFAULT NULL,
  `popustID` int(11) NULL DEFAULT NULL,
  `doneInvoice` int(11) NULL DEFAULT 0,
  `sentInvoiceID` int(11) NULL DEFAULT NULL,
  `file` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `ubl` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `office_master_subjectID` int(11) NULL DEFAULT NULL,
  `status_odobrenje` int(11) NULL DEFAULT NULL,
  `PDV_broj` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `taken` int(11) NULL DEFAULT 0,
  `locked` tinyint(4) NULL DEFAULT 0,
  `robno` tinyint(1) NOT NULL DEFAULT 0,
  `datum_prometa` date NULL DEFAULT NULL,
  `dobavljacID` int(11) NULL DEFAULT NULL,
  `kurs` decimal(13, 4) NULL DEFAULT 0.0000,
  `fakturaFileID` int(11) NULL DEFAULT NULL,
  `instrukcijePlacanjaID` int(11) NULL DEFAULT NULL,
  `tipRacuna` tinyint(1) NULL DEFAULT 0 COMMENT '0 - faktura, 1 - profaktura, 2 - avansi racun, 3 - knjizno odobrenje, 4 - knjizno zaduzenje',
  `podtipRacuna` tinyint(1) NULL DEFAULT 0 COMMENT '0 - 1 na 1, 1 - vise na vise, 2 - period',
  `date_from` date NULL DEFAULT NULL,
  `date_to` date NULL DEFAULT NULL,
  `case_faktura_id` int(11) NULL DEFAULT NULL,
  `datumUplate` datetime(0) NULL DEFAULT NULL,
  `mestoPrometa` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `jezikFakture` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `jezikFakture2` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `otpremnica` tinyint(1) NULL DEFAULT 0,
  `konacna` tinyint(1) NULL DEFAULT 0,
  `show_original` tinyint(1) NULL DEFAULT 0,
  `sef_invoice_id` int(11) UNSIGNED NULL DEFAULT NULL,
  `sef_selesInvoice_id` int(11) UNSIGNED NULL DEFAULT NULL,
  `sef_unique_string` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `pdv_datum_obracuna` int(11) NULL DEFAULT NULL COMMENT '\'3 - pdv se obracunava na dan prometa, 35- pdv se obracunava na dan slanja fakture, 432 - pdv se obracunava na dan placanja\' AFTER `pdv_reasons_id`,',
  `stornirao` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `signed` int(11) NULL DEFAULT 0,
  `broj_narudzbenice` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `broj_tendera` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `sifraObjekta` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `interniBroj` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `ppjbkjs_old` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0',
  `ppID_old` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0',
  `duplikat` int(11) NULL DEFAULT NULL,
  `broj_otpremnice` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `broj_prijemnice` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `sifra_objekta_isporuke` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `id_lokacija_isporuke` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `ulica_isporuke` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `grad_isporuke` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `drzava_isporuke` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `zip_isporuke` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `umanjenje10` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenje20` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenjeE` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenjeO` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenjeAE` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenjeAE10` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenjeAE20` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenjeR` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenjeZ` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenjeSS` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenjeOE` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenjeN` decimal(13, 2) NULL DEFAULT 0.00,
  `OrderReferenceDate` date NULL DEFAULT NULL,
  `InvoiceDocumentReferenceDate` date NULL DEFAULT NULL,
  `DespatchDocumentReferenceDate` date NULL DEFAULT NULL,
  `ReceiptDocumentReferenceDate` date NULL DEFAULT NULL,
  `glnSender` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `glnReceiver` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `sifraPlacanja30` tinyint(4) NULL DEFAULT NULL COMMENT 'Da li je cekirano da se ne koristi sifra placanja 30',
  `brFakturePrefix` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `brFaktureMain` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `brFaktureYear` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `potpisanaIzjava` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `group_vat_prepare_add_item` tinyint(4) NULL DEFAULT 0,
  `needsToBeVATRecorded` tinyint(4) NULL DEFAULT 0,
  `no_pdf` tinyint(1) NULL DEFAULT 0 COMMENT '0 - kreiran kancelarko pdf fakture, 1 - nije krerian kancelarko pdf fakture',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `sefUniqueString`(`sef_unique_string`) USING BTREE,
  INDEX `case_faktura_sentInvoiceID_idx`(`sentInvoiceID`) USING BTREE,
  INDEX `case_faktura_id`(`case_faktura_id`) USING BTREE,
  INDEX `izdavalacID`(`izdavalacID`) USING BTREE,
  INDEX `primaocID`(`primaocID`) USING BTREE,
  FULLTEXT INDEX `brojFakture`(`brojFakture`)
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

