  `sumapdv` decimal(13, 2) NOT NULL DEFAULT 0.00,
  `rounding` decimal(13, 2) NULL DEFAULT NULL,
  `sumatotal` decimal(13, 2) NOT NULL DEFAULT 0.00,
  `ukupnoSlovima` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '0',
  `avanstotal` decimal(13, 2) NULL DEFAULT 0.00,
  `status` int(11) NOT NULL DEFAULT 0,
  `datumKreiranja` datetime(0) NOT NULL DEFAULT '0000-00-00 00:00:00',
  `employeeID` int(10) NULL DEFAULT 0,
  `valutaFakture` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `sentInvoiceID` int(11) NULL DEFAULT NULL,
  `file` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `ubl` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `office_master_subjectID` int(11) NULL DEFAULT NULL,
  `PDV_broj` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
