  `podtipRacuna` tinyint(1) NULL DEFAULT 0 COMMENT '0 - 1 na 1, 1 - vise na vise, 2 - period',
  `date_from` date NULL DEFAULT NULL,
  `date_to` date NULL DEFAULT NULL,
  `case_faktura_id` int(11) NULL DEFAULT NULL,
  `datumUplate` datetime(0) NULL DEFAULT NULL,
  `mestoPrometa` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `show_original` tinyint(1) NULL DEFAULT 0,
  `sef_invoice_id` int(11) UNSIGNED NULL DEFAULT NULL,
  `sef_selesInvoice_id` int(11) UNSIGNED NULL DEFAULT NULL,
  `pdv_datum_obracuna` int(11) NULL DEFAULT NULL COMMENT '\'3 - pdv se obracunava na dan prometa, 35- pdv se obracunava na dan slanja fakture, 432 - pdv se obracunava na dan placanja\' AFTER `pdv_reasons_id`,',
  `stornirao` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `broj_narudzbenice` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
