  `sifraObjekta` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `interniBroj` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `broj_ugovora` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `broj_otpremnice` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `broj_prijemnice` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `sifra_objekta_isporuke` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `id_lokacija_isporuke` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `ulica_isporuke` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `grad_isporuke` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `drzava_isporuke` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `zip_isporuke` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `umanjenje10` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenje20` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenjeE` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenjeO` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenjeAE` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenjeAE10` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenjeAE20` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenjeR` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenjeZ` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenjeSS` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenjeOE` decimal(13, 2) NULL DEFAULT 0.00,
  `umanjenjeN` decimal(13, 2) NULL DEFAULT 0.00,
  `OrderReferenceDate` date NULL DEFAULT NULL,
  `InvoiceDocumentReferenceDate` date NULL DEFAULT NULL,
  `DespatchDocumentReferenceDate` date NULL DEFAULT NULL,
  `ReceiptDocumentReferenceDate` date NULL DEFAULT NULL,
  `glnSender` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `glnReceiver` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `processed` tinyint(1) NULL DEFAULT 0 COMMENT '0 - nije preuzeta sa SEF nalazi se samo u e-Faktura lite modulu, 1 - preuzeta je sa SEF i nalazi se u kancelarku',
  `sde_lite_id` int(11) NULL DEFAULT NULL,
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `izdavalacID_ind`(`izdavalacID`) USING BTREE,
  INDEX `primaocID_ind`(`primaocID`) USING BTREE,
  FULLTEXT INDEX `brojFakture_ft`(`brojFakture`)
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

