-- ----------------------------
-- Table structure for document
-- ----------------------------
DROP TABLE IF EXISTS `document`;
CREATE TABLE `document`  (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `modulType` enum('DOC','OBL','TASK','CASE') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'DOC',
  `uploaderID` int(11) NULL DEFAULT NULL,
  `documentName` varchar(245) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `createTime` datetime(0) NULL DEFAULT NULL,
  `dateOfEntry` date NULL DEFAULT NULL,
  `documentDescription` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `referenceNumber` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `documentRemark` text CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL,
  `documentLanguageID` int(11) NULL DEFAULT NULL,
  `documentLink` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `documentLinkNote` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `digitalSign` tinyint(1) NULL DEFAULT 0,
  `signedDate` date NULL DEFAULT NULL COMMENT 'Datum donosenja/zakljucenja dokumenta/ugovora',
  `signedByDate` date NULL DEFAULT NULL COMMENT 'Ovo je datum potpisivanja',
  `useFrom` datetime(0) NULL DEFAULT NULL,
  `useTo` datetime(0) NULL DEFAULT NULL,
  `sendDate` datetime(0) NULL DEFAULT NULL,
  `receivedDate` datetime(0) NULL DEFAULT NULL,
  `replayDate` date NULL DEFAULT NULL,
  `fileEditID` int(11) NULL DEFAULT NULL,
  `fileFinalID` int(11) NULL DEFAULT NULL,
  `workOrderID` int(11) NULL DEFAULT NULL,
  `oldWorkOrderID` int(11) NULL DEFAULT NULL,
  `previousVersionID` int(11) NULL DEFAULT NULL,
  `validDocument` tinyint(1) NULL DEFAULT 1,
  `autoStatus` tinyint(1) NULL DEFAULT 0,
  `stopValidDate` date NULL DEFAULT NULL,
  `stopValidByID` int(11) NULL DEFAULT NULL,
  `versionGroupID` int(11) NULL DEFAULT NULL,
  `forDelete` int(11) NULL DEFAULT NULL,
  `forDeleteTime` datetime(0) NULL DEFAULT NULL,
  `documentIsTemplate` int(11) NOT NULL DEFAULT 0,
  `massAdd` int(11) NOT NULL DEFAULT 0,
  `price` decimal(13, 2) NULL DEFAULT NULL,
  `priceCurrency` int(11) NULL DEFAULT NULL,
  `documentPriority` int(11) NULL DEFAULT NULL,
  `groupHash` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `parentID` int(11) NULL DEFAULT NULL,
  `startRepetition` datetime(0) NULL DEFAULT NULL,
  `endRepetition` datetime(0) NULL DEFAULT NULL,
  `groupHashHistory` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `rType` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `rInterval` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `rPeriod` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `kaznaSlobodanUnos` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `fromModul` enum('Principal','Delovodnik','SelfAdmin','Postar') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT 'Principal',
  `deleteTime` timestamp(0) NULL DEFAULT NULL,
  `deleteTimeFlag` int(11) NOT NULL DEFAULT 0 COMMENT 'Da li je brisanje preko foldera',
  `expirationDate` date NULL DEFAULT NULL,
  `izvorniFormat` int(11) NULL DEFAULT NULL,
  `izvorniFormatPapirniTip` enum('KOPIJA','DIGITALIZOVANI') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `datumNastanka` date NULL DEFAULT NULL,
  `rokCuvanja` date NULL DEFAULT NULL,
  `datumDogadjaja` date NULL DEFAULT NULL,
  `indexed` int(11) NULL DEFAULT NULL COMMENT 'null,0 - nije ni poslat na indexiranje, 1 - indeksiran, 2 - poslat na indeksiranje, ceka se zavrsetak, 3 - nije poslat na indexiranja jer u datom trenutku nije bila dovoljna kolicina kredita, 4 - doslo je do greske pri indeksiranju, 5 - uradjen je ocr, ali dokument nije indexiran',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `documentLanguage_idx`(`documentLanguageID`) USING BTREE,
  INDEX `uploaderID_idx`(`uploaderID`) USING BTREE,
  INDEX `DocworkOrderID_idx`(`workOrderID`) USING BTREE,
  CONSTRAINT `documentLanguage` FOREIGN KEY (`documentLanguageID`) REFERENCES `document_language` (`ID`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `uploaderID` FOREIGN KEY (`uploaderID`) REFERENCES `employee` (`ID`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

