-- ----------------------------
-- Table structure for employee
-- ----------------------------
DROP TABLE IF EXISTS `employee`;
CREATE TABLE `employee`  (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `firstname` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `lastname` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `defaultEmail` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `businessEmail` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `remark` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `employeeImg` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `create_date` datetime(0) NULL DEFAULT NULL,
  `FK_address` int(11) NULL DEFAULT NULL,
  `FK_address_of_current_residence` int(11) NULL DEFAULT NULL,
  `FK_address_of_birth` int(11) NULL DEFAULT NULL,
  `FK_gender` int(11) NULL DEFAULT NULL,
  `birth_date` date NULL DEFAULT NULL,
  `birth_time` time(0) NULL DEFAULT NULL,
  `identification_number` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `FK_citizenships` int(11) NULL DEFAULT NULL,
  `birth_first_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `birth_last_name` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `FK_birth_gender` int(11) NULL DEFAULT NULL,
  `FK_blood_type` int(11) NULL DEFAULT NULL,
  `FK_marital_status` int(11) NULL DEFAULT NULL,
  `FK_military` int(11) NULL DEFAULT NULL,
  `FK_religion` int(11) NULL DEFAULT NULL,
  `religionTypeOfCalendar` tinyint(1) NULL DEFAULT NULL COMMENT 'null - nema izabranu veroispovest\'pravoslavlje\', za zivu bazu je opet null iako ima religiju \'pravoslavlje\' (mora da adaptira podatke u privatnim informacijama)\r\n1 - za veroispovest \'pravoslavlje\' je izabran gregorijanski kalendar\r\n2 - za veroispovest \'pravoslavlje\' je izabran julijanski kalendar',
  `FK_family_religion_day` int(11) NULL DEFAULT NULL,
  `isFamilyReligionDaySelected` tinyint(1) NULL DEFAULT NULL COMMENT 'null - nije selektovana opcija ne zeli da se izjasni\r\n1 - selektovana opcija ne zeli da se izjasni',
  `private_note` varchar(1000) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `parental_right_executor` tinyint(1) NULL DEFAULT NULL,
  `caregiver_status` tinyint(1) NULL DEFAULT NULL,
  `session_duration` enum('30','60','90','120') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '30',
  `FK_employee_has_title` int(11) NULL DEFAULT NULL,
  `archived` tinyint(1) NULL DEFAULT 0,
  `dateForArchiving` date NULL DEFAULT NULL,
  `archivingByEmployeeID` int(11) NULL DEFAULT NULL,
  `FK_employee_cv` int(11) NULL DEFAULT NULL,
  `year_experience` int(11) NULL DEFAULT NULL,
  `month_experience` int(11) NULL DEFAULT NULL,
  `day_experience` int(11) NULL DEFAULT NULL,
  `work_time` varchar(4) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `part_time_work` tinyint(1) NULL DEFAULT NULL,
  `other_employer_work_time` varchar(4) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `day_birth` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `month_birth` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `year_birth` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `inv_bank_account` int(11) NOT NULL DEFAULT 0,
  `inv_description` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `inv_pdv` int(11) NULL DEFAULT 0,
  `inv_pdv_val` int(11) NULL DEFAULT 0,
  `pay_num` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `eksterni` tinyint(1) NULL DEFAULT 0,
  `voziloID` int(11) UNSIGNED NULL DEFAULT NULL,
  `saglasnost_GO` tinyint(4) NULL DEFAULT NULL COMMENT 'Saglasnost za korišćenje odmora jednokratno ili u više delova',
  `osnovna_zarada_NR` tinyint(1) NULL DEFAULT 0,
  `massFormHash` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `pasos` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `uniqueHash` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `kvalifikacija` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `koeficijentZarade` float(5, 2) NULL DEFAULT NULL,
  `naucno_zvanje_id` int(11) NULL DEFAULT NULL COMMENT 'Sadrži ID naučnog zvanja iz tabele \'settings_naucno_zvanje\'',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `FK_employee_address`(`FK_address`) USING BTREE,
