  `documentID` int(11) NULL DEFAULT NULL,
  `fileName` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `fileDirName` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `formID` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `fileSize` int(100) NULL DEFAULT NULL,
  `uploaderID` int(11) NULL DEFAULT NULL,
  `uploadTime` datetime(0) NULL DEFAULT NULL,
  `fileExt` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `uploaderName` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `fileTrackingID` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `server_id` int(11) NULL DEFAULT 0,
  `kancelarko` tinyint(1) NULL DEFAULT 0 COMMENT '0 - prop dokumentacije pridodata dokumentu, 1 - prop. dok. kopiran glavni fajl fakture',
  `indexed` int(11) NULL DEFAULT NULL COMMENT 'null,0 - nije ni poslat na indexiranje, 1 - indeksiran, 2 - poslat na indeksiranje, ceka se zavrsetak, 3 - nije poslat na indexiranja jer u datom trenutku nije bila dovoljna kolicina kredita, 4 - doslo je do greske pri indeksiranju, 5 - uradjen je ocr, ali dokument nije indexiran, 6 - ne moze se izvuci tekst iz fajla ili je prazan',
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `file_extra_documents_documentID_idx`(`documentID`) USING BTREE
