  `internalInvoiceOption` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `vatPeriod` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `year` year NULL DEFAULT NULL,
  `vatRecordingVersion` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'First',
  `turnoverDate` datetime(0) NULL DEFAULT NULL,
  `paymentDate` datetime(0) NULL DEFAULT NULL,
  `turnoverAmount` decimal(13, 2) NULL DEFAULT NULL COMMENT 'Ukupan iznos nadoknade',
  `turnoverDescription` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `turnoverDescription20` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `turnoverDescription10` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `vatBaseAmount20` decimal(13, 2) NULL DEFAULT NULL COMMENT 'Osnovica PDV po stopi 20%',
  `vatBaseAmount10` decimal(13, 2) NULL DEFAULT NULL COMMENT 'Osnovica PDV po stopi 10%',
  `vatAmount20` decimal(13, 2) NULL DEFAULT NULL COMMENT 'Obracunati PDV po stopi od 20',
  `vatAmount10` decimal(13, 2) NULL DEFAULT NULL COMMENT 'Obracunati PDV po stopi od 10',
  `vatAmount` decimal(13, 2) NULL DEFAULT NULL,
  `totalAmount` decimal(13, 2) NULL DEFAULT NULL,
  `vatDeductionRight` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'None' COMMENT '[\'None\', \'Partially\', \'Fully\']',
  `documentDirection` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '[\'Outbound\', \'Inbound\']',
  `relatedPartyIdentifier` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `foreignDocument` tinyint(4) NULL DEFAULT NULL COMMENT 'Da li je faktura inostrana',
  `basisForPrepayment` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
