  `zakonskiMin` tinyint(4) NULL DEFAULT 0,
  `zakonskiMin_meseci` tinyint(4) NULL DEFAULT NULL COMMENT 'ako ima broj meseci, znaci da taj podtip odsustva zapravo gleda kalendarske dane, ne uzimajuci u obzir radne dane.',
  `zakonskiMax` tinyint(4) NULL DEFAULT 0,
  `zakonskiMax_meseci` tinyint(4) NULL DEFAULT NULL COMMENT 'ako ima broj meseci, znaci da taj podtip odsustva zapravo gleda kalendarske dane, ne uzimajuci u obzir radne dane.',
  `organizacioniMax` smallint(6) NULL DEFAULT NULL,
  `racunjanjeBrojDana` tinyint(1) NULL DEFAULT NULL COMMENT 'racunjanje po:\r\n1 - radnim danima\r\n2 - kalendarskim danima',
  `maxSmanjenjeZarade` double(5, 2) UNSIGNED NULL DEFAULT NULL,
  `procenatOpstiAkt` double(5, 2) UNSIGNED NULL DEFAULT NULL,
  `IO` tinyint(1) NULL DEFAULT NULL,
  `obavezanZahtev` tinyint(1) NULL DEFAULT NULL,
  `ponavljanje` enum('1','2','3','4','6','12') CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL DEFAULT NULL,
  `napomena` text CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL,
  `orgMaxIsEditable` tinyint(1) NULL DEFAULT 1,
