-- Table structure for kad_fixed_working_hours
-- ----------------------------
DROP TABLE IF EXISTS `kad_fixed_working_hours`;
CREATE TABLE `kad_fixed_working_hours`  (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `fleksibilno` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0 - radno vreme nije fleksibilno i kolone fleksibilno_val i  dnevni_fond_casova su null, 1 - radno vreme je fleksibilno i ima podataka u kolonama fleksibilno_val i dnevni_fond_casova',
  `fleksibilno_val` int(11) NULL DEFAULT NULL COMMENT 'Ova kolona ce sadrzati broj minuta za koje je neko radno vreme + fleksibilno.',
  `dnevni_fond_casova` datetime(0) NULL DEFAULT NULL COMMENT 'Ova kolona postoji samo ako je korisnik uneo fleksibilno radno vreme. Sadrzi ukupan broj radnih sati. Datum ce biti zakucan na 1971-01-01 nakon cega ce slediti sati.',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of kad_fixed_working_hours
-- ----------------------------

-- ----------------------------
-- Table structure for kad_fixed_working_time
-- ----------------------------
DROP TABLE IF EXISTS `kad_fixed_working_time`;
CREATE TABLE `kad_fixed_working_time`  (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `id_kad_fixed_wh` int(11) NOT NULL,
  `od` datetime(0) NOT NULL COMMENT 'fleksibilno: od kolona predstavlja pocetak felksibilnog radnog vremena. tada od ima vrednost i ova dva polja predstavljaju interval fleksibilnog radnog vremena kada zaposleni moze da dodje na posao. nije fleksibilno: od prestavlja pocetak ne fleksibilnog radnog vremena, a kraj radnog vremena sa nalazi u koloni do.',
  `od1` datetime(0) NULL DEFAULT NULL COMMENT 'fleksibilno: kolona od predstavlja do kada zaposleni moze da dodje na posao u tom radnom vremenu. nije fleksibilno: null.',
  `do` datetime(0) NOT NULL COMMENT 'fleksibilno: do predstavlja pocetak vremena kada zaposleni moze da ode sa posla, koje se zavrsava najdalje do do1. nije fleksibilno: predstavlja kraj radnog vremena koje je pocelo na polju od, polja od i do1 su null.',
  `do1` datetime(0) NULL DEFAULT NULL COMMENT 'fleksibilno: do1 predstavlja vreme kada zaposleni koji ima fleksibilno radno vreme moze naj kasnije da zavrsi radni dan a da nije usao u prekovremeni rad. nije fleksibilno: null.',
  `koristi_lokaciju_rada` tinyint(1) NULL DEFAULT NULL COMMENT '0 - Ne koristi lokaciju rada; 1 - Koristi lokaciju rada',
  `tip_prijave_lokacije_rada` tinyint(1) NULL DEFAULT NULL COMMENT '1 - Dozvoljava izbor lokacije radnog mesta zaposlenom prilikom prijave; 2 - Predefinisan izbor lokacije rada po danu orv-a; null - znaci da je vrednost u koloni koristi_lokaciju_rada jednaka 0',
  `id_lokacije_rada` int(11) NULL DEFAULT NULL COMMENT 'ID lokacije(mesta) rada iz tabele working_location',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = FIXED;

-- ----------------------------
-- Records of kad_fixed_working_time
-- ----------------------------

