-- ----------------------------
-- Table structure for kad_orv_radno_vreme
-- ----------------------------
DROP TABLE IF EXISTS `kad_orv_radno_vreme`;
CREATE TABLE `kad_orv_radno_vreme`  (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `od` datetime(0) NULL DEFAULT NULL COMMENT 'fleksibilno: od kolona predstavlja pocetak felksibilnog radnog vremena. tada od1 ima vrednost i ova dva polja predstavljaju interval fleksibilnog radnog vremena kada zaposleni moze da dodje na posao. nije fleksibilno: od prestavlja pocetak ne fleksibilnog radnog vremena, a kraj radnog vremena sa nalazi u koloni do.',
  `od1` datetime(0) NULL DEFAULT NULL,
  `do` datetime(0) NULL DEFAULT NULL COMMENT 'fleksibilno: do predstavlja pocetak vremena kada zaposleni moze da ode sa posla, koje se zavrsava najdalje do do1. nije fleksibilno: predstavlja kraj radnog vremena koje je pocelo na polju od, polja od1 i do1 su null.',
  `do1` datetime(0) NULL DEFAULT NULL,
  `id_employee_work_time` int(11) NULL DEFAULT NULL,
  `isDayOff` tinyint(1) NULL DEFAULT 0,
  `wp_putanja` text CHARACTER SET utf8 COLLATE utf8_unicode_ci NULL,
  `wp_id` int(11) NULL DEFAULT NULL,
  `wl_id` int(11) NULL DEFAULT NULL,
  `koristi_lokaciju_rada` tinyint(1) NULL DEFAULT NULL COMMENT '0 - Ne koristi lokaciju rada; 1 - Koristi lokaciju rada',
  `tip_prijave_lokacije_rada` tinyint(1) NULL DEFAULT NULL COMMENT '1 - Dozvoljava izbor lokacije radnog mesta zaposlenom prilikom prijave; 2 - Predefinisan izbor lokacije rada po danu orv-a; null - znaci da je vrednost u koloni koristi_lokaciju_rada jednaka 0',
  `rad_na_dan_praznika` tinyint(4) NULL DEFAULT NULL COMMENT 'null - u pitanju je neradan dan\r\n0 - dan je radan ali se ne radi na dan praznika\r\n1 - dan je radan i radi se na dan praznika',
  `created_at` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0),
  `updated_at` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0),
  PRIMARY KEY (`ID`) USING BTREE,
  INDEX `FK_kad_orv_radno_vreme_employee_work_time`(`id_employee_work_time`) USING BTREE,
  INDEX `FK_kad_orv_radno_vreme_structure_object`(`wp_id`) USING BTREE,
  INDEX `FK_kad_orv_radno_vreme_working_location`(`wl_id`) USING BTREE,
  CONSTRAINT `FK_kad_orv_radno_vreme_employee_work_time` FOREIGN KEY (`id_employee_work_time`) REFERENCES `employee_work_time` (`ID`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `FK_kad_orv_radno_vreme_structure_object` FOREIGN KEY (`wp_id`) REFERENCES `structure_object` (`ID`) ON DELETE NO ACTION ON UPDATE NO ACTION,
  CONSTRAINT `FK_kad_orv_radno_vreme_working_location` FOREIGN KEY (`wl_id`) REFERENCES `working_location` (`ID`) ON DELETE NO ACTION ON UPDATE NO ACTION
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_unicode_ci ROW_FORMAT = DYNAMIC;

