  `pdf` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `magacinID` int(11) NOT NULL,
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '0 - otvorena - izabrani dobavljaci, 1 - porucena roba, 3 - zatvorena porudzbenica, 4 - nekompletirana porudzbenica - obradjen zapisnik',
  `fileID` int(11) NULL DEFAULT NULL,
  `napomena` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL,
  `licnoPreuzimanje` tinyint(1) NULL DEFAULT NULL,
  `datumIsporuke` datetime(0) NULL DEFAULT NULL,
  `mestoIsporuke` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `vozac` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `regVozila` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `addressID` int(11) NULL DEFAULT NULL,
  `ispostavaID` int(11) NULL DEFAULT NULL,
  `statusPosiljke` enum('In progress','Failed','Received','Downloaded','Unknown','Rejected','Accepted','Attachment','ByHand','ForApproving','Opened','PartReceived','PartSigned','Signed') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL,
  `mailmanID` int(11) NULL DEFAULT NULL,
  `isporuceno` tinyint(4) NULL DEFAULT 0 COMMENT '0 - nije poslato, 1 - poslato',
  `pocetnoStanje` int(11) NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci ROW_FORMAT = DYNAMIC;

