-- ----------------------------
-- Table structure for sa_document_excange
-- ----------------------------
DROP TABLE IF EXISTS `sa_document_excange`;
CREATE TABLE `sa_document_excange`  (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `OM_ID` int(11) NOT NULL,
  `UniqueDocumentHash` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `CreatedAt` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0),
  `SendAt` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0),
  `SendBySubjectID` int(11) NOT NULL,
  `SendByEmployeeID` int(11) NULL DEFAULT NULL,
  `SendByEmployee` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `SendByEmployeeEmail` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `SendToSubectID` int(11) NOT NULL,
  `SendToLicenseCompanyID` int(11) NULL DEFAULT NULL,
  `SendToSubjectContact` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `SendToEmail` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `DocumentName` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `DocumentType` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `DocumentPath` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `Message` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `Status` enum('In progress','Failed','Received','Downloaded','Unknown','Rejected','Accepted','Attachment','ByHand','Opened','DontSend') CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'In progress',
  `StatusMailman` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `LastStatusMessage` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT 'Koristi se za poruke sa mail servera! Kod statusa Failed!',
  `LastSefStatusMessage` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `LastSefComment` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `LastCrfStatusMessage` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `EmailMessageID` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `EmailServerID` varchar(245) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `Disable` tinyint(1) NULL DEFAULT 0,
  `LicenseDocumentID` int(11) NULL DEFAULT NULL,
  `AutoSendDocument` timestamp(0) NULL DEFAULT NULL,
  `SendToSubjectName` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `SendToSubjectEmail` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `InvoiceNumber` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `InternalInvoiceNumber` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `InvoiceTotal` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `InvoiceIssueDate` timestamp(0) NULL DEFAULT NULL,
  `InvoiceDate` timestamp(0) NULL DEFAULT NULL,
  `InvoiceStatus` enum('Active','Started','Settled','Asigniran') CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `popust` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `suma` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `valuta` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `pdv` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `int_note` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `Language` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT 'rs',
  `EmailSubject` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `fromUniqueLink` int(1) NULL DEFAULT 0,
  `status_odobrenja` int(11) NULL DEFAULT NULL,
  `DisabledDownload` int(11) NULL DEFAULT 0,
  `storno` tinyint(1) NULL DEFAULT 0 COMMENT '0 - validna, 1 - stornirana',
  `tipRacuna` tinyint(1) NULL DEFAULT 0 COMMENT '0 - faktura, 1 - profaktura, 2 - avansi racun',
  `jbkjs` int(11) NULL DEFAULT NULL,
  `acceptRejectSef` tinyint(1) NULL DEFAULT 0 COMMENT '0 - bez statusa, 1 - odobrena, 2 - odbijena',
  `mistakeSef` tinyint(1) NULL DEFAULT 0,
  `stornoSef` tinyint(1) NULL DEFAULT 0 COMMENT '0 - validna, 1 - stornirana',
  `cancelSef` tinyint(1) NULL DEFAULT 0 COMMENT '0 - validna, 1 - otkazana',
  `reason` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `stornoReason` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `cancelReason` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `unread` tinyint(1) NULL DEFAULT 0 COMMENT '0 - neprocitan status, 1 - procitan status',
  `InvoiceStatusFilter` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `invoiceTagFilter` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `zaposleniOdobrioFakturuSEF` varchar(70) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `zaposleniUradioAkcijuID` int(11) NOT NULL DEFAULT 0,
  `trenutnaAkcija` int(11) NULL DEFAULT NULL COMMENT '1 - odobreno(kancelarko); 2-odbijeno(kancearko); 3 - uradjeno na drugoj licenci; 4 - akcija uradjena direktno na sefu; 5 - automatski odobreno; 6- automatski odbijeno',
  `action_date` timestamp(0) NULL DEFAULT NULL COMMENT 'datum promene sef akcije',
  `akcijaSaLicenceID` int(11) NULL DEFAULT NULL COMMENT 'ID licence sa koje je napravljena akcija',
  PRIMARY KEY (`ID`) USING BTREE,
  UNIQUE INDEX `UniqueDocumentHash_UNIQUE`(`UniqueDocumentHash`) USING BTREE,
  INDEX `excange_has_subject_idx`(`SendBySubjectID`) USING BTREE,
  INDEX `excange_has_subject_sendTo_idx`(`SendToSubectID`) USING BTREE,
  INDEX `sa_document_excange_OM_ID_idx`(`OM_ID`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of sa_document_excange
-- ----------------------------

