-- ----------------------------
DROP VIEW IF EXISTS `vw_lftrgt_structure`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `vw_lftrgt_structure` AS select `structure`.`lft` AS `lft` from `structure` union select `structure`.`rgt` AS `rgt` from `structure`;

