-- ----------------------------
-- Procedure structure for delovodnik
-- ----------------------------
DROP PROCEDURE IF EXISTS `delovodnik`;
delimiter ;;
CREATE PROCEDURE `delovodnik`(IN `ID` INT)
BEGIN

DECLARE LASTID INT(10);

CREATE TEMPORARY TABLE tmptable_1 SELECT * FROM delovodnik_item WHERE delovodnik_item.ID = ID;
UPDATE tmptable_1 SET ID = NULL;
SET LASTID =  LAST_INSERT_ID();
TRUNCATE tmptable_1;
DROP TEMPORARY TABLE tmptable_1;
SELECT LASTID AS nesto;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for f_folder_structure
-- ----------------------------
DROP PROCEDURE IF EXISTS `f_folder_structure`;
delimiter ;;
CREATE PROCEDURE `f_folder_structure`(IN `ptask_type` VARCHAR(10),
	IN `pID` INT,
	IN `pparent_id` INT,
	IN `emplID` INT,
	IN `folderID` INT,
    IN `sharedEmplID` INT)
BEGIN DECLARE new_lft, new_rgt, width, has_leafs, superior, superior_parent, old_lft, old_rgt, parent_rgt, subtree_size, lastCopyxID SMALLINT;

CASE ptask_type

	WHEN 'insert' THEN

	SELECT rgt INTO new_lft
	FROM f_folder_structure
	WHERE ID = pparent_id;

	UPDATE f_folder_structure 
	SET rgt = rgt + 2
	WHERE rgt >= new_lft AND empl_id = emplID;
		 
	UPDATE f_folder_structure 
	SET lft = lft + 2
	WHERE lft > new_lft AND empl_id = emplID;
		 
	VALUES (emplID, new_lft, (new_lft + 1), pparent_id, folderID);

	SELECT LAST_INSERT_ID() AS lastFID;
    
    
	WHEN 'insertid' THEN

	SELECT rgt INTO new_lft
	FROM f_folder_structure
	WHERE ID = pparent_id;

	UPDATE f_folder_structure 
	SET rgt = rgt + 2
	WHERE rgt >= new_lft AND empl_id = emplID;
		 
	UPDATE f_folder_structure 
	SET lft = lft + 2
	WHERE lft > new_lft AND empl_id = emplID;
		 
	VALUES (pID, emplID, new_lft, (new_lft + 1), pparent_id, folderID);

	SELECT LAST_INSERT_ID() AS lastFID;
    
    WHEN 'xcopy' THEN
    
    IF (pID != pparent_id) THEN
		
        CREATE TEMPORARY TABLE IF NOT EXISTS f_folder_xcopy (
        `ID` SMALLINT(5) UNSIGNED NOT NULL AUTO_INCREMENT,
		`empl_id` SMALLINT(5) UNSIGNED DEFAULT NULL,
        `f_folderID` SMALLINT(5) UNSIGNED DEFAULT NULL,
		`lft` SMALLINT(5) UNSIGNED DEFAULT NULL,
		`rgt` SMALLINT(5) UNSIGNED DEFAULT NULL,
		`parent_id` SMALLINT(5) UNSIGNED NOT NULL,
		PRIMARY KEY (`ID`)
        );
        
        SELECT 	emplID,
                t1.f_folderID,
				(t1.lft - (SELECT MIN(lft) FROM f_folder_structure WHERE ID = pID)) AS lft,
				(t1.rgt - (SELECT MIN(lft) FROM f_folder_structure WHERE ID = pID)) AS rgt,
                t1.parent_id
		FROM f_folder_structure AS t1, f_folder_structure AS t2
		WHERE t1.lft BETWEEN t2.lft AND t2.rgt AND t2.ID = pID AND (t1.empl_id = emplID AND t2.empl_id = emplID);
        
        SELECT rgt INTO parent_rgt FROM f_folder_structure WHERE ID = pparent_id;
        
        SET subtree_size = (SELECT (MAX(rgt) + 1) FROM f_folder_xcopy);
        
        UPDATE f_folder_structure
			SET lft = (CASE WHEN lft > parent_rgt THEN lft + subtree_size ELSE lft END),
				rgt = (CASE WHEN rgt >= parent_rgt THEN rgt + subtree_size ELSE rgt END)
        WHERE rgt >= parent_rgt AND empl_id = sharedEmplID; 
        
		SELECT sharedEmplID, f_folderID, lft + parent_rgt, rgt + parent_rgt, parent_id
		FROM f_folder_xcopy;
               
        SET lastCopyxID = LAST_INSERT_ID();
        
        UPDATE f_folder_structure
           SET lft = (SELECT COUNT(*) FROM vw_f_folder_s AS v WHERE v.lft <= f_folder_structure.lft AND v.empl_id = sharedEmplID),
               rgt = (SELECT COUNT(*) FROM vw_f_folder_s AS v WHERE v.lft <= f_folder_structure.rgt AND v.empl_id = sharedEmplID);
               
		DELETE FROM f_folder_xcopy;
        
        UPDATE f_folder_structure SET parent_id = pparent_id WHERE ID = lastCopyxID;
        
	END IF;
    

	WHEN 'delete' THEN
    
	SELECT lft, rgt, (rgt - lft), (rgt - lft + 1), parent_id
    INTO new_lft, new_rgt, has_leafs, width, superior_parent
	FROM f_folder_structure	WHERE ID = pID AND empl_id = emplID;
	
	DELETE FROM f_folder_structure 
	WHERE ID = pID AND empl_id = emplID; 
	 
	IF (has_leafs = 1) THEN
	 
		DELETE FROM f_folder_structure
		WHERE lft BETWEEN new_lft AND new_rgt AND empl_id = emplID;
		
		UPDATE f_folder_structure 
		SET rgt = rgt - width
		WHERE rgt > new_rgt AND empl_id = emplID;
			 
		UPDATE f_folder_structure 
		SET lft = lft - width
		WHERE lft > new_rgt AND empl_id = emplID;
    
    ELSE
    
		DELETE FROM f_folder_structure
		WHERE lft = new_lft AND empl_id = emplID;

		UPDATE f_folder_structure 
		SET rgt = rgt - 1,
			lft = lft - 1,
			parent_id = superior_parent
		WHERE lft BETWEEN new_lft AND new_rgt AND empl_id = emplID;
		
		UPDATE f_folder_structure 
		SET	rgt = rgt - 2
		WHERE rgt > new_rgt AND empl_id = emplID;	 
		 
		UPDATE f_folder_structure 
		SET lft = lft - 2
		WHERE lft > new_rgt AND empl_id = emplID;
	 
	END IF;
    
	 
	 WHEN 'move' THEN
	 
	 IF (pID != pparent_id) THEN
     
			CREATE TEMPORARY TABLE IF NOT EXISTS f_folder_move_edit (
			`ID` SMALLINT(5) UNSIGNED NOT NULL AUTO_INCREMENT,
			`empl_id` SMALLINT(5) UNSIGNED DEFAULT NULL,
			`lft` SMALLINT(5) UNSIGNED DEFAULT NULL,
			`rgt` SMALLINT(5) UNSIGNED DEFAULT NULL,
			`parent_id` SMALLINT(5) UNSIGNED NOT NULL,
			PRIMARY KEY (`ID`));

		SELECT 	t1.ID,
				t1.empl_id,
				(t1.lft - (SELECT MIN(lft) FROM folder WHERE ID = pID)) AS lft,
				(t1.rgt - (SELECT MIN(lft) FROM folder WHERE ID = pID)) AS rgt,
				t1.parent_id
		FROM f_folder_structure AS t1,
		f_folder_structure AS t2
		WHERE t1.lft BETWEEN t2.lft AND t2.rgt AND t2.empl_id = emplID AND t2.ID = pID;

		DELETE FROM f_folder_structure 
		WHERE ID IN (SELECT ID FROM	f_folder_move_edit);
		
		SELECT rgt
		INTO parent_rgt FROM f_folder_structure
		WHERE ID = pparent_id;
		 
		SET subtree_size = (SELECT (MAX(rgt) + 1) FROM f_folder_move_edit);

		UPDATE f_folder_structure 
		SET 
			lft = (CASE WHEN lft > parent_rgt THEN lft + subtree_size ELSE lft END),
			rgt = (CASE WHEN rgt >= parent_rgt THEN rgt + subtree_size ELSE rgt END)
		WHERE rgt >= parent_rgt;	 
		 
		SELECT ID, empl_id, lft + parent_rgt, rgt + parent_rgt, parent_id
		FROM f_folder_move_edit;

		UPDATE f_folder_structure 
		SET lft = (SELECT COUNT(*) FROM vw_lftrgt AS v
				WHERE v.lft <= f_folder_structure.lft AND f_folder_structure.empl_id = emplID),
			rgt = (SELECT COUNT(*) FROM vw_lftrgt AS v
				WHERE v.lft <= f_folder_structure.rgt AND f_folder_structure.empl_id = emplID);
				
		DELETE FROM f_folder_move_edit;
		
		UPDATE f_folder_structure 
		SET parent_id = pparent_id
		WHERE ID = pID;
	 
	END IF;
 
 END CASE;
 
 END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for f_folder_sub_id
-- ----------------------------
DROP PROCEDURE IF EXISTS `f_folder_sub_id`;
delimiter ;;
CREATE PROCEDURE `f_folder_sub_id`(IN `pnode_id` INT,
	IN `emplID` INT)
BEGIN

SELECT node.ID, 
		 (COUNT(parent.ID) - (sub_tree.depth + 1)) AS depth,
         node.parent_id,
         node.empl_id,
         node.f_folderID,
         (SELECT f_folder.sharingPermission FROM f_folder WHERE f_folder.ID = node.f_folderID) as sp,
         (SELECT f_folder.ownerID FROM f_folder WHERE f_folder.ID = node.f_folderID) as ownerID,
                  (SELECT f_folder.ownerID FROM f_folder WHERE f_folder.ID = node.f_folderID) as ownerID,
         (SELECT f_folder.folderName FROM f_folder WHERE f_folder.ID = node.f_folderID) as folderName,
         (SELECT f_folder.folder_img FROM f_folder WHERE f_folder.ID = node.f_folderID) as folder_img,
         (SELECT DATE_FORMAT(f_folder.createTime, "%d.%m.%Y")  FROM f_folder WHERE f_folder.ID = node.f_folderID) as createTime,
         (SELECT f_folder.createTime  FROM f_folder WHERE f_folder.ID = node.f_folderID) as createDate,
         (SELECT f_folder.folderDescription FROM f_folder WHERE f_folder.ID = node.f_folderID) as folderDescription,
         (SELECT f_folder.google_f_id FROM f_folder WHERE f_folder.ID = node.f_folderID) as google_f_id
    FROM f_folder_structure AS node,
         f_folder_structure AS parent,
         f_folder_structure AS sub_parent,
  (SELECT node.ID, (COUNT(parent.ID) - 1) AS depth, node.empl_id
    FROM f_folder_structure AS node,
		     f_folder_structure AS parent
	 WHERE node.lft BETWEEN parent.lft AND parent.rgt
		 AND node.ID = pnode_id AND node.empl_id = emplID AND parent.empl_id = emplID
	 GROUP BY node.ID
	 ORDER BY node.lft) AS sub_tree
   WHERE node.lft BETWEEN parent.lft AND parent.rgt
	   AND node.lft BETWEEN sub_parent.lft AND sub_parent.rgt
	   AND sub_parent.ID = sub_tree.ID AND node.empl_id = emplID AND sub_parent.empl_id = emplID AND sub_tree.empl_id = emplID
       AND parent.empl_id = emplID
   GROUP BY node.ID
   ORDER BY node.lft;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for f_folder_temp_sub_tree
-- ----------------------------
DROP PROCEDURE IF EXISTS `f_folder_temp_sub_tree`;
delimiter ;;
CREATE PROCEDURE `f_folder_temp_sub_tree`(IN `pnode_id` INT, IN `emplID` INT)
BEGIN

  SELECT node.ID, 
		 (COUNT(parent.ID) - (sub_tree.depth + 1)) AS depth,
         node.folderName,
         node.ID AS f_folderID, 
         DATE_FORMAT(node.createTime, "%d.%m.%Y") AS createTime,
         node.ownerID,
         node.folder_img,
         node.`type`, 
         node.parent_id,
         node.folderDescription
    FROM folder AS node,
         folder AS parent,
         folder AS sub_parent,
  (SELECT node.ID, (COUNT(parent.ID) - 1) AS depth
    FROM folder AS node,
		     folder AS parent
	 WHERE node.lft BETWEEN parent.lft AND parent.rgt
		 AND node.ID = pnode_id
	 GROUP BY node.ID
	 ORDER BY node.lft) AS sub_tree
   WHERE node.lft BETWEEN parent.lft AND parent.rgt
	   AND node.lft BETWEEN sub_parent.lft AND sub_parent.rgt
	   AND sub_parent.ID = sub_tree.ID
   GROUP BY node.ID
   ORDER BY node.lft;

END
;;
delimiter ;

-- ----------------------------
-- Function structure for getEmployeeIDByObjectID
-- ----------------------------
DROP FUNCTION IF EXISTS `getEmployeeIDByObjectID`;
delimiter ;;
CREATE FUNCTION `getEmployeeIDByObjectID`(objectIDParam INT, empIDParam INT)
 RETURNS int(11)
BEGIN
    DECLARE resultID INT;

    SELECT employee.ID
    INTO resultID
    FROM (
        SELECT node.id, (COUNT(parent.id) - (sub_tree.depth + 1)) AS depth, node.objectID
        FROM structure AS node,
            structure AS parent,
            structure AS sub_parent,
            (SELECT node.id, (COUNT(parent.id) - 1) AS depth
                FROM structure AS node,
                    structure AS parent
                WHERE node.lft BETWEEN parent.lft AND parent.rgt
                    AND (node.objectID = objectIDParam)  
                GROUP BY node.id
                ORDER BY node.lft
            ) AS sub_tree
        WHERE node.lft BETWEEN parent.lft AND parent.rgt
            AND node.lft BETWEEN sub_parent.lft AND sub_parent.rgt
            AND sub_parent.id = sub_tree.id
        GROUP BY node.id
        ORDER BY node.lft
    ) AS t1 
    LEFT JOIN structure_object ON (t1.objectID = structure_object.ID)
    LEFT JOIN structure_object_has_employee ON (structure_object.ID = structure_object_has_employee.objectID)
    LEFT JOIN employee ON (structure_object_has_employee.employeeID = employee.ID)
    WHERE employee.archived = 0 AND employee.ID = empIDParam;

    RETURN resultID;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for r_tree_traversal
-- ----------------------------
DROP PROCEDURE IF EXISTS `r_tree_traversal`;
delimiter ;;
CREATE PROCEDURE `r_tree_traversal`(IN ptask_type VARCHAR(10),
  IN pID INT,
  IN pparent_id INT)
BEGIN


  DECLARE new_lft, new_rgt, width, has_leafs, superior, superior_parent, old_lft, old_rgt, parent_rgt, subtree_size SMALLINT;

  CASE ptask_type

    WHEN 'insert' THEN

        SELECT rgt INTO new_lft FROM folder WHERE ID = pparent_id;
        UPDATE folder SET rgt = rgt + 2 WHERE rgt >= new_lft;
        UPDATE folder SET lft = lft + 2 WHERE lft > new_lft;
		SELECT LAST_INSERT_ID();

    WHEN 'delete' THEN

        SELECT lft, rgt, (rgt - lft), (rgt - lft + 1), parent_id 
		  INTO new_lft, new_rgt, has_leafs, width, superior_parent 
		  FROM folder WHERE ID = pID;

		DELETE FROM folder WHERE ID = pID;

        IF (has_leafs = 1) THEN
          DELETE FROM folder WHERE lft BETWEEN new_lft AND new_rgt;
          UPDATE folder SET rgt = rgt - width WHERE rgt > new_rgt;
          UPDATE folder SET lft = lft - width WHERE lft > new_rgt;
        ELSE
          DELETE FROM folder WHERE lft = new_lft;
          UPDATE folder SET rgt = rgt - 1, lft = lft - 1, parent_id = superior_parent 
		   WHERE lft BETWEEN new_lft AND new_rgt;
          UPDATE folder SET rgt = rgt - 2 WHERE rgt > new_rgt;
          UPDATE folder SET lft = lft - 2 WHERE lft > new_rgt;
        END IF;

    WHEN 'move' THEN
    
		IF (pID != pparent_id) THEN
        CREATE TEMPORARY TABLE IF NOT EXISTS working_folder
        (
          `ID` smallint(5) unsigned NOT NULL AUTO_INCREMENT,
          `folderName` varchar(245) DEFAULT NULL,
          `folderDescription` text,
          `lft` smallint(5) unsigned DEFAULT NULL,
          `rgt` smallint(5) unsigned DEFAULT NULL,
          `parent_id` smallint(5) unsigned NOT NULL,
          `createTime` datetime NOT NULL,
          `creatorID` smallint(5) unsigned NOT NULL,
          `ownerID` smallint(5) unsigned,
          `folder_img` varchar(45) DEFAULT NULL,
          `type` enum('DEFAULT', 'TEMPLATE', 'PERSONAL') DEFAULT NULL,
          PRIMARY KEY (`ID`)
        );
        
		
			 SELECT t1.ID, 
					t1.folderName,
                    t1.folderDescription,
					(t1.lft - (SELECT MIN(lft) FROM folder WHERE ID = pID)) AS lft,
					(t1.rgt - (SELECT MIN(lft) FROM folder WHERE ID = pID)) AS rgt,
					t1.parent_id,
                    t1.createTime,
                    t1.creatorID,
                    t1.ownerID,
                    t1.folder_img,
                    t1.`type`
			   FROM folder AS t1, folder AS t2
			  WHERE t1.lft BETWEEN t2.lft AND t2.rgt 
				AND t2.ID = pID;

        DELETE FROM folder WHERE ID IN (SELECT ID FROM working_folder);

        SELECT rgt INTO parent_rgt FROM folder WHERE ID = pparent_id;
        SET subtree_size = (SELECT (MAX(rgt) + 1) FROM working_folder);
		
		
        UPDATE folder
          SET lft = (CASE WHEN lft > parent_rgt THEN lft + subtree_size ELSE lft END),
              rgt = (CASE WHEN rgt >= parent_rgt THEN rgt + subtree_size ELSE rgt END)
        WHERE rgt >= parent_rgt;

             SELECT ID, folderName, folderDescription, lft + parent_rgt, rgt + parent_rgt, parent_id, createTime, creatorID, ownerID, folder_img, `type`
               FROM working_folder;
        
		
        UPDATE folder
           SET lft = (SELECT COUNT(*) FROM vw_lftrgt AS v WHERE v.lft <= folder.lft),
               rgt = (SELECT COUNT(*) FROM vw_lftrgt AS v WHERE v.lft <= folder.rgt);
        
        DELETE FROM working_folder;
        UPDATE folder SET parent_id = pparent_id WHERE ID = pID;
		END IF;

    WHEN 'order' THEN

        SELECT lft, rgt, (rgt - lft + 1), parent_id INTO old_lft, old_rgt, width, superior
          FROM folder WHERE ID = pID;

        
        SELECT parent_id INTO superior_parent FROM folder WHERE ID = pparent_id;

        IF (superior = superior_parent) THEN
          SELECT (rgt + 1) INTO new_lft FROM folder WHERE ID = pparent_id;
        ELSE
          SELECT (lft + 1) INTO new_lft FROM folder WHERE ID = pparent_id;
        END IF;

	    IF (new_lft != old_lft) THEN
		  CREATE TEMPORARY TABLE IF NOT EXISTS working_folder
        (
          `ID` smallint(5) unsigned NOT NULL AUTO_INCREMENT,
          `lft` smallint(5) unsigned DEFAULT NULL,
          `rgt` smallint(5) unsigned DEFAULT NULL,
          `parent_id` smallint(5) unsigned NOT NULL,
          PRIMARY KEY (`ID`)
        );

            SELECT t1.ID,
			  	   (t1.lft - (SELECT MIN(lft) FROM folder WHERE ID = pID)) AS lft,
				   (t1.rgt - (SELECT MIN(lft) FROM folder WHERE ID = pID)) AS rgt,
				   t1.parent_id
			  FROM folder AS t1, folder AS t2
			 WHERE t1.lft BETWEEN t2.lft AND t2.rgt AND t2.ID = pID;
            
       DELETE FROM folder WHERE ID IN (SELECT ID FROM working_folder);

       IF(new_lft < old_lft) THEN 
          UPDATE folder SET lft = lft + width WHERE lft >= new_lft AND lft < old_lft;
          UPDATE folder SET rgt = rgt + width WHERE rgt > new_lft AND rgt < old_rgt;
          UPDATE working_folder SET lft = new_lft + lft, rgt = new_lft + rgt;
       END IF;

       IF(new_lft > old_lft) THEN 
            UPDATE folder SET lft = lft - width WHERE lft > old_lft AND lft < new_lft;
            UPDATE folder SET rgt = rgt - width WHERE rgt > old_rgt AND rgt < new_lft;
            UPDATE working_folder SET lft = (new_lft - width) + lft, rgt = (new_lft - width) + rgt;
       END IF;

            SELECT ID, lft, rgt, parent_id
              FROM working_folder;
            
       DELETE FROM working_folder;
	   END IF;
  END CASE;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for selectwp
-- ----------------------------
DROP PROCEDURE IF EXISTS `selectwp`;
delimiter ;;
CREATE PROCEDURE `selectwp`()
BEGIN

SELECT t1.* FROM
(
SELECT structure_object.ID, structure_object.objectName AS name,
(SELECT 
GROUP_CONCAT((SELECT structure_object.objectName FROM structure_object WHERE structure_object.ID = parent.objectID) SEPARATOR '\\') AS parentList
FROM structure AS node,
structure AS parent
WHERE node.lft BETWEEN parent.lft AND parent.rgt
AND node.id = structure.ID
ORDER BY parent.lft) AS Kompanije,

GROUP_CONCAT((SELECT GROUP_CONCAT(CONCAT(employee.id, '#', employee.firstname, ' ', employee.lastname) SEPARATOR ', ') as emplName FROM employee
LEFT JOIN structure_object_has_employee ON (employee.ID = structure_object_has_employee.employeeID)
WHERE structure_object_has_employee.objectID = structure_object.ID)) as employees

FROM structure
LEFT JOIN structure_object ON (structure.objectID = structure_object.ID)
WHERE structure_object.objectType = 'WORKPLACE'
group by structure.id ) as t1
where t1.employees IS NOT NULL;


END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for selectwpforempl
-- ----------------------------
DROP PROCEDURE IF EXISTS `selectwpforempl`;
delimiter ;;
CREATE PROCEDURE `selectwpforempl`(IN employeeS VARCHAR(245))
BEGIN

SELECT t1.* FROM
(
SELECT structure_object.ID, structure_object.objectName AS name,
(SELECT 
GROUP_CONCAT((SELECT structure_object.objectName FROM structure_object WHERE structure_object.ID = parent.objectID) SEPARATOR '\\') AS parentList
FROM structure AS node,
structure AS parent
WHERE node.lft BETWEEN parent.lft AND parent.rgt
AND node.id = structure.ID
ORDER BY parent.lft) AS Kompanije,

GROUP_CONCAT((SELECT GROUP_CONCAT(CONCAT(employee.id, '#', employee.firstname, ' ', employee.lastname) SEPARATOR ', ') as emplName FROM employee
LEFT JOIN structure_object_has_employee ON (employee.ID = structure_object_has_employee.employeeID)
WHERE structure_object_has_employee.objectID = structure_object.ID)) as employees

FROM structure
LEFT JOIN structure_object ON (structure.objectID = structure_object.ID)
WHERE structure_object.objectType = 'WORKPLACE'
group by structure.id ) as t1
where t1.employees IS NOT NULL AND t1.employees LIKE CONCAT('%', employeeS , '%');
  

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for structure_move
-- ----------------------------
DROP PROCEDURE IF EXISTS `structure_move`;
delimiter ;;
CREATE PROCEDURE `structure_move`(IN `ptask_type` VARCHAR(10), IN `pID` INT, IN `pparent_id` INT)
BEGIN


  DECLARE new_lft, new_rgt, width, has_leafs, superior, superior_parent, old_lft, old_rgt, parent_rgt, subtree_size SMALLINT;

  CASE ptask_type

    

    WHEN 'move' THEN
    
		IF (pID != pparent_id) THEN
        CREATE TEMPORARY TABLE IF NOT EXISTS working_structure_move
        (
          `ID` smallint(5) unsigned NOT NULL AUTO_INCREMENT,
          `objectID` varchar(245) DEFAULT NULL,
          `lft` smallint(5) unsigned DEFAULT NULL,
          `rgt` smallint(5) unsigned DEFAULT NULL,
          `parent_id` smallint(5) unsigned NOT NULL,
          `archived` smallint(5) unsigned NOT NULL,
          `sortWeight` int(11) unsigned NOT NULL,
          PRIMARY KEY (`ID`)
        );
        
		
			 SELECT t1.ID, 
					t1.objectID,
					(t1.lft - (SELECT MIN(lft) FROM folder WHERE ID = pID)) AS lft,
					(t1.rgt - (SELECT MIN(lft) FROM folder WHERE ID = pID)) AS rgt,
					t1.parent_id,
                    t1.archived,
                    t1.sortWeight
			   FROM structure AS t1, structure AS t2
			  WHERE t1.lft BETWEEN t2.lft AND t2.rgt 
				AND t2.ID = pID;

        DELETE FROM structure WHERE ID IN (SELECT ID FROM working_structure_move);

        SELECT rgt INTO parent_rgt FROM structure WHERE ID = pparent_id;
        SET subtree_size = (SELECT (MAX(rgt) + 1) FROM working_structure_move);
		
		
        UPDATE structure
          SET lft = (CASE WHEN lft > parent_rgt THEN lft + subtree_size ELSE lft END),
              rgt = (CASE WHEN rgt >= parent_rgt THEN rgt + subtree_size ELSE rgt END)
        WHERE rgt >= parent_rgt;

             SELECT ID, objectID, lft + parent_rgt, rgt + parent_rgt, parent_id, archived, sortWeight
               FROM working_structure_move;
        
		
        UPDATE structure
           SET lft = (SELECT COUNT(*) FROM vw_lftrgt_structure AS v WHERE v.lft <= structure.lft),
               rgt = (SELECT COUNT(*) FROM vw_lftrgt_structure AS v WHERE v.lft <= structure.rgt);
        
        DELETE FROM working_structure_move;
        UPDATE structure SET parent_id = pparent_id WHERE ID = pID;
		END IF;

    
  END CASE;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for structure_tasks
-- ----------------------------
DROP PROCEDURE IF EXISTS `structure_tasks`;
delimiter ;;
CREATE PROCEDURE `structure_tasks`(IN `ptask_type` VARCHAR(10), IN `pID` INT, IN `pparent_id` INT, IN `object_ID` INT)
BEGIN


  DECLARE new_lft, new_rgt, width, has_leafs, superior, superior_parent, old_lft, old_rgt, parent_rgt, subtree_size SMALLINT;

  CASE ptask_type

    WHEN 'insert' THEN

        SELECT rgt INTO new_lft FROM structure WHERE ID = pparent_id;
        UPDATE structure SET rgt = rgt + 2 WHERE rgt >= new_lft;
        UPDATE structure SET lft = lft + 2 WHERE lft > new_lft;
		SELECT LAST_INSERT_ID() as lastInsertID;

    WHEN 'delete' THEN

        SELECT lft, rgt, (rgt - lft), (rgt - lft + 1), parent_id 
		  INTO new_lft, new_rgt, has_leafs, width, superior_parent 
		  FROM structure WHERE ID = pID;

		DELETE FROM structure WHERE ID = pID;

        IF (has_leafs = 1) THEN
          DELETE FROM structure WHERE lft BETWEEN new_lft AND new_rgt;
          UPDATE structure SET rgt = rgt - width WHERE rgt > new_rgt;
          UPDATE structure SET lft = lft - width WHERE lft > new_rgt;
        ELSE
          DELETE FROM structure WHERE lft = new_lft;
          UPDATE structure SET rgt = rgt - 1, lft = lft - 1, parent_id = superior_parent 
		   WHERE lft BETWEEN new_lft AND new_rgt;
          UPDATE structure SET rgt = rgt - 2 WHERE rgt > new_rgt;
          UPDATE structure SET lft = lft - 2 WHERE lft > new_rgt;
        END IF;

    WHEN 'move' THEN
    
		IF (pID != pparent_id) THEN
        CREATE TEMPORARY TABLE IF NOT EXISTS working_structure
        (
          `ID` smallint(5) unsigned NOT NULL AUTO_INCREMENT,
          `objectID` varchar(245) DEFAULT NULL,
          `lft` smallint(5) unsigned DEFAULT NULL,
          `rgt` smallint(5) unsigned DEFAULT NULL,
          `parent_id` smallint(5) unsigned NOT NULL,
          `archived` smallint(5) unsigned NOT NULL,
          `sortWeight` int(11) unsigned NOT NULL,
          PRIMARY KEY (`ID`)
        );
        
		
			 SELECT t1.ID, 
					t1.objectID,
					(t1.lft - (SELECT MIN(lft) FROM structure WHERE ID = pID)) AS lft,
					(t1.rgt - (SELECT MIN(lft) FROM structure WHERE ID = pID)) AS rgt,
					t1.parent_id,
                    t1.archived,
                    t1.sortWeight
			   FROM structure AS t1, structure AS t2
			  WHERE t1.lft BETWEEN t2.lft AND t2.rgt 
				AND t2.ID = pID;

        DELETE FROM structure WHERE ID IN (SELECT ID FROM working_structure);

        SELECT rgt INTO parent_rgt FROM structure WHERE ID = pparent_id;
        SET subtree_size = (SELECT (MAX(rgt) + 1) FROM working_structure);
		
		
        UPDATE structure
          SET lft = (CASE WHEN lft > parent_rgt THEN lft + subtree_size ELSE lft END),
              rgt = (CASE WHEN rgt >= parent_rgt THEN rgt + subtree_size ELSE rgt END)
        WHERE rgt >= parent_rgt;

             SELECT ID, objectID, lft + parent_rgt, rgt + parent_rgt, parent_id, archived, sortWeight
               FROM working_structure;
        
		
        UPDATE structure
           SET lft = (SELECT COUNT(*) FROM vw_lftrgt_structure AS v WHERE v.lft <= structure.lft),
               rgt = (SELECT COUNT(*) FROM vw_lftrgt_structure AS v WHERE v.lft <= structure.rgt);
        
        DELETE FROM working_structure;
        UPDATE structure SET parent_id = pparent_id WHERE ID = pID;
		END IF;

    WHEN 'order' THEN

        SELECT lft, rgt, (rgt - lft + 1), parent_id INTO old_lft, old_rgt, width, superior
          FROM structure WHERE ID = pID;

        
        SELECT parent_id INTO superior_parent FROM structure WHERE ID = pparent_id;

        IF (superior = superior_parent) THEN
          SELECT (rgt + 1) INTO new_lft FROM structure WHERE ID = pparent_id;
        ELSE
          SELECT (lft + 1) INTO new_lft FROM structure WHERE ID = pparent_id;
        END IF;

	    IF (new_lft != old_lft) THEN
		  CREATE TEMPORARY TABLE IF NOT EXISTS working_structure
        (
          `ID` smallint(5) unsigned NOT NULL AUTO_INCREMENT,
          `objectID` varchar(245) DEFAULT NULL,
          `lft` smallint(5) unsigned DEFAULT NULL,
          `rgt` smallint(5) unsigned DEFAULT NULL,
          `parent_id` smallint(5) unsigned NOT NULL,
          PRIMARY KEY (`ID`)
        );

            SELECT t1.ID,
					t1.objectID,
			  	   (t1.lft - (SELECT MIN(lft) FROM struktura WHERE ID = pID)) AS lft,
				   (t1.rgt - (SELECT MIN(lft) FROM struktura WHERE ID = pID)) AS rgt,
				   t1.parent_id
			  FROM structure AS t1, structure AS t2
			 WHERE t1.lft BETWEEN t2.lft AND t2.rgt AND t2.ID = pID;
            
       DELETE FROM structure WHERE ID IN (SELECT ID FROM working_structure);

       IF(new_lft < old_lft) THEN 
          UPDATE structure SET lft = lft + width WHERE lft >= new_lft AND lft < old_lft;
          UPDATE structure SET rgt = rgt + width WHERE rgt > new_lft AND rgt < old_rgt;
          UPDATE working_structure SET lft = new_lft + lft, rgt = new_lft + rgt;
       END IF;

       IF(new_lft > old_lft) THEN 
            UPDATE structure SET lft = lft - width WHERE lft > old_lft AND lft < new_lft;
            UPDATE structure SET rgt = rgt - width WHERE rgt > old_rgt AND rgt < new_lft;
            UPDATE working_structure SET lft = (new_lft - width) + lft, rgt = (new_lft - width) + rgt;
       END IF;

            SELECT ID, objectID, lft, rgt, parent_id
              FROM working_structure;
            
       DELETE FROM working_structure;
	   END IF;
  END CASE;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for where_is_structure
-- ----------------------------
DROP PROCEDURE IF EXISTS `where_is_structure`;
delimiter ;;
CREATE PROCEDURE `where_is_structure`(IN `ptask_type` VARCHAR(10), IN `pID` INT, IN `pparent_id` INT, IN `where_is_name` VARCHAR(245) CHARSET utf8)
BEGIN


   DECLARE new_lft, new_rgt, width, has_leafs, superior, superior_parent, old_lft, old_rgt, parent_rgt, subtree_size SMALLINT;

   CASE ptask_type

     WHEN 'insert' THEN

         SELECT rgt INTO new_lft FROM where_is_structure WHERE ID = pparent_id;
         UPDATE where_is_structure SET rgt = rgt + 2 WHERE rgt >= new_lft;
         UPDATE where_is_structure SET lft = lft + 2 WHERE lft > new_lft;
         SELECT LAST_INSERT_ID() as lastInsertID;

     WHEN 'delete' THEN

         SELECT lft, rgt, (rgt - lft), (rgt - lft + 1), parent_id
           INTO new_lft, new_rgt, has_leafs, width, superior_parent
           FROM where_is_structure WHERE ID = pID;

         DELETE FROM where_is_structure WHERE ID = pID;

         IF (has_leafs = 1) THEN
           DELETE FROM where_is_structure WHERE lft BETWEEN new_lft AND new_rgt;
           UPDATE where_is_structure SET rgt = rgt - width WHERE rgt > new_rgt;
           UPDATE where_is_structure SET lft = lft - width WHERE lft > new_rgt;
         ELSE
           DELETE FROM where_is_structure WHERE lft = new_lft;
           UPDATE where_is_structure SET rgt = rgt - 1, lft = lft - 1, parent_id = superior_parent
            WHERE lft BETWEEN new_lft AND new_rgt;
           UPDATE where_is_structure SET rgt = rgt - 2 WHERE rgt > new_rgt;
           UPDATE where_is_structure SET lft = lft - 2 WHERE lft > new_rgt;
         END IF;

     WHEN 'move' THEN

         IF (pID != pparent_id) THEN
         CREATE TEMPORARY TABLE IF NOT EXISTS working_where_is_structure
         (
           `ID` smallint(5) unsigned NOT NULL AUTO_INCREMENT,
           `whereName` varchar(245) DEFAULT NULL,
           `lft` smallint(5) unsigned DEFAULT NULL,
           `rgt` smallint(5) unsigned DEFAULT NULL,
           `parent_id` smallint(5) unsigned NOT NULL,
           PRIMARY KEY (`ID`)
         );


              SELECT t1.ID,
                     t1.whereName,
                     (t1.lft - (SELECT MIN(lft) FROM where_is_structure WHERE ID = pID)) AS lft,
                     (t1.rgt - (SELECT MIN(lft) FROM where_is_structure WHERE ID = pID)) AS rgt,
                     t1.parent_id
                FROM where_is_structure AS t1, where_is_structure AS t2
               WHERE t1.lft BETWEEN t2.lft AND t2.rgt
                 AND t2.ID = pID;

         DELETE FROM where_is_structure WHERE ID IN (SELECT ID FROM working_where_is_structure);

         SELECT rgt INTO parent_rgt FROM where_is_structure WHERE ID = pparent_id;
         SET subtree_size = (SELECT (MAX(rgt) + 1) FROM working_where_is_structure);


         UPDATE where_is_structure
           SET lft = (CASE WHEN lft > parent_rgt THEN lft + subtree_size ELSE lft END),
               rgt = (CASE WHEN rgt >= parent_rgt THEN rgt + subtree_size ELSE rgt END)
         WHERE rgt >= parent_rgt;

              SELECT ID, whereName, lft + parent_rgt, rgt + parent_rgt, parent_id
                FROM working_where_is_structure;


         UPDATE where_is_structure
            SET lft = (SELECT COUNT(*)
  FROM vw_lftrgt_where_is_structure AS v WHERE v.lft <= 
where_is_structure.lft),
                rgt = (SELECT COUNT(*)
  FROM vw_lftrgt_where_is_structure AS v WHERE v.lft <= 
where_is_structure.rgt);

         DELETE FROM working_where_is_structure;
         UPDATE where_is_structure SET parent_id = pparent_id WHERE ID = 
pID;
         END IF;

     WHEN 'order' THEN

         SELECT lft, rgt, (rgt - lft + 1), parent_id INTO old_lft, 
old_rgt, width, superior
           FROM where_is_structure WHERE ID = pID;


         SELECT parent_id INTO superior_parent FROM where_is_structure 
WHERE ID = pparent_id;

         IF (superior = superior_parent) THEN
           SELECT (rgt + 1) INTO new_lft FROM where_is_structure WHERE 
ID = pparent_id;
         ELSE
           SELECT (lft + 1) INTO new_lft FROM where_is_structure WHERE 
ID = pparent_id;
         END IF;

         IF (new_lft != old_lft) THEN
           CREATE TEMPORARY TABLE IF NOT EXISTS working_where_is_structure
         (
           `ID` smallint(5) unsigned NOT NULL AUTO_INCREMENT,
           `lft` smallint(5) unsigned DEFAULT NULL,
           `rgt` smallint(5) unsigned DEFAULT NULL,
           `parent_id` smallint(5) unsigned NOT NULL,
           PRIMARY KEY (`ID`)
         );

             SELECT t1.ID,
                      (t1.lft - (SELECT MIN(lft) FROM where_is_structure 
WHERE ID = pID)) AS lft,
                    (t1.rgt - (SELECT MIN(lft) FROM where_is_structure 
WHERE ID = pID)) AS rgt,
                    t1.parent_id
               FROM where_is_structure AS t1, where_is_structure AS t2
              WHERE t1.lft BETWEEN t2.lft AND t2.rgt AND t2.ID = pID;

        DELETE FROM where_is_structure WHERE ID IN (SELECT ID FROM 
working_where_is_structure);

        IF(new_lft < old_lft) THEN
           UPDATE where_is_structure SET lft = lft + width WHERE lft >= 
new_lft AND lft < old_lft;
           UPDATE where_is_structure SET rgt = rgt + width WHERE rgt > 
new_lft AND rgt < old_rgt;
           UPDATE working_where_is_structure SET lft = new_lft + lft, 
rgt = new_lft + rgt;
        END IF;

        IF(new_lft > old_lft) THEN
             UPDATE where_is_structure SET lft = lft - width WHERE lft > 
old_lft AND lft < new_lft;
             UPDATE where_is_structure SET rgt = rgt - width WHERE rgt > 
old_rgt AND rgt < new_lft;
             UPDATE working_where_is_structure SET lft = (new_lft - 
width) + lft, rgt = (new_lft - width) + rgt;
        END IF;

             SELECT ID, lft, rgt, parent_id
               FROM working_where_is_structure;

        DELETE FROM working_where_is_structure;
        END IF;
   END CASE;

END
;;
