-- ----------------------------
-- Procedure structure for wp_hierarchy_tasks
-- ----------------------------
DROP PROCEDURE IF EXISTS `wp_hierarchy_tasks`;
delimiter ;;
CREATE PROCEDURE `wp_hierarchy_tasks`(IN ptask_type VARCHAR(10),
  IN pID INT,
  IN pparent_id INT,
  IN work_PlaceID INT)
BEGIN


  DECLARE new_lft, new_rgt, width, has_leafs, superior, superior_parent, old_lft, old_rgt, parent_rgt, subtree_size, lastCopyxID SMALLINT;

  CASE ptask_type

    WHEN 'insert' THEN

        SELECT rgt INTO new_lft FROM wp_hierarchy WHERE ID = pparent_id;
        UPDATE wp_hierarchy SET rgt = rgt + 2 WHERE rgt >= new_lft;
        UPDATE wp_hierarchy SET lft = lft + 2 WHERE lft > new_lft;
        SELECT LAST_INSERT_ID() AS lastID;
        

    WHEN 'delete' THEN

        SELECT lft, rgt, (rgt - lft), (rgt - lft + 1), parent_id 
		  INTO new_lft, new_rgt, has_leafs, width, superior_parent 
		  FROM wp_hierarchy WHERE ID = pID;

		DELETE FROM wp_hierarchy WHERE ID = pID;

        IF (has_leafs = 1) THEN
          DELETE FROM wp_hierarchy WHERE lft BETWEEN new_lft AND new_rgt;
          UPDATE wp_hierarchy SET rgt = rgt - width WHERE rgt > new_rgt;
          UPDATE wp_hierarchy SET lft = lft - width WHERE lft > new_rgt;
        ELSE
          DELETE FROM wp_hierarchy WHERE lft = new_lft;
          UPDATE wp_hierarchy SET rgt = rgt - 1, lft = lft - 1, parent_id = superior_parent 
		   WHERE lft BETWEEN new_lft AND new_rgt;
          UPDATE wp_hierarchy SET rgt = rgt - 2 WHERE rgt > new_rgt;
          UPDATE wp_hierarchy SET lft = lft - 2 WHERE lft > new_rgt;
        END IF;

    WHEN 'move' THEN
    
		IF (pID != pparent_id) THEN
        CREATE TEMPORARY TABLE IF NOT EXISTS working_wp_hierarchy
        (
          `ID` smallint(5) unsigned NOT NULL AUTO_INCREMENT,
          `workPlaceID` varchar(245) DEFAULT NULL,
          `lft` smallint(5) unsigned DEFAULT NULL,
          `rgt` smallint(5) unsigned DEFAULT NULL,
          `parent_id` smallint(5) unsigned NOT NULL,
          PRIMARY KEY (`ID`)
        );
        
		
			 SELECT t1.ID, 
					t1.workPlaceID,
					(t1.lft - (SELECT MIN(lft) FROM wp_hierarchy WHERE ID = pID)) AS lft,
					(t1.rgt - (SELECT MIN(lft) FROM wp_hierarchy WHERE ID = pID)) AS rgt,
					t1.parent_id
			   FROM wp_hierarchy AS t1, wp_hierarchy AS t2
			  WHERE t1.lft BETWEEN t2.lft AND t2.rgt 
				AND t2.ID = pID;

        DELETE FROM wp_hierarchy WHERE ID IN (SELECT ID FROM working_wp_hierarchy);

        SELECT rgt INTO parent_rgt FROM wp_hierarchy WHERE ID = pparent_id;
        SET subtree_size = (SELECT (MAX(rgt) + 1) FROM working_wp_hierarchy);
		
		
        UPDATE wp_hierarchy
          SET lft = (CASE WHEN lft > parent_rgt THEN lft + subtree_size ELSE lft END),
              rgt = (CASE WHEN rgt >= parent_rgt THEN rgt + subtree_size ELSE rgt END)
        WHERE rgt >= parent_rgt;

             SELECT ID, workPlaceID, lft + parent_rgt, rgt + parent_rgt, parent_id
               FROM working_wp_hierarchy;
        
		
        UPDATE wp_hierarchy
           SET lft = (SELECT COUNT(*) FROM vw_lftrgt AS v WHERE v.lft <= wp_hierarchy.lft),
               rgt = (SELECT COUNT(*) FROM vw_lftrgt AS v WHERE v.lft <= wp_hierarchy.rgt);
        
        DELETE FROM working_wp_hierarchy;
        UPDATE wp_hierarchy SET parent_id = pparent_id WHERE ID = pID;
		END IF;
        
        
    WHEN 'copyx' THEN
    
		IF (pID != pparent_id) THEN
        CREATE TEMPORARY TABLE IF NOT EXISTS working_wp_hierarchy
        (
          `ID` smallint(5) unsigned NOT NULL AUTO_INCREMENT,
          `workPlaceID` varchar(245) DEFAULT NULL,
          `lft` smallint(5) unsigned DEFAULT NULL,
          `rgt` smallint(5) unsigned DEFAULT NULL,
          `parent_id` smallint(5) unsigned NOT NULL,
          PRIMARY KEY (`ID`)
        );
        
		
               
                
			 SELECT t1.workPlaceID,
					(t1.lft - (SELECT MIN(lft) FROM wp_hierarchy WHERE ID = pID)) AS lft,
					(t1.rgt - (SELECT MIN(lft) FROM wp_hierarchy WHERE ID = pID)) AS rgt,
					t1.parent_id
			   FROM wp_hierarchy AS t1, wp_hierarchy AS t2
			  WHERE t1.lft BETWEEN t2.lft AND t2.rgt 
				AND t2.ID = pID;
        
        

        

        SELECT rgt INTO parent_rgt FROM wp_hierarchy WHERE ID = pparent_id;
        SET subtree_size = (SELECT (MAX(rgt) + 1) FROM working_wp_hierarchy);
		
		
        UPDATE wp_hierarchy
          SET lft = (CASE WHEN lft > parent_rgt THEN lft + subtree_size ELSE lft END),
              rgt = (CASE WHEN rgt >= parent_rgt THEN rgt + subtree_size ELSE rgt END)
        WHERE rgt >= parent_rgt;

               
               
             SELECT workPlaceID, lft + parent_rgt, rgt + parent_rgt, parent_id
               FROM working_wp_hierarchy;
        SET lastCopyxID = LAST_INSERT_ID();
		
        UPDATE wp_hierarchy
           SET lft = (SELECT COUNT(*) FROM vw_lftrgt AS v WHERE v.lft <= wp_hierarchy.lft),
               rgt = (SELECT COUNT(*) FROM vw_lftrgt AS v WHERE v.lft <= wp_hierarchy.rgt);
        
        DELETE FROM working_wp_hierarchy;
        
        UPDATE wp_hierarchy SET parent_id = pparent_id WHERE ID = lastCopyxID;
		END IF;    

    WHEN 'order' THEN

        SELECT lft, rgt, (rgt - lft + 1), parent_id INTO old_lft, old_rgt, width, superior
          FROM wp_hierarchy WHERE ID = pID;

        
        SELECT parent_id INTO superior_parent FROM wp_hierarchy WHERE ID = pparent_id;

        IF (superior = superior_parent) THEN
          SELECT (rgt + 1) INTO new_lft FROM wp_hierarchy WHERE ID = pparent_id;
        ELSE
          SELECT (lft + 1) INTO new_lft FROM wp_hierarchy WHERE ID = pparent_id;
        END IF;

	    IF (new_lft != old_lft) THEN
		  CREATE TEMPORARY TABLE IF NOT EXISTS working_wp_hierarchy
        (
          `ID` smallint(5) unsigned NOT NULL AUTO_INCREMENT,
          `workPlaceID` varchar(245) DEFAULT NULL,
          `lft` smallint(5) unsigned DEFAULT NULL,
          `rgt` smallint(5) unsigned DEFAULT NULL,
          `parent_id` smallint(5) unsigned NOT NULL,
          PRIMARY KEY (`ID`)
        );

            SELECT t1.ID,
					t1.workPlaceID,
			  	   (t1.lft - (SELECT MIN(lft) FROM wp_hierarchy WHERE ID = pID)) AS lft,
				   (t1.rgt - (SELECT MIN(lft) FROM wp_hierarchy WHERE ID = pID)) AS rgt,
				   t1.parent_id
			  FROM wp_hierarchy AS t1, wp_hierarchy AS t2
			 WHERE t1.lft BETWEEN t2.lft AND t2.rgt AND t2.ID = pID;
            
       DELETE FROM wp_hierarchy WHERE ID IN (SELECT ID FROM working_wp_hierarchy);

       IF(new_lft < old_lft) THEN 
          UPDATE wp_hierarchy SET lft = lft + width WHERE lft >= new_lft AND lft < old_lft;
          UPDATE wp_hierarchy SET rgt = rgt + width WHERE rgt > new_lft AND rgt < old_rgt;
          UPDATE working_wp_hierarchy SET lft = new_lft + lft, rgt = new_lft + rgt;
       END IF;

       IF(new_lft > old_lft) THEN 
            UPDATE wp_hierarchy SET lft = lft - width WHERE lft > old_lft AND lft < new_lft;
            UPDATE wp_hierarchy SET rgt = rgt - width WHERE rgt > old_rgt AND rgt < new_lft;
            UPDATE working_wp_hierarchy SET lft = (new_lft - width) + lft, rgt = (new_lft - width) + rgt;
       END IF;

            SELECT ID, workPlaceID, lft, rgt, parent_id
              FROM working_wp_hierarchy;
            
       DELETE FROM working_wp_hierarchy;
	   END IF;
  END CASE;

END
;;
