-- ----------------------------
-- Triggers structure for table employee_has_document
-- ----------------------------
DROP TRIGGER IF EXISTS `insert_check_empl`;
delimiter ;;
CREATE TRIGGER `insert_check_empl` AFTER INSERT ON `employee_has_document` FOR EACH ROW BEGIN
		DECLARE permView INT default 0;
        DECLARE permEdit INT default 0;
        DECLARE permDeny INT default 0;
        DECLARE employeeCurrentName CHAR(245) CHARACTER SET utf8;       	
       	DECLARE owners INT; 
       	DECLARE ownerSet INT default 0; 

		IF (new.permissionWrite = 0 and new.permissionDeny = 0) THEN
			SET permView = 1;
            SET permEdit = 0;
            SET permDeny = 0;
        END IF;
        IF (new.permissionWrite = 1 and new.permissionDeny = 0) THEN
			SET permView = 0;
            SET permEdit = 1;
            SET permDeny = 0;
        END IF;
        IF (new.permissionWrite = 0 and new.permissionDeny = 1) THEN
			SET permView = 0;
            SET permEdit = 0;
            SET permDeny = 1;
        END IF;        

        SET employeeCurrentName = (SELECT CONCAT(employee.firstname, ' ', employee.lastname) as employeeName
        FROM employee WHERE employee.ID = new.employeeID);       
       	
		SET owners = (SELECT documentID FROM document_has_owner WHERE documentID = new.documentID AND employeeID = new.employeeID);		
		
		if (owners IS NOT NULL) THEN
			SET ownerSet = 1;
		END IF;
        

        objectType, objectID, objectName,
        permissionView, permissionEdit, permissionDeny, owner) 
        VALUES (NOW(), "insert", new.documentID,
        "empl", new.employeeID, employeeCurrentName, permView, permEdit, permDeny, ownerSet); 
    END
;;
delimiter ;

