-- ----------------------------
-- Triggers structure for table employee_has_document
-- ----------------------------
DROP TRIGGER IF EXISTS `delete_check_empl`;
delimiter ;;
CREATE TRIGGER `delete_check_empl` AFTER DELETE ON `employee_has_document` FOR EACH ROW BEGIN
		DECLARE permView INT default 0;
        DECLARE permEdit INT default 0;
        DECLARE permDeny INT default 0;
        DECLARE eventTime TIMESTAMP default NOW();
        DECLARE employeeCurrentName CHAR(245) CHARACTER SET utf8;       
       	DECLARE owners INT; 
       	DECLARE ownerSet INT default 0; 

		IF (old.permissionWrite = 0 and old.permissionDeny = 0) THEN
			SET permView = 1;
            SET permEdit = 0;
            SET permDeny = 0;
        END IF;
        IF (old.permissionWrite = 1 and old.permissionDeny = 0) THEN
			SET permView = 0;
            SET permEdit = 1;
            SET permDeny = 0;
        END IF;
        IF (old.permissionWrite = 0 and old.permissionDeny = 1) THEN
			SET permView = 0;
            SET permEdit = 0;
            SET permDeny = 1;
        END IF;

        IF (old.expireDate IS NOT NULL) THEN
			SET eventTime = CONCAT(old.expireDate, ' 00:00:01');
        END IF;        

        SET employeeCurrentName = (SELECT CONCAT(employee.firstname, ' ', employee.lastname) as employeeName
        FROM employee WHERE employee.ID = old.employeeID);       
       	
		SET owners = (SELECT documentID FROM document_has_owner WHERE documentID = old.documentID AND employeeID = old.employeeID);		
		
		if (owners IS NOT NULL) THEN
			SET ownerSet = 1;
		END IF;        

        objectType, objectID, objectName,
        permissionView, permissionEdit, permissionDeny, owner)
        VALUES (eventTime, "delete", old.documentID,
        "empl", old.employeeID, employeeCurrentName, permView, permEdit, permDeny, ownerSet);        

    END
;;
delimiter ;

-- ----------------------------
-- Triggers structure for table events_application
-- ----------------------------
DROP TRIGGER IF EXISTS `update_app_fields_contact`;
delimiter ;;
CREATE TRIGGER `update_app_fields_contact` AFTER UPDATE ON `events_application` FOR EACH ROW BEGIN    
    UPDATE events_application_fields AS af
    JOIN events_fields AS f ON af.id_field = f.id
    SET af.field_value = NEW.contact_person
    WHERE f.id_predefined = 1     
      AND af.id_application = NEW.id;
