-- ----------------------------
-- Triggers structure for table structure_has_document
-- ----------------------------
DROP TRIGGER IF EXISTS `insert_check`;
delimiter ;;
CREATE TRIGGER `insert_check` AFTER INSERT ON `structure_has_document` FOR EACH ROW BEGIN
		DECLARE permView INT default 0;
        DECLARE permEdit INT default 0;
        DECLARE permDeny INT default 0;
        DECLARE objectName CHAR(245) CHARACTER SET utf8;
        DECLARE structureParentList CHAR(245) CHARACTER SET utf8;
    
		IF (new.permissionWrite = 0 and new.permissionDeny = 0) THEN
			SET permView = 1;
            SET permEdit = 0;
            SET permDeny = 0;
        END IF;
        IF (new.permissionWrite = 1 and new.permissionDeny = 0) THEN
			SET permView = 0;
            SET permEdit = 1;
            SET permDeny = 0;
        END IF;
        IF (new.permissionWrite = 0 and new.permissionDeny = 1) THEN
			SET permView = 0;
            SET permEdit = 0;
            SET permDeny = 1;
        END IF;
        
        SET objectName = (SELECT structure_object.objectName FROM structure_object
        LEFT JOIN structure ON (structure_object.ID = structure.objectID)
        WHERE structure.ID = new.structureID);
        
        SET structureParentlist = (SELECT GROUP_CONCAT(structure_object.objectName SEPARATOR ' / ')
		FROM structure AS node,
        structure AS parent
		LEFT JOIN structure_object ON (parent.objectID = structure_object.ID)
		WHERE node.lft BETWEEN parent.lft AND parent.rgt
        AND node.id = new.structureID
		ORDER BY parent.lft);
        
        objectType, objectID, objectName,
        objectParentList,
        permissionView, permissionEdit, permissionDeny)
        VALUES (NOW(), "insert", new.documentID,
        "object", new.structureID, objectName, structureParentlist,
        permView, permEdit, permDeny);
        
    END
;;
delimiter ;

