-- ----------------------------
-- Triggers structure for table structure_has_document
-- ----------------------------
DROP TRIGGER IF EXISTS `delete_check`;
delimiter ;;
CREATE TRIGGER `delete_check` AFTER DELETE ON `structure_has_document` FOR EACH ROW BEGIN
		DECLARE permView INT default 0;
        DECLARE permEdit INT default 0;
        DECLARE permDeny INT default 0;
        DECLARE objectName CHAR(245) CHARACTER SET utf8;
        DECLARE eventTime TIMESTAMP default NOW();
        DECLARE structureParentList CHAR(245) CHARACTER SET utf8;
    
		IF (old.permissionWrite = 0 and old.permissionDeny = 0) THEN
			SET permView = 1;
            SET permEdit = 0;
            SET permDeny = 0;
        END IF;
        IF (old.permissionWrite = 1 and old.permissionDeny = 0) THEN
			SET permView = 0;
            SET permEdit = 1;
            SET permDeny = 0;
        END IF;
        IF (old.permissionWrite = 0 and old.permissionDeny = 1) THEN
			SET permView = 0;
            SET permEdit = 0;
            SET permDeny = 1;
        END IF;
        IF (old.expireDate IS NOT NULL) THEN
			SET eventTime = CONCAT(old.expireDate, ' 00:00:01');
        END IF;
        
        SET objectName = (SELECT structure_object.objectName FROM structure_object
        LEFT JOIN structure ON (structure_object.ID = structure.objectID)
        WHERE structure.ID = old.structureID);
        
        SET structureParentlist = (SELECT GROUP_CONCAT(structure_object.objectName SEPARATOR ' / ')
		FROM structure AS node,
        structure AS parent
		LEFT JOIN structure_object ON (parent.objectID = structure_object.ID)
		WHERE node.lft BETWEEN parent.lft AND parent.rgt
        AND node.id = old.structureID
		ORDER BY parent.lft);
        
        objectType, objectID, objectName,
        objectParentList,
        permissionView, permissionEdit, permissionDeny)
        VALUES (eventTime, "delete", old.documentID,
        "object", old.structureID, objectName, structureParentlist,
        permView, permEdit, permDeny);
        
    END
;;
delimiter ;

