CREATE TABLE tkt_channels (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(255) NOT NULL UNIQUE,
    api_key VARCHAR(555) UNIQUE DEFAULT NULL,
    api_url VARCHAR(555) DEFAULT NULL,
    url VARCHAR(555) UNIQUE DEFAULT NULL,
    description TEXT DEFAULT NUll,
    default_priority_id BIGINT DEFAULT NULL,
    email_on_create TEXT DEFAULT NULL,
    email_on_response TEXT DEFAULT NULL,
    notify_agents TINYINT(1) DEFAULT NULL,
    notify_admins TINYINT(1) DEFAULT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (default_priority_id) REFERENCES tkt_ticket_priorities(id) ON DELETE SET NULL
) COLLATE='utf8mb4_general_ci' ENGINE=InnoDB;

CREATE TABLE tkt_channel_origins (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    domain VARCHAR(255),
    channel_id BIGINT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (channel_id) REFERENCES tkt_channels(id) ON DELETE CASCADE
) COLLATE='utf8mb4_general_ci' ENGINE=InnoDB;

CREATE TABLE tkt_channel_servers (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    ip VARCHAR(255),
    channel_id BIGINT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, 
    FOREIGN KEY (channel_id) REFERENCES tkt_channels(id) ON DELETE CASCADE
) COLLATE='utf8mb4_general_ci' ENGINE=InnoDB;

