    password VARCHAR(255) DEFAULT NULL,
    remember_token VARCHAR(255) DEFAULT NULL, 
    external_id VARCHAR(255),
    channel_id BIGINT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (channel_id) REFERENCES tkt_channels(id) ON DELETE CASCADE,
    INDEX idx_external_id (external_id)
) COLLATE='utf8mb4_general_ci' ENGINE=InnoDB;

CREATE TABLE tkt_channel_user (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    channel_id BIGINT NOT NULL,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (channel_id) REFERENCES tkt_channels(id) ON DELETE CASCADE,
    UNIQUE (user_id, channel_id) 
) COLLATE='utf8mb4_general_ci' ENGINE=InnoDB;

CREATE TABLE tkt_ticket_statuses (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    color VARCHAR(255) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) COLLATE='utf8mb4_general_ci' ENGINE=INNODB;

CREATE TABLE tkt_channel_ticket_status (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    channel_id BIGINT NOT NULL,
    ticket_status_id BIGINT NOT NULL,
    is_default_ticket BOOLEAN DEFAULT FALSE,
    is_default_response BOOLEAN DEFAULT FALSE,
    is_default_closed BOOLEAN DEFAULT FALSE,
    is_default_assign BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (channel_id) REFERENCES tkt_channels(id) ON DELETE CASCADE,
    FOREIGN KEY (ticket_status_id) REFERENCES tkt_ticket_statuses(id) ON DELETE CASCADE
) COLLATE='utf8mb4_general_ci' ENGINE=INNODB;

CREATE TABLE tkt_groups (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(255) NOT NULL UNIQUE,
    description TEXT DEFAULT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) COLLATE='utf8mb4_general_ci' ENGINE=InnoDB;

CREATE TABLE tkt_channel_group (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    group_id BIGINT NOT NULL,
    channel_id BIGINT NOT NULL,
    FOREIGN KEY (group_id) REFERENCES tkt_groups(id) ON DELETE CASCADE,
    FOREIGN KEY (channel_id) REFERENCES tkt_channels(id) ON DELETE CASCADE,
    UNIQUE (group_id, channel_id) 
) COLLATE='utf8mb4_general_ci' ENGINE=InnoDB;

CREATE TABLE tkt_user_group (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    group_id BIGINT NOT NULL,
    user_id INT NOT NULL,
    FOREIGN KEY (group_id) REFERENCES tkt_groups(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    UNIQUE (group_id, user_id) 
) COLLATE='utf8mb4_general_ci' ENGINE=InnoDB;

CREATE TABLE tkt_tickets (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    customer_name VARCHAR(255) NOT NULL,
    subject VARCHAR(255) NOT NULL,
    description TEXT,
    priority_id BIGINT DEFAULT NULL, 
    customer_id BIGINT NOT NULL,
    user_id INT DEFAULT NULL,
    group_id BIGINT DEFAULT NULL, 
    channel_id BIGINT DEFAULT NULL,
    external_id VARCHAR(255),
    source VARCHAR(255) DEFAULT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (customer_id) REFERENCES tkt_customers(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY (group_id) REFERENCES tkt_groups(id) ON DELETE SET NULL,
    FOREIGN KEY (channel_id) REFERENCES tkt_channels(id) ON DELETE CASCADE,
    FOREIGN KEY (priority_id) REFERENCES tkt_ticket_priorities(id) ON DELETE SET NULL,
    INDEX idx_external_id (external_id)
) COLLATE='utf8mb4_general_ci' ENGINE=InnoDB; 

CREATE TABLE tkt_ticket_responses (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    ticket_id BIGINT NOT NULL, 
    customer_id BIGINT DEFAULT NULL,
    user_id INT DEFAULT NULL, 
    response TEXT NOT NULL,
    response_type ENUM('public', 'private') DEFAULT 'public',
    send_notification BIGINT DEFAULT NULL, 
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (ticket_id) REFERENCES tkt_tickets(id) ON DELETE CASCADE,
    FOREIGN KEY (customer_id) REFERENCES tkt_customers(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) COLLATE='utf8mb4_general_ci' ENGINE=InnoDB;

CREATE TABLE tkt_ticket_attachments (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    ticket_id BIGINT DEFAULT NULL, 
    response_id BIGINT DEFAULT NULL,
    file_path VARCHAR(255) NOT NULL,
    file_name VARCHAR(255) NOT NULL, 
    customer_id BIGINT DEFAULT NULL, 
    user_id INT DEFAULT NULL, 
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (ticket_id) REFERENCES tkt_tickets(id) ON DELETE CASCADE,
    FOREIGN KEY (response_id) REFERENCES tkt_ticket_responses(id) ON DELETE CASCADE,
    FOREIGN KEY (customer_id) REFERENCES tkt_customers(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
) COLLATE='utf8mb4_general_ci' ENGINE=InnoDB;

CREATE TABLE tkt_status_ticket (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    ticket_id BIGINT DEFAULT NULL,
    status_id BIGINT DEFAULT NULL,
    FOREIGN KEY (ticket_id) REFERENCES tkt_tickets(id) ON DELETE CASCADE,
    FOREIGN KEY (status_id) REFERENCES tkt_ticket_statuses(id) ON DELETE CASCADE
) COLLATE='utf8mb4_general_ci' ENGINE=InnoDB;

CREATE TABLE tkt_status_response (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    response_id BIGINT DEFAULT NULL,
    status_id BIGINT DEFAULT NULL,
    FOREIGN KEY (response_id) REFERENCES tkt_ticket_responses(id) ON DELETE CASCADE,
    FOREIGN KEY (status_id) REFERENCES tkt_ticket_statuses(id) ON DELETE CASCADE
) COLLATE='utf8mb4_general_ci' ENGINE=InnoDB;

