	INDEX ( `created_at` ),
	INDEX ( `updated_at` ),
	INDEX ( `deleted_at` ),
CONSTRAINT `fk_post_category` FOREIGN KEY ( `category_id` ) REFERENCES `forum_categories` ( `category_id` ) 
) ENGINE = INNODB CHARSET = utf8 COLLATE utf8_unicode_ci;

CREATE TABLE `forum_post_files` (
