CREATE TABLE IF NOT EXISTS `zahtevi_placanja` (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `idFakture` int(11) DEFAULT 0,
  `datumZahteva` timestamp NOT NULL DEFAULT current_timestamp(),
  `opis` varchar(50) COLLATE utf8_unicode_ci DEFAULT '',
  `tipDokumenta` varchar(50) COLLATE utf8_unicode_ci DEFAULT '',
  `datumDokumenta` timestamp NULL DEFAULT NULL,
  `datumRealizacije` timestamp NULL DEFAULT NULL,
  `naziv` varchar(50) COLLATE utf8_unicode_ci NOT NULL,
  `proceduraID` int(11) NOT NULL,
  `status_odobrenje` int(11) DEFAULT NULL,
  `kreatorID` int(11) DEFAULT NULL,
  `korak_broj` int(11) DEFAULT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=14 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
 
CREATE TABLE IF NOT EXISTS `zahtevi_placanja_iznos` (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `zahtevID` int(11) NOT NULL DEFAULT 0,
  `iznos` decimal(13,2) NOT NULL DEFAULT 0.00,
  `datum` datetime DEFAULT NULL,
  `korakID` int(11) NOT NULL,
  `korakBroj` int(11) NOT NULL,
  `uplaceno` decimal(13,2) NOT NULL,
  PRIMARY KEY (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;
 
CREATE TABLE IF NOT EXISTS `odobrenje_proces_odobravanja_zahtev_placanja` (
  `ID` int(11) NOT NULL AUTO_INCREMENT,
  `ProcedureID` int(11) NOT NULL,
  `EmployeeID` int(11) NOT NULL,
  `EmployeeName` varchar(245) NOT NULL,
  `zahtevID` int(11) NOT NULL,
  `Status` enum('Approved','Rejected','AutoApproved','AutoRejected','Returned') NOT NULL,
  `Comment` text DEFAULT NULL,
  `IsActive` int(11) NOT NULL DEFAULT 1,
  `CreatedAt` timestamp NOT NULL DEFAULT current_timestamp(),
  `korakID` int(11) DEFAULT NULL,
  `OdobrenjeID` int(11) DEFAULT NULL,
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
 
 
CREATE TABLE IF NOT EXISTS `odobrenje_poslato_zahtev_placanja` (
  `ID` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `kreatorID` int(11) NOT NULL,
  `proceduraID` int(11) NOT NULL,
  `zahtevID` int(11) NOT NULL,
