  `Changing` enum('Y','N') DEFAULT 'Y',
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
 
 
CREATE TABLE IF NOT EXISTS `odobrenje_istorija_odobravanja_zahtev_placanja` (
  `ID` int(10) NOT NULL AUTO_INCREMENT,
  `ProcedureID` int(10) NOT NULL,
  `EmployeeID` int(10) NOT NULL,
  `EmployeeName` varchar(245) NOT NULL,
  `zahtevID` int(10) NOT NULL,
  `korakID` int(10) DEFAULT NULL,
  `OdobrenjeID` int(10) DEFAULT NULL,
  `Status` enum('Approved','Rejected','AutoApproved','AutoRejected','Returned') NOT NULL,
  `Comment` text DEFAULT NULL,
  `IsActive` int(10) NOT NULL DEFAULT 1,
  `CreatedAt` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`ID`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=18 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;

CREATE TABLE `notes_categories` (
	`category_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
	`parent_id` BIGINT UNSIGNED NULL,
	`name` VARCHAR ( 255 ) NOT NULL,
	`path` TEXT NULL,
	`_lft` BIGINT UNSIGNED NOT NULL,
	`_rgt` BIGINT UNSIGNED NOT NULL,
	`created_by` INT UNSIGNED NOT NULL,
	`updated_by` INT UNSIGNED NULL,
	`deleted_by` INT UNSIGNED NULL,
	`created_at` DATETIME NOT NULL,
	`updated_at` DATETIME NULL,
	`deleted_at` DATETIME NULL,
	PRIMARY KEY ( `category_id` ),
	INDEX ( `parent_id` ),
	INDEX ( `_lft` ),
	INDEX ( `_rgt` ),
	INDEX ( `_lft`, `_rgt` ),
	INDEX ( `created_by` ),
	INDEX ( `updated_by` ),
	INDEX ( `deleted_by` ),
	INDEX ( `created_at` ),
	INDEX ( `updated_at` ),
	INDEX ( `deleted_at` ),
CONSTRAINT `fk_notes_category_parent` FOREIGN KEY ( `parent_id` ) REFERENCES `notes_categories` ( `category_id` ) 
) ENGINE = INNODB CHARSET = utf8 COLLATE utf8_unicode_ci;

CREATE TABLE `notes_posts` (
    `post_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `category_id` BIGINT UNSIGNED UNSIGNED NOT NULL,
    `title` VARCHAR(255) NOT NULL,
    `content` TEXT NOT NULL,
    `has_files` TINYINT NOT NULL,
    `created_by` INT UNSIGNED NOT NULL,
    `updated_by` INT UNSIGNED NULL,
    `deleted_by` INT UNSIGNED NULL,
    `created_at` DATETIME NOT NULL,
    `updated_at` DATETIME NULL,
    `deleted_at` DATETIME NULL,
    PRIMARY KEY (`post_id`),
    INDEX (`category_id`),
    INDEX (`has_files`),
    INDEX (`created_by`),
    INDEX (`updated_by`),
    INDEX (`deleted_by`),
    INDEX (`created_at`),
    INDEX (`updated_at`),
    INDEX (`deleted_at`),
    CONSTRAINT `fk_notes_post_category` FOREIGN KEY (`category_id`) REFERENCES `notes_categories` (`category_id`)
) ENGINE = InnoDB CHARSET = utf8 COLLATE utf8_unicode_ci;

CREATE TABLE `notes_post_files` (
	`file_id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
	`post_id` BIGINT UNSIGNED NOT NULL,
	`name` VARCHAR ( 255 ) NOT NULL,
	`storage_path` VARCHAR ( 255 ) NOT NULL,
	`mime_type` VARCHAR ( 255 ) NOT NULL,
	`size` INT UNSIGNED NOT NULL,
	PRIMARY KEY ( `file_id` ),
	INDEX ( `post_id` ),
	INDEX ( `mime_type` ),
	INDEX ( `size` ),
CONSTRAINT `fk_notes_file_post` FOREIGN KEY ( `post_id` ) REFERENCES `notes_posts` ( `post_id` ) 
) ENGINE = INNODB CHARSET = utf8 COLLATE utf8_unicode_ci;

CREATE TABLE `notes_favorite_posts` (
	`employee_id` INT NOT NULL,
	`post_id` BIGINT UNSIGNED NOT NULL,
	`created_at` TIMESTAMP NOT NULL,
	PRIMARY KEY ( `employee_id`, `post_id` ),
	INDEX ( `created_at` ),
CONSTRAINT `fk_notes_favorite_post` FOREIGN KEY ( `post_id` ) REFERENCES `notes_posts` ( `post_id` ) 
) ENGINE = INNODB CHARSET = utf8 COLLATE utf8_unicode_ci;

CREATE TABLE `notes_post_visibility` (
	`post_id` BIGINT UNSIGNED NOT NULL,
	`employee_id` INT NOT NULL,
	PRIMARY KEY ( `post_id`, `employee_id` ),
CONSTRAINT `fk_notes_visibility_post` FOREIGN KEY ( `post_id` ) REFERENCES `notes_posts` ( `post_id` ) 
) ENGINE = INNODB CHARSET = utf8 COLLATE utf8_unicode_ci;

CREATE TABLE `notes_post_comments` (
	`comment_id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
	`post_id` BIGINT UNSIGNED NOT NULL,
	`employee_id` INT NOT NULL,
	`content` TEXT NOT NULL,
	`created_at` DATETIME NOT NULL,
	`updated_at` DATETIME NULL,
