CREATE TABLE delovodnik_email_accounts (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  email VARCHAR(355) NOT NULL,
  delovodnik_id INT UNSIGNED NOT NUll,
  employee_id INT NOT NULL,
  folder_id INT DEFAULT NULL,
  archival_material_id INT DEFAULT NULL,
  izvorni_format_id INT DEFAULT NULL,
  izvorni_format_papirni_tip VARCHAR(255) DEFAULT NULL,
  document_signature_date DATE DEFAULT NULL,
 
  imap_host VARCHAR(255) DEFAULT NULL,
  imap_port VARCHAR(255) DEFAULT NULL,
  imap_encryption VARCHAR(255) DEFAULT NULL,
  imap_username VARCHAR(255) DEFAULT NULL,
  imap_password TEXT DEFAULT NULL,
  imap_last_fetched_at TIMESTAMP NULL DEFAULT NULL,
  imap_message_last_uid VARCHAR(255) DEFAULT NULL,
  status ENUM( 'fetch_pending', 'fetch_processing', 'fetch_error', 'delete_pending', 'delete_processing', 'delete_error', 'active', 'inactive' ) DEFAULT 'active',
  imap_last_error TEXT DEFAULT NULL,
 
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP NULL DEFAULT NULL,
 
  CONSTRAINT fk_delovodnik_email
    FOREIGN KEY (delovodnik_id) REFERENCES delovodnik(ID) ON DELETE CASCADE,
  CONSTRAINT fk_employee_owner
    FOREIGN KEY (employee_id) REFERENCES employee(ID) ON DELETE CASCADE,
  CONSTRAINT fk_folder_email
    FOREIGN KEY (folder_id) REFERENCES d_folder(ID) ON DELETE SET NULL
 
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
 
CREATE TABLE delovodnik_email_document_type (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  email_id BIGINT NOT NULL,
  document_type_id INT NOT NULL,
 
  CONSTRAINT fk_del_email_document_type
    FOREIGN KEY (email_id) REFERENCES delovodnik_email_accounts(id) ON DELETE CASCADE,
  CONSTRAINT fk_del_document_type
    FOREIGN KEY (document_type_id) REFERENCES document_type(ID) ON DELETE CASCADE
 
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
 
CREATE TABLE delovodnik_email_document_addresses (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  email_id BIGINT NOT NULL,
  addressable_id BIGINT NOT NULL,
  addressable_type VARCHAR(50) NOT NULL COMMENT 'company ili contact_personal',
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 
  CONSTRAINT fk_del_email_document_addresses FOREIGN KEY (email_id)
      REFERENCES delovodnik_email_accounts(id) ON DELETE CASCADE
 
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
 
CREATE TABLE delovodnik_email_messages (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  email_account_id BIGINT NOT NULL,
  uid VARCHAR(150) NOT NULL,
  subject VARCHAR(255) NOT NULL,
  from_address VARCHAR(255) NULL,
  in_reply_to VARCHAR(512) NULL,      
  received_at DATETIME NULL,
  folder VARCHAR(255) NULL,
  status ENUM('pending', 'processing', 'failed', 'created') DEFAULT 'pending' COMMENT 'pending - ceka pregled, processing - u fazi kreiranja dokumenta, failed - neuspesno kreiran dokument, created - kreiran dokument',
  last_error TEXT DEFAULT NULL,
  archival_material_id INT DEFAULT NULL,
  delovodnik_id INT UNSIGNED NOT NUll,
  document_id INT DEFAULT NULL COMMENT 'ID kreiranog dokumneta',
  created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted_at TIMESTAMP NULL DEFAULT NULL,
 
  CONSTRAINT fk_email_account FOREIGN KEY (email_account_id) REFERENCES delovodnik_email_accounts(id)
 
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
 
CREATE TABLE delovodnik_email_attachments (
  id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  email_message_id BIGINT UNSIGNED NOT NULL,
  filename VARCHAR(500) NOT NULL,
  mime_type VARCHAR(255) NULL,
  size BIGINT UNSIGNED NULL,
  downloaded TINYINT(1) DEFAULT 0 COMMENT '0 = nije skinut, 1 = skinut prilikom zavodjenja',
  path VARCHAR(1000) NULL COMMENT 'putanja kad se fajl snimi lokalno',
  is_selected TINYINT(1) DEFAULT 0 COMMENT 'selektovano za zavodjenje',
  created_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 
  CONSTRAINT fk_email_attachment FOREIGN KEY (email_message_id) REFERENCES delovodnik_email_messages(id) ON DELETE CASCADE
 
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


