CREATE TABLE `despatch_advices_additional_columns` (
	`id` INT(10) UNSIGNED NOT NULL AUTO_INCREMENT,
	`table_name` VARCHAR(50) NOT NULL DEFAULT '0' COLLATE 'utf8mb3_general_ci',
	`column_name` VARCHAR(50) NOT NULL DEFAULT '0' COLLATE 'utf8mb3_general_ci',
	`column_translation` VARCHAR(50) NOT NULL DEFAULT '0' COLLATE 'utf8mb3_general_ci',
	`UserID` INT(10) NOT NULL,
	`is_checked` TINYINT(3) NOT NULL DEFAULT '0',
	`created_at` timestamp(0) NULL DEFAULT CURRENT_TIMESTAMP(0),
   `updated_at` timestamp(0) NULL DEFAULT CURRENT_TIMESTAMP(0),
	PRIMARY KEY (`ID`) USING BTREE
)
COLLATE='utf8mb3_general_ci'
ENGINE=InnoDB;

