ALTER TABLE `obr_filled_templates` ADD `signed` TINYINT ( 1 ) DEFAULT 0 AFTER archived;

CREATE TABLE `obr_signed_filled_templates` (
	`id` INT ( 11 ) NOT NULL AUTO_INCREMENT,
	`filled_template_id` INT ( 11 ) NOT NULL,
	`user_id` INT ( 11 ) NOT NULL,
	`file_path` VARCHAR ( 256 ) NOT NULL,
	`created_at` DATETIME NOT NULL,
	`updated_at` DATETIME NOT NULL,
	PRIMARY KEY ( `id` ),
	CONSTRAINT `fk_signed_filled_template_id` FOREIGN KEY ( `filled_template_id` ) REFERENCES obr_filled_templates ( `id` ) ON DELETE CASCADE,
CONSTRAINT `fk_sft_user_id` FOREIGN KEY ( `user_id` ) REFERENCES employee ( `ID` ) ON DELETE CASCADE 
) COLLATE = 'utf8_unicode_ci' ENGINE = INNODB;

